def _diag(msg):
    if DIAG_STARTUP:
        print(f"[DIAG] {(time.time() - _DIAG_T0) * 1000:7.0f} ms  {msg}")


def _get_transit_dir(config):
    """Cartella di transito prima del cestino: configurabile via
    config['trash_transit_dir'], altrimenti il default sotto ~/.local/share."""
    d = (config.get("trash_transit_dir") or "").strip()
    return d if d else TRASH_TRANSIT_DIR


def _transit_limit_bytes(config):
    mb = config.get("trash_transit_limit_mb", TRASH_TRANSIT_LIMIT_MB_DEFAULT)
    try:
        mb = max(50, int(mb))
    except (TypeError, ValueError):
        mb = TRASH_TRANSIT_LIMIT_MB_DEFAULT
    return mb * 1024 * 1024


def _transit_clean_history_entries(sent_paths):
    """Rimuove dallo storico persistente le entry 'trashed_transit' i cui
    file sono stati davvero inviati al cestino di sistema (altrimenti
    resterebbero a puntare a file non più presenti in transito)."""
    if not sent_paths:
        return
    try:
        entries = load_history()
        entries = [e for e in entries
                   if not (e.get("action") == "trashed_transit"
                           and e.get("dest") in sent_paths)]
        save_history(entries)
    except Exception:
        pass


def move_to_transit(filepath, config):
    """Sposta un file nella cartella di transito invece di cestinarlo subito.
    Ritorna il percorso di destinazione, o None in caso di errore.
    I file restano lì finché l'utente non conferma di svuotarla (a fine
    sessione, o manualmente), momento in cui vengono davvero inviati al
    cestino di sistema. Se la cartella supera il limite configurato, i
    file più vecchi vengono inviati automaticamente al cestino di sistema
    (mai cancellati in modo permanente — vedi _transit_enforce_limit)."""
    transit = _get_transit_dir(config)
    try:
        os.makedirs(transit, exist_ok=True)
    except Exception:
        return None
    fname = os.path.basename(filepath)
    dest = os.path.join(transit, fname)
    if os.path.exists(dest):
        base, ext = os.path.splitext(fname)
        i = 1
        while os.path.exists(dest):
            dest = os.path.join(transit, f"{base}_{i}{ext}")
            i += 1
    try:
        shutil.move(filepath, dest)
    except Exception:
        return None
    # Segue anche qui: il file resta recuperabile con "Annulla" finche'
    # non viene svuotato il cestino di transito — se rating/tag restassero
    # sul percorso vecchio, un ripristino li lascerebbe orfani.
    if _METADATA_STORE_AVAILABLE:
        metadata_store.rename_path(filepath, dest)
    _transit_enforce_limit(config)
    return dest


# Cartella DEDICATA per "Taglia" verso un programma esterno — SEPARATA
# dal cestino di transito qui sopra di proposito: quello ha un limite
# di dimensione oltre il quale i file piu' vecchi vengono mandati
# davvero al cestino di sistema, e un file "tagliato" ma non ancora
# incollato non deve MAI rischiare di finire spazzato via da quel
# meccanismo pensato per tutt'altro scopo (Elimina).
#
# Perche' esiste: molti file manager esterni (Nemo, verificato
# direttamente da Carlo con un test mirato: il taglia/incolla interno
# di Nemo funziona, ma non si fida di un segnale "taglia" ricevuto da
# un programma esterno via clipboard — lo tratta sempre come una copia)
# non spostano mai il file di origine se il taglia arriva da fuori.
# L'unico modo affidabile per un vero "sposta" verso un programma
# esterno e' spostare DAVVERO il file subito, non solo segnalarlo.
#
# Scelta esplicita di Carlo, consapevole del compromesso: il file
# sparisce dalla cartella di origine PRIMA di sapere dove verra'
# incollato — recuperabile dallo Storico (azione "cut_staged") finche'
# non viene davvero incollato da qualche parte. Se l'incolla avviene
# DENTRO Image Sorter, la cartella di attesa si ripulisce da sola
# (_clipboard_paste sposta il file da li' alla destinazione finale). Se
# avviene in un programma esterno che copia invece di spostare (come
# Nemo), la copia in questa cartella resta — richiede una pulizia
# manuale occasionale, segnalato chiaramente a Carlo.
CUT_STAGING_DIR = os.path.join(os.path.expanduser("~"), ".local", "share",
                               "image_sorter", "taglia_in_attesa")


def move_to_cut_staging(filepath):
    """Sposta subito un file "tagliato" nella cartella di attesa
    dedicata (vedi commento sopra). Ritorna il nuovo percorso, o None
    in caso di errore."""
    try:
        os.makedirs(CUT_STAGING_DIR, exist_ok=True)
    except Exception:
        return None
    fname = os.path.basename(filepath)
    dest = os.path.join(CUT_STAGING_DIR, fname)
    if os.path.exists(dest):
        base, ext = os.path.splitext(fname)
        i = 1
        while os.path.exists(dest):
            dest = os.path.join(CUT_STAGING_DIR, f"{base}_{i}{ext}")
            i += 1
    try:
        shutil.move(filepath, dest)
    except Exception:
        return None
    if _METADATA_STORE_AVAILABLE:
        metadata_store.rename_path(filepath, dest)
    return dest


def _transit_dir_files(config):
    """Lista dei file attualmente in cartella di transito."""
    transit = _get_transit_dir(config)
    if not os.path.isdir(transit):
        return []
    try:
        return [os.path.join(transit, f) for f in os.listdir(transit)
                if os.path.isfile(os.path.join(transit, f))]
    except Exception:
        return []


def _transit_dir_size(config):
    """Dimensione totale della cartella di transito in bytes."""
    total = 0
    for fp in _transit_dir_files(config):
        try:
            total += os.path.getsize(fp)
        except OSError:
            pass
    return total


def _transit_enforce_limit(config):
    """Se la cartella di transito supera il limite configurato, invia al
    VERO cestino di sistema i file più vecchi finché si rientra nel
    limite. A differenza del backup crop, qui NON si cancella mai nulla
    in modo permanente — solo un normale invio al cestino di sistema,
    quindi i file restano recuperabili da lì. Ritorna (inviati, errori)."""
    limit = _transit_limit_bytes(config)
    files = _transit_dir_files(config)
    if not files:
        return 0, []
    aged = []
    for fp in files:
        try:
            aged.append((os.path.getmtime(fp), fp))
        except OSError:
            pass
    aged.sort()
    total = sum(os.path.getsize(fp) for _, fp in aged if os.path.isfile(fp))
    if total <= limit:
        return 0, []
    sent, errors = [], []
    for _, fp in aged:
        if total <= limit:
            break
        try:
            sz = os.path.getsize(fp)
        except OSError:
            sz = 0
        if send_to_trash(fp):
            sent.append(fp)
            total -= sz
        else:
            errors.append(os.path.basename(fp))
    _transit_clean_history_entries(sent)
    return len(sent), errors


def empty_transit_dir(config):
    """Invia davvero al cestino di sistema tutti i file in transito, e
    rimuove le relative entry dallo storico persistente (Impostazioni >
    Storico) — altrimenti resterebbero a puntare a file non più presenti
    in transito. Ritorna (svuotati, errori)."""
    files = _transit_dir_files(config)
    done, errors = 0, []
    sent_paths = []
    for fp in files:
        if send_to_trash(fp):
            done += 1
            sent_paths.append(fp)
        else:
            errors.append(os.path.basename(fp))
    _transit_clean_history_entries(sent_paths)
    return done, errors

