try:
    import sys as _sys
    _sys.path.insert(0, os.path.expanduser(
        "~/.local/lib/python3.8/site-packages"))
    from tkinterdnd2 import TkinterDnD as _TkinterDnD, DND_FILES as _DND_FILES
    _TKDND_OK = True
except ImportError:
    _TKDND_OK = False
    _TkinterDnD = None

def _dnd_register(widget, callback):
    """Registra widget come drop target con tkinterdnd2."""
    if not _TKDND_OK: return
    try:
        widget.drop_target_register(_DND_FILES)
        widget.dnd_bind("<<Drop>>",
                        lambda e: callback(_dnd_parse(e.data)))
        widget.dnd_bind("<<DropEnter>>",
                        lambda e: widget.config(relief="solid") or "copy")
        widget.dnd_bind("<<DropLeave>>",
                        lambda e: widget.config(relief="flat"))
    except Exception: pass

def _dnd_parse(data):
    """Parsa tutti i percorsi dal dato drop (supporta file multipli).
    Formato tkdnd: {/path/con spazi} {/altro/path} oppure /path/senza/spazi
    Restituisce lista di percorsi.
    """
    import re
    pairs = re.findall(r'\{([^}]+)\}|([^\s]+)', str(data))
    result = []
    for a, b in pairs:
        p = a or b
        if p.startswith("file://"): p = p[7:]
        if p: result.append(p)
    return result

def _dnd_parse_first(data):
    """Restituisce solo il primo percorso (compatibilità)."""
    result = _dnd_parse(data)
    return result[0] if result else ""


# ── Cartelle private ──────────────────────────────────────────────────────
_PRIVATE_FILE = os.path.join(
    os.path.expanduser("~/.config/image_sorter"), "private.dat")

def _load_private_folders():
    """Carica lista cartelle private da file offuscato (base64)."""
    try:
        import base64
        if not os.path.isfile(_PRIVATE_FILE): return []
        with open(_PRIVATE_FILE, "rb") as fh:
            data = base64.b64decode(fh.read()).decode("utf-8")
        return [l for l in data.splitlines() if l.strip()]
    except Exception: return []

def _save_private_folders(folders):
    """Salva lista cartelle private in file offuscato (base64)."""
    try:
        import base64
        os.makedirs(os.path.dirname(_PRIVATE_FILE), exist_ok=True)
        data = "\n".join(folders).encode("utf-8")
        with open(_PRIVATE_FILE, "wb") as fh:
            fh.write(base64.b64encode(data))
    except Exception: pass

def _is_private(path, private_folders):
    """Restituisce True se path e' dentro una cartella privata."""
    p = os.path.abspath(path)
    for pf in private_folders:
        apf = os.path.abspath(pf)
        if p == apf or p.startswith(apf + os.sep):
            return True
    return False


