def _load_translations():
    """Carica le traduzioni da translations.py nella stessa cartella dello script."""
    try:
        import importlib.util
        trans_path = os.path.join(SCRIPT_DIR, "translations.py")
        if not os.path.isfile(trans_path):
            return None, None, {}
        spec = importlib.util.spec_from_file_location("translations", trans_path)
        mod  = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return (getattr(mod, "LANG", {}),
                getattr(mod, "SHORTCUTS", {}),
                getattr(mod, "_IT_EN", {}))
    except Exception:
        return None, None, {}

_LANG_DATA, _SHORTCUTS_DATA, _IT_EN_FROM_FILE = _load_translations()

_IT_EN = _IT_EN_FROM_FILE

def _translate_widgets(widget, lang):
    """Scorre tutti i widget e traduce i testi noti IT→EN."""
    if lang == "it": return
    mapping = _IT_EN
    try:
        cls = widget.__class__.__name__
        if cls in ("Label","Button","Checkbutton","Radiobutton","LabelFrame"):
            t = widget.cget("text")
            if t in mapping:
                widget.config(text=mapping[t])
        elif cls == "Notebook":
            # Traduce le etichette dei tab ttk.Notebook
            for tab_id in widget.tabs():
                t = widget.tab(tab_id, "text")
                if t in mapping:
                    widget.tab(tab_id, text=mapping[t])
        elif cls == "Entry":
            # Traduce placeholder se impostato
            pass
    except Exception: pass
    for child in widget.winfo_children():
        _translate_widgets(child, lang)

def _translate_menu(menu, lang):
    """Traduce le voci di un Menu tk."""
    if lang == "it": return
    mapping = _IT_EN
    try:
        last = menu.index("end")
        if last is None: return
        for i in range(last+1):
            try:
                t = menu.entrycget(i, "label")
                if t in mapping:
                    menu.entryconfig(i, label=mapping[t])
            except Exception: pass
    except Exception: pass

def T(key, lang=None, **kw):
    """Restituisce la stringa tradotta per key nella lingua corrente."""
    if lang is None:
        try:
            cfg = load_config()
            lang = cfg.get("language", "it")
        except Exception:
            lang = "it"
    data = (_LANG_DATA or {}).get(lang, {})
    if not data:
        data = (_LANG_DATA or {}).get("it", {})
    s = data.get(key, key)   # fallback: mostra la chiave
    if kw:
        try: s = s.format(**kw)
        except Exception: pass
    return s


