import struct, wave, math as _math

def _make_wav(freq, duration, volume=0.4, fade=0.02, sample_rate=22050):
    """Genera un file WAV in memoria come bytes."""
    n_samples = int(sample_rate * duration)
    fade_s    = int(sample_rate * fade)
    buf = bytearray()
    for i in range(n_samples):
        t   = i / sample_rate
        env = 1.0
        if i < fade_s:
            env = i / fade_s
        elif i > n_samples - fade_s:
            env = (n_samples - i) / fade_s
        val = int(32767 * volume * env * _math.sin(2 * _math.pi * freq * t))
        buf += struct.pack("<h", max(-32768, min(32767, val)))
    # Costruisce WAV in memoria
    import io
    out = io.BytesIO()
    with wave.open(out, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf))
    return out.getvalue()


def _make_chord_wav(freqs, duration, volume=0.3, fade=0.03, sample_rate=22050):
    """Genera un accordo/sequenza di note."""
    import io
    n_samples = int(sample_rate * duration)
    fade_s    = int(sample_rate * fade)
    buf = bytearray()
    for i in range(n_samples):
        t   = i / sample_rate
        env = 1.0
        if i < fade_s:
            env = i / fade_s
        elif i > n_samples - fade_s:
            env = (n_samples - i) / fade_s
        val = sum(_math.sin(2 * _math.pi * f * t) for f in freqs)
        val = int(32767 * volume * env * val / len(freqs))
        buf += struct.pack("<h", max(-32768, min(32767, val)))
    out = io.BytesIO()
    with wave.open(out, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf))
    return out.getvalue()


def _make_sequence_wav(notes, volume=0.35, fade=0.015, sample_rate=22050):
    """Genera una sequenza di note IN SUCCESSIONE (non sovrapposte).
    notes: lista di tuple (freq_hz, durata_sec)."""
    import io
    buf = bytearray()
    for freq, duration in notes:
        n_samples = int(sample_rate * duration)
        fade_s    = max(1, int(sample_rate * fade))
        for i in range(n_samples):
            t   = i / sample_rate
            env = 1.0
            if i < fade_s:
                env = i / fade_s
            elif i > n_samples - fade_s:
                env = (n_samples - i) / fade_s
            val = int(32767 * volume * env * _math.sin(2 * _math.pi * freq * t))
            buf += struct.pack("<h", max(-32768, min(32767, val)))
    out = io.BytesIO()
    with wave.open(out, "wb") as wf:
        wf.setnchannels(1)
        wf.setsampwidth(2)
        wf.setframerate(sample_rate)
        wf.writeframes(bytes(buf))
    return out.getvalue()


# Genera i suoni una sola volta all'avvio
_SOUND_MOVE   = None   # breve bip acuto: file spostato
_SOUND_DONE   = None   # accordo conclusivo: scansione completata
_SOUND_UNDO   = None   # due note discendenti: operazione annullata
_SOUND_TRASH  = None   # tonfo grave: file cestinato (transito)
_SOUND_READY  = False

def _init_sounds():
    global _SOUND_MOVE, _SOUND_DONE, _SOUND_UNDO, _SOUND_TRASH, _SOUND_READY
    if _SOUND_READY:
        return
    try:
        # Suono spostamento: breve bip 880Hz (La5) — 80ms
        _SOUND_MOVE  = _make_wav(880, 0.08, volume=0.35)
        # Suono completamento: accordo Do-Mi-Sol ascendente — 400ms
        _SOUND_DONE  = _make_chord_wav([523, 659, 784], 0.4, volume=0.3)
        # Suono annulla: due note discendenti (Mi5-La4) — "indietro"
        _SOUND_UNDO  = _make_sequence_wav([(659, 0.07), (440, 0.09)], volume=0.35)
        # Suono cestino: tonfo grave singolo (La3), più lungo e sordo —
        # nettamente diverso sia dal bip acuto dello spostamento sia dalla
        # melodia discendente dell'annulla
        _SOUND_TRASH = _make_wav(220, 0.14, volume=0.4, fade=0.03)
        _SOUND_READY = True
    except Exception:
        pass


def play_sound(sound_type="move"):
    """Riproduce un suono in background. sound_type: 'move', 'done', 'undo' o 'trash'."""
    if not _SOUND_READY:
        _init_sounds()
    data = {"move": _SOUND_MOVE, "done": _SOUND_DONE,
            "undo": _SOUND_UNDO, "trash": _SOUND_TRASH}.get(sound_type, _SOUND_MOVE)
    if not data:
        return
    def _play():
        try:
            import tempfile, subprocess as _sp
            tmp = tempfile.NamedTemporaryFile(suffix=".wav", delete=False)
            tmp.write(data)
            tmp.close()
            # Prova aplay (ALSA), poi paplay (PulseAudio)
            for player in ["aplay", "paplay", "sox"]:
                try:
                    _sp.Popen([player, "-q", tmp.name],
                              stdout=_sp.DEVNULL, stderr=_sp.DEVNULL)
                    break
                except FileNotFoundError:
                    continue
            import time as _t; _t.sleep(0.6)
            import os as _os; _os.unlink(tmp.name)
        except Exception:
            pass
    threading.Thread(target=_play, daemon=True).start()


# =============================================================================
# ICONE (generate con Pillow, nessun file esterno)
# =============================================================================

_icon_cache    = {}
from collections import OrderedDict as _OD
_thumb_cache   = _OD()  # {(filepath, mtime, size): PhotoImage} — LRU
_THUMB_CACHE_MAX = 200   # max thumbnail in memoria
# La cache viene ora letta dal thread principale (peek_thumbnail) e scritta
# anche da thread di lavoro (generazione miniature in background): le
# operazioni di riordino/espulsione LRU non sono atomiche, serve un lock.
_thumb_cache_lock = threading.Lock()

def make_icon(name, size=18, fg=(0,200,255), bg=(10,15,26)):
    """Genera una PhotoImage tkinter con icona vettoriale semplice."""
    key = (name, size, fg, bg)
    if key in _icon_cache:
        return _icon_cache[key]
    img = Image.new("RGBA", (size, size), (bg[0], bg[1], bg[2], 0))
    d = ImageDraw.Draw(img)
    s = size
    c = s // 2  # centro
    t = max(1, s // 10)  # spessore linea

    if name == "folder":
        # Cartella: rettangolo con tab in cima
        d.rectangle([1, s//3, s-2, s-2], outline=fg, width=t)
        d.rectangle([1, s//4, s//2, s//3+1], outline=fg, fill=fg, width=1)
    elif name == "folder_open":
        d.rectangle([1, s//3, s-2, s-2], outline=fg, width=t)
        d.rectangle([1, s//4, s//2, s//3+1], outline=fg, fill=fg, width=1)
        # Freccia aperta
        d.line([(s//4, s*2//3),(s*3//4, s*2//3)], fill=fg, width=t)
    elif name == "home":
        # Casa: triangolo tetto + rettangolo
        d.polygon([(c, 2),(s-2, s//2),(2, s//2)], outline=fg, fill=bg)
        d.rectangle([s//4, s//2, s*3//4, s-2], outline=fg, width=t)
        # Porta
        d.rectangle([c-2, s*2//3, c+2, s-2], fill=fg)
    elif name == "image":
        # Cornice con montagna stilizzata
        d.rectangle([2, 2, s-3, s-3], outline=fg, width=t)
        d.polygon([(3, s-4),(s//3, s//3),(s*2//3, s*2//3),(s-4,s-4)],
                  outline=fg, fill=(fg[0]//3, fg[1]//3, fg[2]//3, 180))
        d.ellipse([s*2//3-2, 3, s-4, s//3], outline=fg, width=t)
    elif name == "video":
        # Rettangolo con triangolo play
        d.rectangle([2, 2, s-3, s-3], outline=fg, width=t)
        d.polygon([(s//3, s//4),(s//3, s*3//4),(s*3//4, c)], fill=fg)
    elif name == "document":
        # Foglio con angolo piegato
        d.polygon([(2,2),(s-s//4,2),(s-2,s//4),(s-2,s-2),(2,s-2)],
                  outline=fg, width=t)
        d.line([(s-s//4, 2),(s-s//4, s//4),(s-2, s//4)], fill=fg, width=t)
        # Righe testo
        for y in [s//3, s//2, s*2//3]:
            d.line([(s//5, y),(s*4//5, y)], fill=fg, width=max(1,t-1))
    elif name == "disk":
        # Cerchio con etichetta
        d.ellipse([2,2,s-3,s-3], outline=fg, width=t)
        d.ellipse([s//3,s//3,s*2//3,s*2//3], outline=fg, width=t)
    elif name == "root":
        # Slash /
        d.line([(s*2//3, 2),(s//3, s-3)], fill=fg, width=t+1)
    elif name == "up":
        # Freccia su
        d.polygon([(c,2),(s-3,c),(3,c)], fill=fg)
        d.rectangle([c-t, c, c+t, s-3], fill=fg)
    elif name == "down":
        # Freccia giù
        d.polygon([(c,s-3),(s-3,c),(3,c)], fill=fg)
        d.rectangle([c-t, 3, c+t, c], fill=fg)
    elif name == "close":
        # X
        d.line([(3,3),(s-4,s-4)], fill=fg, width=t+1)
        d.line([(s-4,3),(3,s-4)], fill=fg, width=t+1)
    elif name == "check":
        # Spunta
        d.line([(3,c),(c-1,s-4),(s-3,3)], fill=fg, width=t+1)
    elif name == "new_folder":
        # Cartella con +
        d.rectangle([1, s//3, s-2, s-2], outline=fg, width=t)
        d.rectangle([1, s//4, s//2, s//3+1], fill=fg, width=1)
        d.line([(c, s//2),(c, s-3)], fill=(0,255,128), width=t+1)
        d.line([(s//3+1, s*3//4),(s*2//3, s*3//4)], fill=(0,255,128), width=t+1)
    elif name == "back":
        # Freccia sinistra
        d.polygon([(3,c),(c,2),(c,s-3)], fill=fg)
        d.rectangle([c, c-t, s-3, c+t], fill=fg)
    elif name == "play":
        # Triangolo play
        d.polygon([(3,2),(3,s-3),(s-3,c)], fill=fg)

    photo = ImageTk.PhotoImage(img)
    _icon_cache[key] = photo
    return photo


def icon_btn(parent, icon_name, text="", cmd=None, bg=None, fg=None,
             size=16, **kwargs):
    """Crea un Button con icona Pillow + testo opzionale."""
    _bg = bg or PANEL_COLOR
    _fg = fg or (0, 200, 255)
    ico  = make_icon(icon_name, size=size, fg=_fg, bg=tuple(
        int(_bg.lstrip("#")[i:i+2], 16) for i in (0,2,4))
        if isinstance(_bg, str) else _bg)
    b = tk.Button(parent, image=ico, text=text,
                  compound="left" if text else "none",
                  bg=_bg, relief="flat", bd=0,
                  activebackground=HIGHLIGHT,
                  command=cmd, **kwargs)
    b._icon_ref = ico   # impedisce garbage collection
    return b


def detect_media_type(filepath):
    """Rileva il tipo di file anche senza estensione, leggendo i magic bytes."""
    # Prima prova con estensione normale
    ext = os.path.splitext(filepath)[1].lower()
    if ext in MEDIA_EXTENSIONS:
        return ext

    # Nessuna estensione o estensione sconosciuta: leggi magic bytes
    try:
        with open(filepath, "rb") as f:
            header = f.read(16)
        # Immagini
        if header[:3] == b"\xff\xd8\xff":          return ".jpg"
        if header[:8] == b"\x89PNG\r\n\x1a\n":    return ".png"
        if header[:6] in (b"GIF87a", b"GIF89a"):     return ".gif"
        if header[:4] == b"RIFF" and header[8:12] == b"WEBP": return ".webp"
        if header[:2] in (b"BM",):                   return ".bmp"
        if header[:4] in (b"II*\x00", b"MM\x00*"): return ".tiff"
        # Video
        if header[4:8] == b"ftyp":
            brand = header[8:12]
            if brand in (b"heic", b"heix", b"mif1", b"msf1", b"avif"):
                return ".heic"
            return ".mp4"
        if header[4:8] == b"moov":                    return ".mp4"
        if header[:4] == b"RIFF" and header[8:12] == b"AVI ": return ".avi"
        if header[:4] == b"\x1a\x45\xdf\xa3":     return ".mkv"
        # PDF
        if header[:4] == b"%PDF":                    return ".pdf"
    except (OSError, IOError):
        pass
    return ""


def is_media_file(filepath):
    """Controlla se il file è un media supportato, anche senza estensione."""
    return detect_media_type(filepath) in MEDIA_EXTENSIONS


def tk_safe(text, maxlen=None):
    """Rimuove caratteri che causano RenderAddGlyphs crash in tkinter/X11.
    Filtra:
    - caratteri oltre BMP (codepoint >= 0x10000): emoji, flag, bold Unicode
    - blocchi BMP non supportati dal font di default X11: simboli, box-drawing,
      variation selectors, simboli miscellanei, emoticon BMP
    """
    if not isinstance(text, str):
        text = str(text)

    def _is_safe(c):
        cp = ord(c)
        if cp >= 0x10000:
            return False   # oltre BMP: emoji, flag regionali, bold Unicode
        # Variation selectors (U+FE00–FE0F, U+E0100–E01EF già coperti da >= 0x10000)
        if 0xFE00 <= cp <= 0xFE0F:
            return False
        # Simboli miscellanei e Dingbats
        if 0x2600 <= cp <= 0x27BF:
            return False
        # Box drawing e block elements (━ █ ecc.)
        if 0x2500 <= cp <= 0x259F:
            return False
        # Supplemental arrows, geometric shapes
        if 0x25A0 <= cp <= 0x25FF:
            return False
        # Miscellaneous Symbols and Arrows (⭕ ecc.)
        if 0x2B00 <= cp <= 0x2BFF:
            return False
        # Enclosed alphanumerics, enclosed CJK
        if 0x2460 <= cp <= 0x24FF:
            return False
        # Caratteri di controllo e non-printable
        if cp < 32 and cp not in (9, 10, 13):
            return False
        return True

    result = "".join(c if _is_safe(c) else "?" for c in text)
    # Comprimi sequenze di ? multipli in uno solo
    import re as _re
    result = _re.sub(r'\?{2,}', '?', result)
    if maxlen and len(result) > maxlen:
        result = result[:maxlen-1] + "…"
    return result

def pillow_safe(text, maxlen=None):
    """Sanitizza testo per Pillow ImageDraw.text — usa solo ASCII stampabile
    per evitare crash con font di default che non supportano Unicode esteso.
    Caratteri non-ASCII vengono rimpiazzati con '?'.
    """
    if not isinstance(text, str):
        text = str(text)
    result = "".join(c if 32 <= ord(c) < 127 else "?" for c in text)
    if maxlen and len(result) > maxlen:
        result = result[:maxlen-3] + "..."
    return result


def load_thumbnail(filepath, size):
    """Carica thumbnail con cache, draft mode per JPEG, timeout per video/PDF."""
    try:
        mtime = os.path.getmtime(filepath)
        key   = (filepath, mtime, size)
        with _thumb_cache_lock:
            if key in _thumb_cache:
                _thumb_cache.move_to_end(key)  # aggiorna LRU
                return _thumb_cache[key]

        ext = detect_media_type(filepath)
        if ext in VIDEO_EXTENSIONS:
            img = get_video_frame(filepath)
            if img is None:
                img = Image.new("RGB", (size, size), (20,20,40))
                d = ImageDraw.Draw(img)
                s = size
                d.polygon([(s//4,s//4),(s//4,3*s//4),(3*s//4,s//2)], fill=(0,200,255))
            img.thumbnail((size, size), Image.Resampling.LANCZOS)
            img = add_play_overlay(img, corner=(size > 60))
        elif ext in PDF_EXTENSIONS:
            img = get_pdf_preview(filepath, size=(size*2, size*2))
            img.thumbnail((size, size), Image.Resampling.LANCZOS)
            img = add_pdf_overlay(img)
        else:
            img = Image.open(filepath)
            # Draft mode: molto più veloce per JPEG grandi
            if hasattr(img, "draft") and ext in (".jpg", ".jpeg"):
                img.draft("RGB", (size * 2, size * 2))
            # Sicurezza memoria: se l'immagine è enorme, ridimensiona prima di caricare
            if img.width * img.height > 4000 * 4000:
                img.thumbnail((2000, 2000), Image.Resampling.NEAREST)
            img.thumbnail((size, size), Image.Resampling.LANCZOS)
            img = img.copy()  # stacca dai pixel originali
            # Il file descriptor viene rilasciato dal GC — img.close() invalida i pixel

        # Cache LRU: sposta in coda (più recente) e rimuovi il meno usato
        with _thumb_cache_lock:
            if key in _thumb_cache:
                _thumb_cache.move_to_end(key)
            else:
                _thumb_cache[key] = img
                if len(_thumb_cache) > _THUMB_CACHE_MAX:
                    _thumb_cache.popitem(last=False)  # rimuovi il meno recente
        return img
    except Exception:
        return None


# ── Posizione GPS: appunti condivisi fra le finestre ─────────────────────────
import re as _re
# Un solo posto per la posizione copiata, cosi' si puo' copiare da Naviga e
# incollare in Timeline (o viceversa).
_gps_clipboard = [None]      # (lat, lon) oppure None


def gps_clip_set(lat, lon):
    _gps_clipboard[0] = (float(lat), float(lon))


def gps_clip_get():
    return _gps_clipboard[0]


# Riconosce le coordinate scritte nei formati che si ottengono copiando da
# Google Maps e simili. Non e' un parser generico di geolocalizzazione: e'
# tarato sui modi in cui una coordinata finisce negli appunti.
_DMS_RE = _re.compile(
    r"""(\d+(?:[.,]\d+)?)\s*[°d:\s]\s*
        (?:(\d+(?:[.,]\d+)?)\s*['m:\s]\s*)?
        (?:(\d+(?:[.,]\d+)?)\s*(?:"|''|s)?\s*)?
        \s*([NSEWOnsewo])""", _re.X)


def parse_coords(text):
    """Estrae (lat, lon) da un testo incollato. None se non riconosciuto.

    Formati gestiti:
      45.452519, 9.163573        (decimale, il piu' comune da Maps)
      45.452519 9.163573         (separati da spazio o punto e virgola)
      45.4525N, 9.1635E          (con lettera dell'emisfero)
      45°27'09.1"N 9°09'48.9"E   (gradi/primi/secondi, sempre da Maps)
      geo:45.4525,9.1635         (link geo:)
      https://maps.google.com/... /@45.4525,9.1635,17z   (URL di Maps)
    """
    if not text or not text.strip():
        return None
    t = text.strip()
    # Senza nemmeno una cifra non c'e' niente da interpretare: senza questo
    # controllo un testo qualsiasi poteva arrivare in fondo alla funzione e
    # produrre una coppia di zeri.
    if not _re.search(r"\d", t):
        return None
    # Negli URL di Maps le coordinate seguono una "@"; prendendo il testo
    # dopo di essa si evita di catturare per errore altri numeri dell'URL.
    if "@" in t and ("map" in t.lower() or "http" in t.lower()):
        t = t.split("@", 1)[1]
    t = t.replace("geo:", " ")

    # 1) gradi/primi/secondi con emisfero
    dms = _DMS_RE.findall(t)
    if len(dms) >= 2:
        vals = []
        for d, m, sec, ref in dms[:2]:
            v = (float(d.replace(",", "."))
                 + float((m or "0").replace(",", ".")) / 60.0
                 + float((sec or "0").replace(",", ".")) / 3600.0)
            if ref.upper() in ("S", "W", "O"):
                v = -v
            vals.append((v, ref.upper()))
        lat = next((v for v, r in vals if r in ("N", "S")), None)
        lon = next((v for v, r in vals if r in ("E", "W", "O")), None)
        if lat is None or lon is None:      # emisferi non dichiarati: ordine
            lat, lon = vals[0][0], vals[1][0]
        if -90 <= lat <= 90 and -180 <= lon <= 180:
            return _reject_null_island(lat, lon)

    # 2) coppia di numeri decimali, con eventuale lettera dell'emisfero
    nums = _re.findall(r"[-+]?\d+\.\d+|[-+]?\d+(?=\s*[°NSEWnsew])|[-+]?\d+",
                       t.replace(",", " "))
    refs = _re.findall(r"[NSEWnsew]", t)
    if len(nums) >= 2:
        try:
            lat, lon = float(nums[0]), float(nums[1])
        except ValueError:
            return None
        if len(refs) >= 2:
            if refs[0].upper() == "S": lat = -abs(lat)
            if refs[1].upper() == "W": lon = -abs(lon)
        if -90 <= lat <= 90 and -180 <= lon <= 180:
            return _reject_null_island(lat, lon)
    return None


def _reject_null_island(lat, lon):
    """Scarta la coppia (0, 0).

    E' il punto in mezzo all'Oceano Atlantico al largo del Golfo di Guinea:
    non e' una posizione plausibile per una foto, ed e' invece il valore che
    esce da un campo vuoto o da un testo senza coordinate vere. Meglio un
    "coordinate non riconosciute" che scrivere zeri su tutti i file
    selezionati.
    """
    if abs(lat) < 1e-9 and abs(lon) < 1e-9:
        return None
    return (lat, lon)


def apply_gps_to_files(paths, lat, lon):
    """Scrive la posizione su piu' file e registra una voce di storico.

    Procedura UNICA per tutti i punti del programma (menu di Naviga, menu
    della Timeline, geotag di gruppo): scriverla una sola volta evita che
    i vari percorsi divergano, come era gia' successo per la
    registrazione degli spostamenti.
    Restituisce (fatti, saltati_per_formato, errori, percorsi_riusciti).
    percorsi_riusciti e' la lista dei file su cui la scrittura e'
    DAVVERO andata a buon fine — indispensabile per chi (es. Timeline)
    aggiorna una cache in RAM dopo la scrittura: aggiornarla per TUTTI i
    percorsi richiesti invece che solo per quelli riusciti mostrerebbe
    "corretto" anche un file su cui la scrittura e' fallita in silenzio
    (segnalato da Carlo: il popup di conferma mostrava le coordinate
    giuste, ma alcuni file restavano con la posizione vecchia — perche'
    la cache di Timeline veniva aggiornata comunque, a prescindere
    dall'esito reale di ciascun file).
    """
    # Rete di sicurezza indipendente dal parsing: nessun percorso del
    # programma deve poter scrivere (0, 0) su un gruppo di file, qualunque
    # sia la strada da cui arrivano le coordinate.
    try:
        if abs(float(lat)) < 1e-9 and abs(float(lon)) < 1e-9:
            return 0, 0, ["Coordinate non valide (0, 0)"], []
    except (TypeError, ValueError):
        return 0, 0, ["Coordinate non valide"], []
    try:
        from exif_editor import read_gps, write_gps, GPS_WRITABLE_EXT
    except Exception:
        return 0, 0, ["piexif non installato"], []
    writable = [p for p in paths
                if os.path.splitext(p)[1].lower() in GPS_WRITABLE_EXT]
    skipped = len(paths) - len(writable)
    done, errors, prev = 0, [], []
    for fp in writable:
        before = read_gps(fp)
        ok, msg = write_gps(fp, lat, lon)
        if ok:
            done += 1
            prev.append([fp, before[0] if before else None,
                         before[1] if before else None])
        else:
            # Nome del file nel messaggio: senza, un errore su un file
            # in mezzo a un gruppo era impossibile da individuare (solo
            # "N errori" nello stato, nessun indizio su quale file).
            errors.append(f"{os.path.basename(fp)}: {msg}")
    if done:
        try:
            append_history({"action": "geotag_batch",
                            "files": [p for p, a, o in prev],
                            "prev_gps": [[a, o] for p, a, o in prev],
                            "dest": "",
                            "note": f"{done} file: {lat:.5f}, {lon:.5f}"})
        except Exception:
            pass
    return done, skipped, errors, [p for p, a, o in prev]


# Colore dell'indicatore di formato: ambra, distinto dal verde del GPS e
# dal ciano dell'interfaccia.
FMT_DOT_FILL    = "#ff9800"
FMT_DOT_OUTLINE = "#4a2a00"

# Colore dell'indicatore di errore: rosso, l'unico dei tre che segnala un
# problema e non una proprieta' del file.
ERR_DOT_FILL    = "#ff3b30"
ERR_DOT_OUTLINE = "#4a0000"

# Geometria della colonna di pallini in alto a destra del canvas.
DOT_R    = 7            # raggio
DOT_Y0   = DOT_R + 8    # centro del primo pallino
DOT_STEP = 2 * DOT_R + 5  # distanza fra un pallino e il successivo


_gps_flag_cache = _OD()          # {(filepath, mtime): bool}
_gps_flag_lock  = threading.Lock()
_GPS_FLAG_MAX   = 3000           # solo booleani: costa pochissimo tenerne tanti


def has_gps_quick(filepath):
    """True se il file contiene coordinate GPS leggibili.

    Legge l'EXIF con Pillow, quindi va chiamata da un thread di lavoro e
    mai sul thread principale: su una cartella di centinaia di foto
    bloccherebbe l'interfaccia. Il risultato viene tenuto in cache con la
    data di modifica, cosi' tornando in una cartella gia' vista i pallini
    compaiono subito.
    """
    try:
        key = (filepath, os.path.getmtime(filepath))
    except OSError:
        return False
    with _gps_flag_lock:
        if key in _gps_flag_cache:
            _gps_flag_cache.move_to_end(key)
            return _gps_flag_cache[key]
    val = False
    try:
        if os.path.splitext(filepath)[1].lower() in EXIF_READ_EXT:
            from PIL import Image as _PI
            gps = _PI.open(filepath).getexif().get_ifd(0x8825)
            val = bool(gps and gps.get(2) and gps.get(4))
    except Exception:
        val = False
    with _gps_flag_lock:
        _gps_flag_cache[key] = val
        _gps_flag_cache.move_to_end(key)
        while len(_gps_flag_cache) > _GPS_FLAG_MAX:
            _gps_flag_cache.popitem(last=False)
    return val


def is_non_jpeg_image(filepath):
    """True se il file e' un'immagine ma NON un JPEG.

    Serve a segnalare a colpo d'occhio i file che, pur essendo immagini,
    non accettano i metadati EXIF nello stesso modo (PNG, WebP, AVIF...)
    o che occupano molto piu' spazio a parita' di contenuto.
    Video e PDF non sono immagini: nessun indicatore.
    """
    try:
        ext = os.path.splitext(filepath)[1].lower()
    except Exception:
        return False
    return ext in IMAGE_EXTENSIONS and ext not in (".jpg", ".jpeg")


def peek_thumbnail(filepath, size):
    """Restituisce la miniatura SOLO se è già in cache, altrimenti None.

    Non apre mai il file e non decodifica nulla: serve al thread
    principale per disegnare subito ciò che è già pronto, lasciando al
    thread di lavoro tutto ciò che richiederebbe una decodifica (immagini
    molto grandi, estrazione frame video via ffmpeg, rendering PDF).
    """
    try:
        key = (filepath, os.path.getmtime(filepath), size)
        with _thumb_cache_lock:
            img = _thumb_cache.get(key)
            if img is not None:
                _thumb_cache.move_to_end(key)
            return img
    except Exception:
        return None


# ── Rinomina in serie: segnaposto ────────────────────────────────────────────
import re as _re
import datetime as _datetime

# Etichette dei segnaposto utilizzabili nel modello di rinomina, nell'ordine
# in cui vengono mostrati nell'aiuto del dialogo.
RENAME_TOKENS = [
    ("{nome}",       "nome originale"),
    ("{n}",          "numero progressivo"),
    ("{data}",       "data di scatto"),
    ("{anno}",       "anno"),
    ("{mese}",       "mese"),
    ("{giorno}",     "giorno"),
    ("{ora}",        "ora di scatto"),
    ("{marca}",      "marca fotocamera"),
    ("{modello}",    "modello fotocamera"),
    ("{iso}",        "ISO"),
    ("{focale}",     "focale"),
    ("{diaframma}",  "diaframma"),
    ("{esposizione}","tempo di posa"),
    ("{larghezza}",  "larghezza px"),
    ("{altezza}",    "altezza px"),
    ("{cartella}",   "nome cartella"),
]

_RENAME_BAD_CHARS = '/\\:*?"<>|'

def sanitize_filename(name, fallback="file"):
    """Rende una stringa utilizzabile come nome di file.

    Rimuove i separatori di percorso e i caratteri non ammessi, comprime
    gli spazi e i separatori ripetuti lasciati dai segnaposto vuoti (es.
    un modello "{data}_{modello}" su un file senza EXIF produrrebbe
    altrimenti un nome che inizia con un underscore isolato).
    """
    out = "".join(("" if (c in _RENAME_BAD_CHARS or ord(c) < 32) else c)
                  for c in (name or ""))
    out = _re.sub(r"\s+", " ", out)
    out = _re.sub(r"_{2,}", "_", out)
    out = _re.sub(r"-{2,}", "-", out)
    out = out.strip(" ._-")
    return out or fallback

def rename_token_values(filepath, index=0, start=1, digits=3,
                        date_fmt="%Y%m%d"):
    """Valori dei segnaposto per un singolo file.

    I dati di scatto vengono letti una sola volta per file (il chiamante
    tiene una cache): senza EXIF utilizzabile, la data ripiega sulla data
    di modifica del file e gli altri campi restano vuoti — un segnaposto
    senza valore semplicemente sparisce dal nome, senza lasciare buchi.
    """
    vals = {t: "" for t, _d in RENAME_TOKENS}
    base = os.path.splitext(os.path.basename(filepath))[0]
    vals["{nome}"]     = base
    vals["{cartella}"] = os.path.basename(os.path.dirname(filepath))
    try:
        vals["{n}"] = str(start + index).zfill(max(1, digits))
    except Exception:
        vals["{n}"] = str(index + 1)

    dt = None
    try:
        from PIL import Image as _Img
        img = _Img.open(filepath)
        vals["{larghezza}"] = str(img.width)
        vals["{altezza}"]   = str(img.height)
        ex = img.getexif()
        if ex:
            vals["{marca}"]   = str(ex.get(0x010F, "") or "").strip()
            vals["{modello}"] = str(ex.get(0x0110, "") or "").strip()
            sub = {}
            try:
                sub = ex.get_ifd(0x8769) or {}
            except Exception:
                sub = {}
            raw_dt = (sub.get(0x9003) or sub.get(0x9004) or ex.get(0x0132))
            if raw_dt:
                try:
                    dt = _datetime.datetime.strptime(
                        str(raw_dt).strip(), "%Y:%m:%d %H:%M:%S")
                except Exception:
                    dt = None
            iso = sub.get(0x8827)
            if isinstance(iso, (list, tuple)):
                iso = iso[0] if iso else None
            if iso:
                vals["{iso}"] = f"ISO{int(iso)}"
            fn = sub.get(0x829D)
            if fn:
                try:
                    vals["{diaframma}"] = ("f%g" % float(fn)).replace(".", "-")
                except Exception:
                    pass
            fl = sub.get(0x920A)
            if fl:
                try:
                    vals["{focale}"] = "%gmm" % float(fl)
                except Exception:
                    pass
            et = sub.get(0x829A)
            if et:
                try:
                    et = float(et)
                    # Le frazioni di secondo contengono "/", che è un
                    # separatore di percorso: va trasformato, non inserito.
                    vals["{esposizione}"] = (("1-%ds" % round(1.0 / et))
                                             if 0 < et < 1 else "%gs" % et)
                except Exception:
                    pass
    except Exception:
        pass

    if dt is None:
        try:
            dt = _datetime.datetime.fromtimestamp(os.path.getmtime(filepath))
        except Exception:
            dt = None
    if dt is not None:
        try:
            vals["{data}"] = dt.strftime(date_fmt)
        except Exception:
            vals["{data}"] = dt.strftime("%Y%m%d")
        vals["{anno}"]   = dt.strftime("%Y")
        vals["{mese}"]   = dt.strftime("%m")
        vals["{giorno}"] = dt.strftime("%d")
        vals["{ora}"]    = dt.strftime("%H%M%S")
    return vals

def apply_rename_template(template, values):
    """Sostituisce i segnaposto nel modello (case-insensitive)."""
    out = template or ""
    for tok in sorted(values, key=len, reverse=True):
        if tok.lower() in out.lower():
            out = _re.sub(_re.escape(tok), lambda _m: values[tok],
                          out, flags=_re.IGNORECASE)
    return out


def is_video(filepath):
    t = detect_media_type(filepath)
    return t in VIDEO_EXTENSIONS

def is_pdf(filepath):
    t = detect_media_type(filepath)
    return t in PDF_EXTENSIONS

def _pymupdf_available():
    """Controlla se PyMuPDF (fitz) è installato."""
    try:
        import fitz  # noqa
        return True
    except ImportError:
        return False


def get_pdf_page_count(filepath):
    """Ritorna il numero di pagine del PDF."""
    # PyMuPDF — veloce, nessun processo esterno
    try:
        import fitz
        doc = fitz.open(filepath)
        n = doc.page_count
        doc.close()
        return n
    except Exception:
        pass
    # Fallback: pdfinfo
    try:
        result = subprocess.run(["pdfinfo", filepath],
                                capture_output=True, text=True, timeout=5)
        for line in result.stdout.splitlines():
            if line.startswith("Pages:"):
                return int(line.split(":")[1].strip())
    except Exception:
        pass
    return 1


def get_pdf_preview(filepath, size=(640, 480), page=1):
    """Estrae una pagina del PDF come immagine PIL.
    Usa PyMuPDF se disponibile (più veloce, nessun file temp),
    altrimenti pdftoppm come fallback."""

    # ── PyMuPDF ────────────────────────────────────────────────────────────────
    try:
        import fitz
        doc  = fitz.open(filepath)
        pg   = doc[page - 1]          # 0-indexed
        # Risoluzione: 72dpi per anteprime, 120dpi per visualizzazione grande
        zoom = 1.0 if max(size) <= 200 else 1.5
        mat  = fitz.Matrix(zoom, zoom)
        pix  = pg.get_pixmap(matrix=mat, alpha=False)
        doc.close()
        img  = Image.frombytes("RGB", (pix.width, pix.height), pix.samples)
        return img
    except Exception:
        pass

    # ── Fallback: pdftoppm ────────────────────────────────────────────────────
    try:
        tmp = tempfile.mkdtemp()
        out_base = os.path.join(tmp, "page")
        subprocess.run(
            ["pdftoppm", "-r", "72", "-f", str(page), "-l", str(page),
             "-png", filepath, out_base],
            capture_output=True, timeout=8)
        files = sorted(glob.glob(out_base + "*.png"))
        if files and os.path.getsize(files[0]) > 0:
            img = Image.open(files[0]).copy()
            shutil.rmtree(tmp, ignore_errors=True)
            return img
        shutil.rmtree(tmp, ignore_errors=True)
    except Exception:
        pass

    # ── Icona generica ────────────────────────────────────────────────────────
    img = Image.new("RGB", (size[0], size[1]), (240, 240, 248))
    d = ImageDraw.Draw(img)
    d.rectangle([80, 40, 360, 440], fill=(255,255,255), outline=(200,60,60), width=3)
    d.rectangle([80, 40, 360, 110], fill=(200,60,60))
    d.text((110, 55), "PDF", fill=(255,255,255))
    d.text((110, 140), pillow_safe(os.path.basename(filepath), 24), fill=(80,80,100))
    return img


def add_pdf_overlay(img, page=1, total_pages=1):
    """Sovrappone badge PDF con numero pagina nell'angolo in basso a sinistra."""
    img = img.convert("RGBA")
    w, h = img.size
    overlay = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(overlay)
    pad  = max(4, min(w, h) // 30)
    fh   = max(10, min(w, h) // 12)
    text = f"PDF {page}/{total_pages}" if total_pages > 1 else "PDF"
    char_w = max(6, fh * 6 // 10)
    bw = len(text) * char_w + pad * 3
    bh = fh + pad * 2
    x0, y0 = pad, h - bh - pad
    d.rounded_rectangle([x0, y0, x0+bw, y0+bh], radius=3,
                         fill=(180, 40, 40, 210))
    d.text((x0 + pad, y0 + pad), text, fill=(255, 255, 255, 240))
    result = Image.alpha_composite(img, overlay)
    return result.convert("RGB")



def add_play_overlay(img, alpha=180, corner=True):
    """Sovrappone un badge play nell'angolo in basso a sinistra dell'immagine."""
    img = img.convert("RGBA")
    w, h = img.size
    overlay = Image.new("RGBA", (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(overlay)
    if corner:
        # Badge piccolo nell'angolo in basso a sinistra
        r  = max(10, min(w, h) // 8)   # raggio proporzionale ma piccolo
        pad = max(4, r // 3)
        cx = pad + r
        cy = h - pad - r
    else:
        # Centro (usato per le thumbnail senza frame)
        r  = min(w, h) // 4
        cx, cy = w // 2, h // 2
    # Cerchio scuro
    d.ellipse([cx-r, cy-r, cx+r, cy+r], fill=(0, 0, 0, alpha))
    # Triangolo play
    m = r // 4
    pts = [
        (cx - r//2 + m, cy - int(r*0.55)),
        (cx - r//2 + m, cy + int(r*0.55)),
        (cx + int(r*0.65), cy),
    ]
    d.polygon(pts, fill=(255, 255, 255, 220))
    result = Image.alpha_composite(img, overlay)
    return result.convert("RGB")


_ffmpeg_lock  = threading.Lock()   # un solo ffmpeg alla volta per thumbnail
# Cache dei frame video. Era un dict semplice con espulsione del PRIMO
# inserito (una FIFO, non una LRU): il frame usato di continuo poteva
# essere buttato via mentre restavano in RAM frame visti una volta sola.
# Ora e' un OrderedDict con move_to_end ad ogni accesso, come la cache
# delle miniature.
# La chiave include la data di modifica: senza, dopo aver sostituito o
# rielaborato un video si continuava a vedere il vecchio frame finche' la
# cache non veniva svuotata.
_video_cache      = _OD()          # {(filepath, mtime): PIL.Image} — LRU
_video_cache_lock = threading.Lock()
_VIDEO_CACHE_MAX  = 30             # max entry in cache


def _video_cache_get(key):
    with _video_cache_lock:
        img = _video_cache.get(key)
        if img is not None:
            _video_cache.move_to_end(key)   # diventa la piu' recente
            return img.copy()
    return None


def _video_cache_put(key, img):
    with _video_cache_lock:
        _video_cache[key] = img
        _video_cache.move_to_end(key)
        while len(_video_cache) > _VIDEO_CACHE_MAX:
            _video_cache.popitem(last=False)   # espelle la MENO usata

def get_video_frame(filepath, size=(640, 480)):
    """Estrae un frame del video come PIL Image. Richiede ffmpeg.
    Usa cache LRU semplice per evitare re-estrazione sullo stesso file.
    Usa lock per serializzare ffmpeg ed evitare accumulo di processi."""
    try:
        _key = (filepath, os.path.getmtime(filepath))
    except OSError:
        return None                     # file sparito nel frattempo

    # Cache hit — nessun ffmpeg necessario
    _hit = _video_cache_get(_key)
    if _hit is not None:
        return _hit

    acquired = _ffmpeg_lock.acquire(timeout=8)  # attesa max 8s su sistema carico
    if not acquired:
        return None   # ffmpeg già occupato, salta

    tmp_path = None
    proc     = None
    try:
        # Ricontrolla cache dopo aver acquisito il lock (altro thread potrebbe averla popolata)
        _hit = _video_cache_get(_key)
        if _hit is not None:
            return _hit

        tmp = tempfile.NamedTemporaryFile(suffix=".jpg", delete=False)
        tmp_path = tmp.name
        tmp.close()

        def _run(seek):
            nonlocal proc
            env = os.environ.copy()
            env["LANG"] = "en_US.UTF-8"   # garantisce encoding corretto per path Unicode
            proc = subprocess.Popen(
                ["ffmpeg", "-y", "-ss", str(seek), "-i", filepath,
                 "-vframes", "1", "-q:v", "2", "-vf", "scale=640:-1",
                 tmp_path],
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                env=env)
            try:
                proc.wait(timeout=10)  # 10s: sufficiente anche per video grandi su HDD lenti
            except subprocess.TimeoutExpired:
                proc.kill()
                proc.wait()
            return proc.returncode

        rc = _run(1)
        if rc != 0 or not os.path.exists(tmp_path) or os.path.getsize(tmp_path) < 500:
            rc = _run(0)

        if rc == 0 and os.path.exists(tmp_path) and os.path.getsize(tmp_path) > 0:
            try:
                img = Image.open(tmp_path)
                img.load()   # forza lettura completa prima di unlink
                img = img.convert("RGB").copy()
            except Exception:
                return None
            _video_cache_put(_key, img.copy())
            return img

    except Exception:
        pass
    finally:
        _ffmpeg_lock.release()
        if tmp_path:
            try:
                os.unlink(tmp_path)
            except Exception:
                pass

    return None

def send_to_trash(filepath):
    """Sposta il file nel cestino di sistema (freedesktop.org)."""
    try:
        import send2trash
        send2trash.send2trash(filepath)
        return True
    except ImportError:
        pass
    try:
        trash_dir = os.path.join(os.path.expanduser("~"), ".local", "share", "Trash")
        files_dir = os.path.join(trash_dir, "files")
        info_dir  = os.path.join(trash_dir, "info")
        os.makedirs(files_dir, exist_ok=True)
        os.makedirs(info_dir,  exist_ok=True)
        fname = os.path.basename(filepath)
        dest  = os.path.join(files_dir, fname)
        base, ext = os.path.splitext(fname)
        i = 1
        while os.path.exists(dest):
            dest = os.path.join(files_dir, f"{base}_{i}{ext}")
            i += 1
        dest_name = os.path.basename(dest)
        info_path = os.path.join(info_dir, dest_name + ".trashinfo")
        with open(info_path, "w") as f:
            f.write("[Trash Info]\n")
            f.write(f"Path={filepath}\n")
            f.write(f"DeletionDate={datetime.datetime.now().strftime('%Y-%m-%dT%H:%M:%S')}\n")
        shutil.move(filepath, dest)
        return True
    except Exception:
        return False

KEYS             = ["7", "8", "9", "4", "5", "6", "1", "2", "3", "0"]
# Formati da cui i metadati EXIF si possono LEGGERE (via Pillow) e quelli
# su cui si possono RISCRIVERE (via piexif, che supporta solo JPEG e WebP:
# su TIFF e HEIC l'inserimento fallisce con un errore senza messaggio).
EXIF_READ_EXT  = {".jpg", ".jpeg", ".tiff", ".tif", ".webp", ".heic", ".heif"}
EXIF_WRITE_EXT = {".jpg", ".jpeg", ".webp"}
ROWS_LAYOUT      = [["7","8","9"], ["4","5","6"], ["1","2","3"], ["0"]]
# Ordine dei tasti per la sidebar in modalita' elenco: dal 9 in alto allo 0
# in basso, un tasto per riga. E' un ordine diverso da KEYS (che segue la
# disposizione fisica della tastiera numerica) e da ROWS_LAYOUT (la griglia
# a 3 colonne): qui conta solo l'ordine di lettura verticale richiesto.
SIDEBAR_LIST_ORDER = ["9", "8", "7", "6", "5", "4", "3", "2", "1", "0"]
IMAGE_EXTENSIONS = {".jpg", ".jpeg", ".png", ".gif", ".bmp", ".tiff", ".webp", ".avif", ".pnm", ".pbm", ".pgm", ".ppm", ".heic", ".heif"}
VIDEO_EXTENSIONS = {".mp4", ".mov", ".avi", ".mkv", ".webm", ".m4v", ".flv"}
PDF_EXTENSIONS   = {".pdf"}
MEDIA_EXTENSIONS = IMAGE_EXTENSIONS | VIDEO_EXTENSIONS | PDF_EXTENSIONS
DEFAULT_PRESET   = "Default"

# --- COLORI ------------------------------------------------------------------
BG_COLOR     = "#1a1a2e"
PANEL_COLOR  = "#16213e"
ACCENT_COLOR = "#0f3460"
HIGHLIGHT    = "#e94560"
TEXT_COLOR   = "#eaeaea"
MUTED_COLOR  = "#888888"
SUCCESS      = "#2ecc71"
WARNING      = "#f5a623"
KEY_COLORS   = [
    "#e94560", "#f5a623", "#7ed321",
    "#4a90e2", "#9b59b6", "#1abc9c",
    "#e67e22", "#2ecc71", "#3498db",
    "#e74c3c",
]
HUD_CYAN     = "#00c8ff"
PRIVACY_RED  = "#ff2020"   # bordo rosso quando file in cartella privata
PRESET_COLORS = ["#e74c3c", "#27ae60", "#2980b9"]  # Rosso, Verde, Blu per i primi 3 preset

def dim_color(hex_color, verso=BG_COLOR, quota=0.72):
    """Mescola un colore verso lo sfondo, per l'aria "spenta".

    quota=0 lascia il colore com'e', quota=1 lo porta completamente allo
    sfondo. Serve a spegnere un bottone mantenendone riconoscibile la
    tinta: cambiando colore del tutto non si capirebbe piu' quale tasto e'.
    """
    try:
        a = hex_color.lstrip("#")
        b = verso.lstrip("#")
        out = []
        for i in (0, 2, 4):
            ca = int(a[i:i+2], 16)
            cb = int(b[i:i+2], 16)
            out.append(int(round(ca + (cb - ca) * quota)))
        return "#%02x%02x%02x" % tuple(out)
    except Exception:
        return hex_color


# --- RAGGIUNGIBILITA' DELLE DESTINAZIONI -------------------------------------
# Un preset puo' puntare a un disco esterno staccato o a una condivisione di
# rete non montata. Prima non si vedeva: si premeva il tasto e l'operazione
# falliva. Il controllo e' una chiamata al filesystem, che su un percorso di
# rete irraggiungibile puo' bloccare per secondi, quindi non va mai fatto sul
# thread dell'interfaccia: si legge dalla cache e si aggiorna in background.
_dest_avail_cache = {}            # {percorso: (scadenza, disponibile)}
_dest_avail_lock  = threading.Lock()
DEST_AVAIL_TTL    = 20            # secondi di validita' di una verifica

def dest_probe(path):
    """Verifica BLOCCANTE di una destinazione. Solo da thread secondari.

    Disponibile significa due cose insieme: la cartella esiste ed e'
    scrivibile. Un disco smontato fa fallire la prima, una cartella di
    sistema o una condivisione in sola lettura la seconda; in entrambi i
    casi premere quel tasto non funzionerebbe, quindi vanno segnalate
    allo stesso modo.
    """
    if not path:
        return True               # slot vuoto: niente da segnalare
    try:
        ok = os.path.isdir(path) and os.access(path, os.W_OK)
    except Exception:
        ok = False
    with _dest_avail_lock:
        _dest_avail_cache[path] = (time.time() + DEST_AVAIL_TTL, ok)
    return ok

def dest_available_cached(path):
    """Stato dalla cache, senza toccare il filesystem.

    Ritorna None se non e' mai stato verificato o se la verifica e'
    scaduta: chi disegna deve trattarlo come "non so ancora" e lasciare
    il bottone com'e', invece di spegnerlo per un attimo ad ogni giro.
    """
    if not path:
        return True
    with _dest_avail_lock:
        voce = _dest_avail_cache.get(path)
    if not voce:
        return None
    scadenza, ok = voce
    return ok if time.time() < scadenza else None

def dest_probe_async(paths, quando_pronto):
    """Verifica una lista di percorsi in background.

    quando_pronto viene chiamato SENZA argomenti al termine, e tocca a
    chi lo passa rimandarlo al thread principale.
    """
    unici = [p for p in dict.fromkeys(paths) if p]
    if not unici:
        return

    def _lavora():
        for p in unici:
            dest_probe(p)
        try:
            quando_pronto()
        except Exception:
            pass

    threading.Thread(target=_lavora, daemon=True).start()

def dest_paint_slots(voci):
    """Applica lo stato di raggiungibilita' ai badge delle sidebar.

    voci: lista di (badge, etichetta, tasto, percorso). Nella griglia sono
    due widget — pastiglia colorata col numero sopra, nome sotto — nell'
    elenco e' un solo bottone e l'etichetta vale None: in quel caso si
    tocca solo bg/fg del bottone, senza colorare un'etichetta che non
    esiste.
    Uno stato None (non ancora verificato) lascia l'aspetto normale: uno
    spegnimento preventivo sarebbe un falso allarme.
    """
    for badge, etichetta, k, path in voci:
        try:
            if badge is None or not badge.winfo_exists():
                continue
            spento = (dest_available_cached(path) is False)
            base   = KEY_COLORS[KEYS.index(k)] if k in KEYS else ACCENT_COLOR
            badge.config(bg=dim_color(base) if spento else base,
                         fg=MUTED_COLOR if spento else "white")
            if etichetta is not None and etichetta.winfo_exists():
                etichetta.config(
                    fg=MUTED_COLOR if spento
                    else (SUCCESS if path else TEXT_COLOR))
        except Exception:
            continue


def render_preset_keys(sorter, parent, pname, slots, is_active,
                       dest_widgets, badge_labels, folder_name_labels):
    """Disegna i dieci tasti di un preset dentro `parent`.

    Griglia a 3 colonne (default, lo storico) o elenco verticale a tutta
    larghezza, secondo get_sidebar_layout(sorter.config).

    Usata sia dalla sidebar dentro la finestra sia da quella in finestra
    separata: prima avevano lo stesso blocco ripetuto quasi parola per
    parola, e due copie identiche sono un rischio di divergenza silenziosa
    (la stessa famiglia di problema di _build_sidebar, vedi li'). sorter e'
    sempre l'ImageSorter, passato esplicitamente perche' dalla sidebar
    popup non e' self.
    """
    layout = get_sidebar_layout(sorter.config)
    lista  = (layout == "list")

    grid = tk.Frame(parent, bg=PANEL_COLOR)
    grid.pack(fill="x", padx=1, pady=(0, 1))
    for gi in range(3):
        grid.columnconfigure(gi, weight=1)

    # In modalita' elenco ogni tasto occupa una riga intera, dal 9 in alto
    # allo 0 in basso: e' l'ordine chiesto esplicitamente, diverso sia da
    # KEYS (la disposizione fisica della tastierina) sia da ROWS_LAYOUT
    # (la griglia a 3 colonne).
    righe = [[k] for k in SIDEBAR_LIST_ORDER] if lista else ROWS_LAYOUT

    row_idx = 0
    for row_keys in righe:
        for col_idx, k in enumerate(row_keys):
            color    = KEY_COLORS[KEYS.index(k)]
            colspan  = 3 if (lista or k == "0") else 1
            has_dest = bool(slots[k].get('path', '').strip())
            lbl      = slots[k].get('label', '') if has_dest else ''
            cell = tk.Frame(grid, bg=PANEL_COLOR)
            # In elenco meno margine verticale fra una riga e l'altra:
            # e' proprio quello che stringe la colonna, oltre al font.
            cell.grid(row=row_idx, column=col_idx, columnspan=colspan,
                      sticky="nsew", padx=1, pady=(0, 1) if lista else 1)

            if lista:
                # Un solo bottone colorato per tasto: numero ed etichetta
                # nello stesso widget, niente riquadro separato sotto.
                # Rispetto alla griglia si perde la distinzione di colore
                # fra "ha una destinazione" e "slot vuoto" (li' era il
                # verde/grigio del testo): qui la conta gia' il numero
                # da solo, senza etichetta accanto.
                maxlen  = 30
                short_l = lbl if len(lbl) <= maxlen else lbl[:maxlen-1] + "."
                testo   = f"{k}   {short_l}" if short_l else k
                btn = tk.Button(cell, text=testo,
                                font=("TkFixedFont", 8, "bold"),
                                bg=color, fg="white", anchor="w", padx=10,
                                activebackground=HIGHLIGHT, activeforeground="white",
                                relief="flat", bd=0,
                                command=lambda key=k, p=pname: sorter._move_to_preset(key, p))
                btn.pack(fill="x", ipady=1)
                btn.bind("<Button-3>",
                         lambda e, key=k, p=pname: sorter._quick_set_dest(key, p, e))
                # dest_paint_slots si aspetta la coppia (badge, etichetta):
                # qui il secondo elemento e' None, cosi' tocca solo bg/fg
                # dell'unico widget invece di colorare anche un'etichetta
                # che non esiste piu'.
                dest_widgets.append(
                    (btn, None, k, resolve_path(slots[k]) if has_dest else ""))
                if is_active:
                    badge_labels[k]       = btn
                    folder_name_labels[k] = None
                continue

            # --- griglia: badge del numero sopra, nome sotto (storico) ---
            short_l = lbl if len(lbl) <= 11 else lbl[:10] + "."
            badge = tk.Button(cell, text=k,
                              font=("TkFixedFont", 9, "bold"),
                              bg=color, fg="white",
                              activebackground=HIGHLIGHT, activeforeground="white",
                              relief="flat", bd=0,
                              command=lambda key=k, p=pname: sorter._move_to_preset(key, p))
            badge.pack(fill="x")
            name_btn = tk.Button(cell, text=short_l,
                                 font=("TkFixedFont", 7),
                                 bg=PANEL_COLOR,
                                 fg=SUCCESS if has_dest else TEXT_COLOR,
                                 activebackground=PANEL_COLOR, activeforeground=HIGHLIGHT,
                                 relief="flat", bd=0,
                                 command=lambda key=k, p=pname: sorter._move_to_preset(key, p))
            name_btn.pack(fill="x", pady=(0, 1))
            # Tasto destro: modifica o elimina destinazione del tasto
            for _w in (badge, name_btn):
                _w.bind("<Button-3>",
                        lambda e, key=k, p=pname: sorter._quick_set_dest(key, p, e))
            dest_widgets.append(
                (badge, name_btn, k,
                 resolve_path(slots[k]) if has_dest else ""))
            if is_active:
                badge_labels[k]       = badge
                folder_name_labels[k] = name_btn
        row_idx += 1


def preset_color(config, preset_name, fallback=None):
    """Ritorna il colore RGB per il preset (rosso/verde/blu per i primi 3)."""
    names = list(config.get("presets", {}).keys())
    idx = names.index(preset_name) if preset_name in names else -1
    if 0 <= idx < len(PRESET_COLORS):
        return PRESET_COLORS[idx]
    return fallback or HUD_CYAN

HUD_DIM      = "#1a3a5a"

def _tooltip(widget, text):
    """Mostra un tooltip al passaggio del mouse."""
    tip = [None]
    def _show(e):
        if tip[0] and tip[0].winfo_exists():
            return
        t = tk.Toplevel(widget)
        t.wm_overrideredirect(True)
        t.configure(bg=PANEL_COLOR)
        tk.Label(t, text=text, font=("TkFixedFont", 7),
                 bg=PANEL_COLOR, fg=TEXT_COLOR,
                 padx=6, pady=3).pack()
        x = widget.winfo_rootx() + 20
        y = widget.winfo_rooty() + widget.winfo_height() + 2
        t.wm_geometry(f"+{x}+{y}")
        tip[0] = t
    def _hide(e):
        if tip[0] and tip[0].winfo_exists():
            tip[0].destroy()
        tip[0] = None
    widget.bind("<Enter>", _show, add=True)
    widget.bind("<Leave>", _hide, add=True)


def hud_apply(win, color=None):
    """Aggiunge bordo HUD ciano alla finestra usando un frame bordo."""
    c = color or HUD_CYAN
    # Applica un bordo colorato alla finestra tramite highlightbackground
    try:
        win.config(highlightbackground=c, highlightthickness=2,
                   highlightcolor=c)
    except Exception:
        pass

def _Tf(it_template, lang, **kwargs):
    """Traduce un template IT con placeholder e formatta con kwargs.
    Es: _Tf("Cestinati {n} file.", lang, n=3) → "3 file(s) trashed."
    """
    if lang == "it" or not _IT_EN_FROM_FILE:
        return it_template.format(**kwargs) if kwargs else it_template
    translated = _IT_EN_FROM_FILE.get(it_template, it_template)
    return translated.format(**kwargs) if kwargs else translated

def default_slot(key):
    return {"label": "", "path": ""}

def default_preset():
    return {k: default_slot(k) for k in KEYS}

def migrate_old_preset(old):
    """Converte il vecchio formato {key: "nome"} nel nuovo {key: {label, path}}."""
    new = {}
    for k in KEYS:
        v = old.get(k, f"Cartella_{k}")
        if isinstance(v, dict):
            new[k] = {"label": v.get("label", ""),
                      "path":  v.get("path", "")}
        else:
            new[k] = {"label": str(v), "path": ""}
    return new

def normalize_config_paths(config):
    """Adatta i percorsi salvati nel config all'utente corrente."""
    current_home = os.path.expanduser("~")
    current_user = os.path.basename(current_home)
    def fix(val):
        if not isinstance(val, str):
            return val
        # Sostituisce /home/altro_utente/ con /home/utente_corrente/
        if val.startswith("/home/"):
            parts = val.split("/", 3)
            if len(parts) >= 3 and parts[2] != current_user:
                parts[2] = current_user
                return "/".join(parts)
        return val
    for slots in config.get("presets", {}).values():
        for slot in slots.values():
            if isinstance(slot, dict) and "path" in slot:
                slot["path"] = fix(slot["path"])
    if "last_source" in config:
        config["last_source"] = fix(config["last_source"])
    return config

def load_config():
    # Rileva lingua di sistema: italiano se LANG inizia con "it", inglese altrimenti
    _sys_lang = os.environ.get("LANG", "").lower()
    _default_lang = "it" if _sys_lang.startswith("it") else "en"

    default = {
        "active_preset":   DEFAULT_PRESET,
        "presets":         {DEFAULT_PRESET: default_preset()},
        "sidebar_mode":    "inline",
        "sidebar_layout":  "grid",     # "grid" (badge 3 col.) o "list" (elenco verticale)
        "sidebar_presets": 3,
        "keypad_cols":     3,
        "keypad_cols_configured": 3,
        "crop_remember":   False,
        "crop_snap_edges": True,
        "show_images":     True,
        "show_videos":     True,
        "show_pdfs":       True,
        "show_no_ext":     True,
        "language":        _default_lang,
        "backup_limit_mb": BACKUP_LIMIT_MB_DEFAULT,
        "backup_dir":       "",   # vuoto = usa BACKUP_DIR default
        "trash_transit_dir": "",  # vuoto = usa TRASH_TRANSIT_DIR default
        "trash_transit_ask_on_quit": True,
        "trash_transit_limit_mb": TRASH_TRANSIT_LIMIT_MB_DEFAULT,
        # Data (ISO) in cui e' stato scelto "Oggi non chiedere piu'" nel
        # popup del cestino di transito; vuoto = chiedi normalmente.
        "trash_transit_skip_date": "",
    }
    if not os.path.isfile(CONFIG_FILE):
        return default
    try:
        with open(CONFIG_FILE) as f:
            data = json.load(f)
        if "presets" not in data:
            # Vecchio formato piatto
            old = {k: data.get(k, f"Cartella_{k}") for k in KEYS}
            data = {"active_preset": DEFAULT_PRESET,
                    "presets": {DEFAULT_PRESET: migrate_old_preset(old)}}
        else:
            for pname in list(data["presets"].keys()):
                data["presets"][pname] = migrate_old_preset(data["presets"][pname])
        if data.get("active_preset") not in data["presets"]:
            data["active_preset"] = next(iter(data["presets"]))
        return normalize_config_paths(data)
    except Exception:
        return default

def _json_is_flat_leaf(v):
    """Un valore ammesso dentro un blocco compatto: uno scalare, oppure
    una lista di soli scalari (es. "color": [15, 20, 40]).

    Un dizionario, o una lista che contiene a sua volta dizionari o
    liste, NON e' ammesso: se lo fosse, l'intero contenitore finirebbe
    su una riga sola nascondendo la struttura vera — per esempio l'elenco
    dei dieci tasti di una pagina del deck, che invece deve restare
    leggibile uno per riga.
    """
    if isinstance(v, dict):
        return False
    if isinstance(v, list):
        return all(not isinstance(x, (dict, list)) for x in v)
    return True

def _json_is_flat(value):
    """True se value (un dizionario o una lista) puo' stare su una riga
    sola: ogni suo elemento e' un _json_is_flat_leaf. Un preset o uno
    slot del deck ("label", "path", "color"...) e' sempre cosi', mentre
    il dizionario dei preset o la lista delle pagine non lo sono, perche'
    i loro valori sono a loro volta dizionari (altri preset, altri tasti).
    """
    if isinstance(value, dict):
        vals = value.values()
    elif isinstance(value, list):
        vals = value
    else:
        return True
    return all(_json_is_flat_leaf(v) for v in vals)

def _json_pretty(obj, level=0, indent="  "):
    """Serializza in JSON con una regola in piu' rispetto a json.dumps:
    un dizionario o una lista "piatta" (solo scalari dentro, vedi
    _json_is_flat) sta su una riga sola, invece che una riga per chiave.

    Il file che il programma scrive aveva ogni singolo campo di ogni
    singolo tasto del deck su una riga a se' — decine di righe identiche
    per pagina, dove capire "questa e' la pagina 2" richiedeva contare le
    parentesi graffe. Qui un preset o uno slot del deck restano
    riconoscibili a colpo d'occhio come un blocco solo, e la struttura
    generale (quali preset ci sono, quante pagine) resta comunque
    indentata e leggibile.
    """
    pad, pad_in = indent * level, indent * (level + 1)

    if isinstance(obj, dict):
        if not obj:
            return "{}"
        if _json_is_flat(obj):
            parti = ", ".join(
                f"{json.dumps(k, ensure_ascii=False)}: "
                f"{json.dumps(v, ensure_ascii=False)}"
                for k, v in obj.items())
            return "{" + parti + "}"
        righe = [f'{pad_in}{json.dumps(k, ensure_ascii=False)}: '
                f'{_json_pretty(v, level + 1, indent)}'
                for k, v in obj.items()]
        return "{\n" + ",\n".join(righe) + "\n" + pad + "}"

    if isinstance(obj, list):
        if not obj:
            return "[]"
        if _json_is_flat(obj):
            parti = ", ".join(json.dumps(v, ensure_ascii=False) for v in obj)
            return "[" + parti + "]"
        righe = [f"{pad_in}{_json_pretty(v, level + 1, indent)}" for v in obj]
        return "[\n" + ",\n".join(righe) + "\n" + pad + "]"

    return json.dumps(obj, ensure_ascii=False)

CONFIG_NOTE = (
    "File generato da Image Sorter, di solito non serve modificarlo a "
    "mano. Le chiavi che iniziano con '_' sono solo spiegazioni, il "
    "programma le ignora e le riscrive ad ogni salvataggio: cancellarle o "
    "modificarle non ha effetto e non rompe nulla. 'presets' e' un "
    "dizionario {nome preset: {tasto: {label, path}}}: il nome del "
    "preset e' gia' la chiave, quindi si riconosce da solo. "
    "'deck_idle_pages' e' una lista di pagine del deck fisico; ogni "
    "pagina e' una lista di tasti nell'ordine mostrato nella griglia di "
    "Impostazioni > Deck (il primo elemento della lista e' 'Pagina 1' "
    "in quella finestra, il secondo 'Pagina 2', e cosi' via)."
)

def save_config(data):
    # La nota va in testa e si aggiorna ad ogni salvataggio: se data
    # contiene gia' una "_note" (riletta da un salvataggio precedente),
    # va scartata qui, altrimenti .update() la lascerebbe vincere e la
    # nota mostrata resterebbe quella vecchia.
    out = {"_note": CONFIG_NOTE}
    for k, v in data.items():
        if k != "_note":
            out[k] = v
    with open(CONFIG_FILE, "w") as f:
        f.write(_json_pretty(out))

def _auto_backup_snapshot():
    """Copia di sicurezza automatica e silenziosa di config, storico e
    metadata, una volta al giorno all'avvio, in
    backup_auto/AAAA-MM-GG/. Aggiuntiva rispetto ai backup manuali
    di Carlo (cartelle di versione, backup/): qui basta avviare il
    programma per avere sempre uno scatto recente, anche se nessuno se
    ne ricorda a mano — nato da due incidenti (22 e 23/08/2026) in cui
    image_sorter_config.json e' stato cancellato per errore fuori dal
    programma, senza alcuna rete di sicurezza automatica.

    Un solo scatto al giorno: se la cartella di oggi esiste gia' non
    viene rifatta (non sovrascrive mai uno scatto del giorno con uno
    stato eventualmente gia' danneggiato piu' tardi nella stessa
    giornata) ne' cancellata. Rotazione: tiene solo gli ultimi
    AUTO_BACKUP_KEEP_DAYS giorni. Non deve MAI bloccare l'avvio: ogni
    errore viene ignorato in silenzio."""
    try:
        day_dir = os.path.join(AUTO_BACKUP_DIR, time.strftime("%Y-%m-%d"))
        if os.path.isdir(day_dir):
            return
        sources = [CONFIG_FILE, HISTORY_FILE]
        meta_file = getattr(metadata_store, "METADATA_FILE", None)
        if meta_file:
            sources.append(meta_file)
        existing = [p for p in sources if os.path.isfile(p)]
        if not existing:
            return
        os.makedirs(day_dir, exist_ok=True)
        for p in existing:
            shutil.copy2(p, os.path.join(day_dir, os.path.basename(p)))
        giorni = sorted(d for d in os.listdir(AUTO_BACKUP_DIR)
                        if os.path.isdir(os.path.join(AUTO_BACKUP_DIR, d)))
        for vecchio in giorni[:-AUTO_BACKUP_KEEP_DAYS]:
            shutil.rmtree(os.path.join(AUTO_BACKUP_DIR, vecchio), ignore_errors=True)
    except Exception:
        pass

def _delete_history_thumb(entry):
    """Rimuove il file miniatura associato a una entry dello storico, se
    presente. Silenzioso in caso di errore: la miniatura è un dettaglio
    visivo, non deve mai bloccare la gestione dello storico."""
    name = entry.get("thumb") if isinstance(entry, dict) else None
    if not name:
        return
    try:
        path = os.path.join(HISTORY_THUMBS_DIR, name)
        if os.path.isfile(path):
            os.remove(path)
    except Exception:
        pass

def _make_history_thumb(source_path):
    """Crea una piccola anteprima JPEG per una entry dello storico, salvata
    nella cartella temporanea dedicata (stessa area dei file di lavoro
    dell'app — non i file originali dell'utente). Ritorna solo il NOME del
    file (non il percorso assoluto, per restare portabile se la cartella
    home cambia posizione), o stringa vuota se non disponibile/non
    supportato. La cartella viene ripulita automaticamente quando le entry
    più vecchie escono dal limite dello storico o quando l'elenco viene
    svuotato (si vedano save_history() e _history_clear())."""
    if not source_path or not os.path.isfile(source_path):
        return ""
    try:
        media = detect_media_type(source_path)
        if media in VIDEO_EXTENSIONS:
            img = get_video_frame(source_path)
        elif media in PDF_EXTENSIONS:
            img = get_pdf_preview(source_path, page=1)
        else:
            img = Image.open(source_path)
            # Draft mode: decodifica diretta a risoluzione ridotta per i
            # JPEG grandi, invece di decodificare tutto e poi rimpicciolire
            # (stessa ottimizzazione già usata in make_thumb()).
            ext = os.path.splitext(source_path)[1].lower()
            if hasattr(img, "draft") and ext in (".jpg", ".jpeg"):
                img.draft("RGB", (HISTORY_THUMB_SIZE * 2, HISTORY_THUMB_SIZE * 2))
            img = ImageOps.exif_transpose(img)   # orientamento corretto
            # Sicurezza memoria: immagini enormi (es. panorami, scansioni)
            # vengono prima ridotte velocemente prima del rimpicciolimento
            # di qualità finale.
            if img.width * img.height > 4000 * 4000:
                img.thumbnail((2000, 2000), Image.NEAREST)
        if img is None:
            return ""
        img = img.convert("RGB")
        img.thumbnail((HISTORY_THUMB_SIZE, HISTORY_THUMB_SIZE), Image.LANCZOS)
        os.makedirs(HISTORY_THUMBS_DIR, exist_ok=True)
        fname = hashlib.md5(
            f"{source_path}{time.time_ns()}".encode()).hexdigest()[:20] + ".jpg"
        img.save(os.path.join(HISTORY_THUMBS_DIR, fname), "JPEG", quality=82)
        return fname
    except Exception:
        return ""

def load_history():
    """Carica lo storico operazioni dal file JSON persistente."""
    try:
        if os.path.isfile(HISTORY_FILE):
            with open(HISTORY_FILE, encoding="utf-8") as f:
                data = json.load(f)
                return data if isinstance(data, list) else []
    except Exception:
        pass
    return []

# Lock per serializzare le scritture sul file storico: la miniatura viene
# ora generata in un thread separato (si veda append_history) e patchata
# nello storico al termine — senza un lock, un annullamento eseguito nello
# stesso istante potrebbe leggere/scrivere il file concorrentemente e far
# perdere l'una o l'altra modifica (read-modify-write non atomico).
_history_lock = threading.Lock()

def save_history(entries):
    """Salva lo storico su file JSON (max HISTORY_MAX entry). Le entry più
    vecchie eventualmente scartate dal limite hanno la miniatura associata
    rimossa dalla cartella temporanea, per non lasciare file orfani."""
    try:
        if len(entries) > HISTORY_MAX:
            for old_entry in entries[:-HISTORY_MAX]:
                _delete_history_thumb(old_entry)
            entries = entries[-HISTORY_MAX:]
        with open(HISTORY_FILE, "w", encoding="utf-8") as f:
            json.dump(entries, f, indent=2, ensure_ascii=False)
    except Exception:
        pass

def find_history_entry(filepath, days=10):
    """Cerca nello storico una entry recente (entro `days` giorni) per filepath.
    Ritorna la entry più recente trovata, o None.
    Considera: moved (dest=filepath attuale), moved_browser, moved_timeline,
    moved_timeline_batch, cropped (files[0]=filepath).
    """
    import datetime
    cutoff = datetime.datetime.now() - datetime.timedelta(days=days)
    entries = load_history()
    best = None
    for entry in reversed(entries):   # dal più recente
        try:
            ts = datetime.datetime.strptime(
                entry.get("timestamp", ""), "%Y-%m-%d %H:%M:%S")
        except ValueError:
            continue
        if ts < cutoff:
            continue
        action = entry.get("action", "")
        files  = entry.get("files", [])
        dest   = entry.get("dest",  "")
        # Per spostamenti: dest è dove è andato il file (path attuale)
        if action in ("moved", "moved_browser", "moved_timeline"):
            if dest == filepath:
                return entry
        elif action == "renamed_batch":
            if filepath in (entry.get("dests") or []):
                return entry
        elif action in ("copied_browser", "moved_browser_batch"):
            if filepath in (entry.get("dests") or []):
                return entry
        elif action == "geotag_batch":
            # Il file non si sposta ne' cambia nome: basta che sia
            # nell'elenco di quelli a cui e' stata scritta la posizione.
            if filepath in files:
                return entry
        elif action == "moved_timeline_batch":
            dest_dir = dest
            if filepath in (entry.get("dests") or []):
                return entry
            for orig in files:
                if os.path.join(dest_dir, os.path.basename(orig)) == filepath:
                    return entry
        # Per crop/resize: files[0] è il file modificato (path attuale)
        elif action in ("cropped", "resized"):
            if files and files[0] == filepath:
                return entry
        # Per "taglia" in attesa: il file, alla sua posizione ATTUALE,
        # e' nella cartella di attesa (dest) — come per "moved" e affini,
        # non nell'origine, dove ormai non c'e' piu' nulla da cliccare.
        elif action == "cut_staged":
            if dest == filepath:
                return entry
    return best

def append_history(entry):
    """Aggiunge una entry allo storico persistente e salva.
    entry: dict con keys: action, files, dest, note
    Non registra operazioni su file in cartelle private.

    La miniatura di anteprima NON viene generata qui: aprire l'immagine,
    correggerne l'orientamento ed eventualmente estrarre un frame video
    (via ffmpeg) può richiedere un tempo non trascurabile, soprattutto sui
    video — e questa funzione viene chiamata in linea, sul thread
    principale, ad ogni singolo spostamento con i tasti 1-9 (l'azione più
    frequente in assoluto durante lo smistamento). La entry viene quindi
    salvata subito senza miniatura, e la miniatura viene generata in un
    thread separato che la aggiunge allo storico appena pronta, senza
    bloccare l'operazione in corso.
    """
    import datetime
    # Protezione privacy: non registrare file in cartelle private
    private_folders = _load_private_folders()
    if private_folders:
        files = entry.get("files", [])
        if any(_is_private(f, private_folders) for f in files):
            return
    entry["timestamp"] = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    entry["id"] = hashlib.md5(
        f"{entry['timestamp']}{time.time_ns()}{os.getpid()}".encode()
        ).hexdigest()[:16]
    entry["thumb"] = ""
    with _history_lock:
        entries = load_history()
        entries.append(entry)
        save_history(entries)

    # Posizione ATTUALE del file da cui generare la miniatura: 'dest' se
    # presente e valida (dopo uno spostamento o un ritaglio il file si
    # trova ormai lì), altrimenti il primo path in 'files' (es. rotazioni,
    # che non cambiano posizione).
    thumb_src = entry.get("dest") or ""
    if not (thumb_src and os.path.isfile(thumb_src)):
        # Nelle voci di tipo batch 'dest' è una CARTELLA, non un file:
        # os.path.isfile() falliva e si ripiegava su files[0], che è il
        # percorso ORIGINALE — ormai vuoto, perché i file sono appena
        # stati spostati. Risultato: le voci batch non avevano mai
        # l'anteprima nello Storico. Si cerca ora, in ordine: le
        # destinazioni reali ('dests'), i percorsi originali (validi per
        # rotazioni e simili, che non spostano nulla) e infine, per le
        # voci più vecchie senza 'dests', il nome originale dentro la
        # cartella di destinazione.
        thumb_src = ""
        for _cand in (list(entry.get("dests") or []) +
                      list(entry.get("files") or [])):
            if _cand and os.path.isfile(_cand):
                thumb_src = _cand
                break
        if not thumb_src:
            _ddir = entry.get("dest") or ""
            if _ddir and os.path.isdir(_ddir):
                for _f in (entry.get("files") or []):
                    _c = os.path.join(_ddir, os.path.basename(_f))
                    if os.path.isfile(_c):
                        thumb_src = _c
                        break
    if thumb_src:
        threading.Thread(target=_update_history_thumb_async,
                         args=(entry["id"], thumb_src), daemon=True).start()

def _update_history_thumb_async(entry_id, thumb_src):
    """Genera la miniatura (lavoro potenzialmente lento: apertura immagine,
    estrazione frame video, rasterizzazione PDF) e la aggiunge alla entry
    corrispondente nello storico, individuata tramite il suo 'id' univoco
    invece che tramite indice di posizione (che nel frattempo potrebbe
    essere cambiato per un annullamento o un troncamento). Se la entry non
    viene più trovata (es. già annullata prima che la miniatura fosse
    pronta), la miniatura appena creata viene scartata subito."""
    fname = _make_history_thumb(thumb_src)
    if not fname:
        return
    with _history_lock:
        entries = load_history()
        for e in entries:
            if e.get("id") == entry_id:
                e["thumb"] = fname
                save_history(entries)
                return
    _delete_history_thumb({"thumb": fname})

def _get_backup_dir(config=None):
    """Ritorna la cartella backup attiva (da config o default)."""
    if config:
        custom = config.get("backup_dir", "").strip()
        if custom and os.path.isdir(custom):
            return custom
    return BACKUP_DIR

def _backup_limit_bytes(config):
    """Ritorna il limite backup in bytes dalla config (default 500 MB)."""
    mb = config.get("backup_limit_mb", BACKUP_LIMIT_MB_DEFAULT)
    try:
        return int(mb) * 1024 * 1024
    except Exception:
        return BACKUP_LIMIT_MB_DEFAULT * 1024 * 1024

def _backup_dir_size(config=None):
    """Calcola dimensione totale della cartella backup in bytes."""
    bdir = _get_backup_dir(config)
    total = 0
    if not os.path.isdir(bdir):
        return 0
    for dirpath, _, files in os.walk(bdir):
        for f in files:
            try:
                total += os.path.getsize(os.path.join(dirpath, f))
            except OSError:
                pass
    return total

def _backup_enforce_limit(config):
    """Rimuove i backup più vecchi finché la dimensione è sotto il limite."""
    limit = _backup_limit_bytes(config)
    bdir  = _get_backup_dir(config)
    if not os.path.isdir(bdir):
        return
    all_files = []
    for dirpath, _, files in os.walk(bdir):
        for f in files:
            fp = os.path.join(dirpath, f)
            try:
                all_files.append((os.path.getmtime(fp), fp))
            except OSError:
                pass
    all_files.sort()
    total = sum(os.path.getsize(fp) for _, fp in all_files
                if os.path.isfile(fp))
    for _, fp in all_files:
        if total <= limit:
            break
        try:
            sz = os.path.getsize(fp)
            os.remove(fp)
            total -= sz
            day_dir = os.path.dirname(fp)
            if os.path.isdir(day_dir) and not os.listdir(day_dir):
                os.rmdir(day_dir)
        except OSError:
            pass

def make_crop_backup(filepath, config):
    """Crea un backup del file prima del crop in <backup_dir>/YYYY-MM-DD/.
    Ritorna il path del backup, o None se fallisce.
    Non crea backup se il file è in una cartella privata."""
    import datetime, shutil
    # Protezione privacy: non backuppare file in cartelle private
    private_folders = _load_private_folders()
    if private_folders and _is_private(filepath, private_folders):
        return None
    try:
        bdir = _get_backup_dir(config)
        os.makedirs(bdir, exist_ok=True)
        day     = datetime.datetime.now().strftime("%Y-%m-%d")
        day_dir = os.path.join(bdir, day)
        os.makedirs(day_dir, exist_ok=True)
        fname     = os.path.basename(filepath)
        base, ext = os.path.splitext(fname)
        ts        = datetime.datetime.now().strftime("%H%M%S")
        dest      = os.path.join(day_dir, f"{base}_{ts}{ext}")
        shutil.copy2(filepath, dest)
        _backup_enforce_limit(config)
        return dest
    except Exception:
        return None

def get_keypad_cols(config):
    """Numero di colonne preset nel tastierino (1, 2 o 3)."""
    return max(1, min(8, int(config.get("keypad_cols", 3))))

def get_sidebar_mode(config):
    """Modalita sidebar: hidden / inline / popup."""
    return config.get("sidebar_mode", "inline")

def get_sidebar_layout(config):
    """Aspetto della sidebar: "grid" (badge numero+nome a 3 colonne, lo
    storico) o "list" (un tasto per riga, ordine 9->0, etichetta a tutta
    larghezza). Non riguarda il deck, che resta a griglia: li' il
    trascinamento per scambiare due tasti si basa sulla posizione a
    griglia, e un elenco verticale cambierebbe quella geometria."""
    return config.get("sidebar_layout", "grid")

def get_sidebar_presets(config):
    """Numero di preset visibili nella sidebar (1, 2 o 3)."""
    return max(1, min(3, int(config.get("sidebar_presets", 3))))

def fmt_size(n):
    """Formatta dimensione file in B/KB/MB."""
    if n < 1024:      return f"{n} B"
    if n < 1024 ** 2: return f"{n/1024:.1f} KB"
    return f"{n/1024**2:.1f} MB"


def sanitize_name(name):
    for ch in '/\\:*?"<>|':
        name = name.replace(ch, "")
    return name.strip()

def resolve_path(slot):
    """Restituisce il percorso assoluto della cartella per uno slot."""
    p = slot.get("path", "").strip()
    if p and os.path.isabs(p):
        return p
    label = slot.get("label", "Cartella") or "Cartella"
    return os.path.join(BASE_DEST, label)

# =============================================================================
# SELEZIONE PRESET
# =============================================================================

# =============================================================================
# DIALOGO CONFIGURAZIONE CARTELLE (rinomina + percorso libero)
# =============================================================================

# =============================================================================
# CLIPBOARD FILE — INTEROPERABILE CON IL SISTEMA OPERATIVO
# =============================================================================
# Prima Naviga usava una lista Python interna (self._clipboard_files),
# mai collegata alla vera clipboard X11: copiare qui e incollare in
# Nemo/Nautilus/Thunar (o viceversa) non funzionava affatto — segnalato
# da Carlo. Queste due funzioni condivise (usate sia da Naviga che da
# Timeline) sostituiscono quel meccanismo con la selezione CLIPBOARD
# vera.
#
# Passano da "xclip" (comando esterno) come meccanismo principale,
# invece che dal supporto nativo di Tkinter — trovati DUE difetti reali
# di quest'ultimo con un test diretto, non solo per sospetto:
#   1. Tkinter DICHIARA di rispondere alla richiesta ICCCM "MULTIPLE"
#      (compare nel suo stesso elenco TARGETS) ma se interrogato
#      davvero risponde "target MULTIPLE not available" — molti
#      lettori GTK (Nemo/Nautilus) la usano di serie per leggere piu'
#      formati in una sola richiesta, e se fallisce puo' risultare in
#      "niente da incollare" anche se scrittura e rilettura dallo
#      stesso processo funzionavano (esattamente il caso di Carlo,
#      confermato: copia poi incolla subito, nessun errore nel log, ma
#      niente da incollare).
#   2. Leggendo con Tkinter una selezione posseduta da un programma
#      ESTERNO vero (non un altro widget dello stesso interprete
#      Python) in un formato non testuale nativo, il contenuto torna
#      come sequenza di byte non decodificata invece del testo vero.
# "xclip" e' un programma maturo, usato da moltissimi strumenti Linux
# apposta per questo tipo di interoperabilita', e non soffre di nessuno
# dei due problemi (verificato con test diretti). Tkinter resta come
# riserva, usata solo se "xclip" non e' installato sul sistema.
#
# Un solo formato alla volta: x-special/gnome-copied-files (quello che
# Nemo/Nautilus/Caja controllano per primo, include gia' l'
# informazione taglia/copia) invece di text/uri-list — scelta per
# l'ambiente di Carlo (Cinnamon/Nemo). Se in futuro serve piu'
# compatibilita' con file manager che leggono SOLO text/uri-list (es.
# alcuni ambienti KDE), va rivista: xclip puo' servire un solo target
# per invocazione, non entrambi insieme.
#
# Limite noto, condiviso dalla maggior parte dei programmi Linux: la
# selezione resta leggibile solo finche' il processo che l'ha impostata
# resta aperto — non c'e' un "clipboard manager" di sistema a mantenerla
# viva oltre (alcuni desktop environment lo offrono via un programma a
# parte, es. clipit/parcellite — al di fuori del controllo di questo
# programma). Con xclip come scrittore, e' il processo xclip stesso
# (non Image Sorter) a dover restare vivo — si stacca da solo in
# background, sopravvive anche se Naviga/Timeline vengono chiusi, e
# si chiude da solo quando qualcun altro rivendica la selezione.

_xclip_available = None   # calcolato una sola volta, poi tenuto in cache

def _has_xclip():
    global _xclip_available
    if _xclip_available is None:
        _xclip_available = shutil.which("xclip") is not None
    return _xclip_available


def _os_clipboard_set_files(widget, paths, cut=False):
    """Registra i file sulla clipboard REALE del sistema operativo —
    tramite xclip se disponibile (vedi commento sopra sul perche'),
    altrimenti tramite il supporto nativo di Tkinter.

    Ritorna True se ha usato xclip (interoperabilita' con file manager
    esterni garantita), False se e' dovuta ricadere sul metodo nativo
    di Tkinter (che funziona solo all'interno del programma stesso, per
    via del difetto MULTIPLE — vedi il commento sopra). I chiamanti
    usano questo per avvisare chiaramente l'utente invece di lasciarlo
    scoprire il limite in silenzio."""
    uris = []
    for p in paths:
        try:
            uris.append("file://" + urllib.parse.quote(os.path.abspath(p)))
        except Exception:
            continue
    if not uris:
        return True
    gnome_data = ("cut" if cut else "copy") + "\n" + "\n".join(uris)

    if _has_xclip():
        try:
            # stderr=DEVNULL, NON subprocess.PIPE: xclip si stacca in
            # background per continuare a servire la selezione dopo
            # aver letto stdin, e il processo figlio EREDITA la pipe di
            # stderr, tenendola aperta — Python resta in attesa che si
            # chiuda per sempre (fino al timeout), anche se il processo
            # "principale" e' gia' uscito. Trovato con un test diretto:
            # da riga di comando xclip torna in 5 millisecondi, con una
            # pipe stderr impiegava sempre esattamente il timeout
            # intero. Questo e' quello che faceva ricadere silenziosamente
            # sul metodo Tk (col suo difetto MULTIPLE) anche quando xclip
            # era installato e funzionante.
            proc = subprocess.Popen(
                ["xclip", "-selection", "clipboard", "-t",
                 "x-special/gnome-copied-files"],
                stdin=subprocess.PIPE,
                stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            proc.communicate(input=gnome_data.encode("utf-8"), timeout=3)
            if proc.returncode == 0:
                return True
            log_error(f"Copia file via xclip: uscita con codice "
                     f"{proc.returncode}", tag="os_clipboard_set_xclip")
        except Exception as _ex:
            log_error(f"Copia file via xclip fallita: {_ex}",
                     tag="os_clipboard_set_xclip")
        # Se xclip e' fallito, si prova comunque col metodo nativo
        # invece di rinunciare del tutto.

    uri_list_data = "\r\n".join(uris) + "\r\n"
    text_data = "\n".join(paths)

    def _h_uri(offset, maxchars):
        offset, maxchars = int(offset), int(maxchars)
        return uri_list_data[offset:offset + maxchars]

    def _h_gnome(offset, maxchars):
        offset, maxchars = int(offset), int(maxchars)
        return gnome_data[offset:offset + maxchars]

    def _h_text(offset, maxchars):
        offset, maxchars = int(offset), int(maxchars)
        return text_data[offset:offset + maxchars]

    try:
        widget.selection_own(selection="CLIPBOARD")
        widget.selection_handle(_h_uri, selection="CLIPBOARD", type="text/uri-list")
        widget.selection_handle(_h_gnome, selection="CLIPBOARD",
                                type="x-special/gnome-copied-files")
        widget.selection_handle(_h_text, selection="CLIPBOARD", type="STRING")
        widget.selection_handle(_h_text, selection="CLIPBOARD", type="UTF8_STRING")
        widget.update()
        return False
    except tk.TclError as _ex:
        log_error(f"Copia file negli appunti di sistema fallita: {_ex}",
                 tag="os_clipboard_set")
        return False


def _os_clipboard_get_files(widget):
    """Legge la clipboard di sistema per un elenco di file — tramite
    xclip se disponibile (stessa ragione della scrittura: piu'
    affidabile del supporto nativo di Tkinter con selezioni possedute
    da programmi esterni), altrimenti tramite Tkinter. Ritorna
    (lista_percorsi, e_un_taglia); lista vuota se la clipboard non
    contiene file (es. solo testo semplice, o e' vuota del tutto)."""
    for _type in ("x-special/gnome-copied-files", "text/uri-list"):
        data = None
        if _has_xclip():
            try:
                proc = subprocess.run(
                    ["xclip", "-selection", "clipboard", "-t", _type, "-o"],
                    capture_output=True, timeout=3)
                if proc.returncode == 0:
                    data = proc.stdout.decode("utf-8", errors="replace")
            except Exception:
                data = None
        if data is None:
            try:
                data = widget.selection_get(selection="CLIPBOARD", type=_type)
            except tk.TclError:
                continue
        if not data:
            continue
        lines = [l.strip() for l in data.replace("\r\n", "\n").split("\n") if l.strip()]
        is_cut = False
        if (_type == "x-special/gnome-copied-files" and lines
                and lines[0] in ("copy", "cut")):
            is_cut = (lines[0] == "cut")
            lines = lines[1:]
        paths = []
        for l in lines:
            if l.startswith("file://"):
                p = urllib.parse.unquote(l[len("file://"):])
                if os.path.exists(p):
                    paths.append(p)
        if paths:
            return paths, is_cut
    return [], False


def open_in_filemanager(filepath):
    """Apre il file manager nella cartella del file, evidenziando il file se possibile."""
    if not filepath:
        return
    filepath = os.path.abspath(filepath)
    folder   = os.path.dirname(filepath) if os.path.isfile(filepath) else filepath

    # 1. dbus — più affidabile su GNOME/KDE/Cinnamon
    try:
        uri = "file://" + filepath
        subprocess.Popen([
            "dbus-send", "--session", "--dest=org.freedesktop.FileManager1",
            "--type=method_call", "/org/freedesktop/FileManager1",
            "org.freedesktop.FileManager1.ShowItems",
            f"array:string:{uri}", "string:"
        ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        return
    except FileNotFoundError:
        pass

    # 2. File manager specifici su varie distro
    for fm in ["nautilus", "nemo", "thunar", "dolphin", "pcmanfm",
               "caja", "spacefm", "xdg-open"]:
        if subprocess.run(["which", fm], capture_output=True).returncode == 0:
            try:
                # nautilus/nemo/dolphin accettano il file direttamente
                target = filepath if fm in ("nautilus","nemo","dolphin") else folder
                subprocess.Popen([fm, target],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return
            except Exception:
                continue

    # 2. File manager specifici con supporto --select
    for cmd in [
        ["nemo",    filepath],
        ["nautilus","--select", filepath],
        ["dolphin", "--select", filepath],
        ["caja",    "--select", filepath],
        ["thunar",  folder],
        ["pcmanfm", folder],
        ["xdg-open",folder],
    ]:
        try:
            subprocess.Popen(cmd, stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
            return
        except FileNotFoundError:
            continue


def _launch_video_player(filepath):
    """Avvia un player video esterno per filepath, provando in ordine una
    lista di player comuni — estratta da ImageSorter._play_video() (che
    ora la richiama) perche' serve anche al comando "Apri" di Naviga e
    Timeline sui video (richiesto da Carlo: prima navigavano al file
    nel visualizzatore principale, che per un video mostra solo un
    fotogramma statico, invece di lanciare davvero un player). Evita
    xdg-open come prima scelta: potrebbe riaprire Image Sorter stesso
    se e' il programma predefinito per quell'estensione. Ritorna True
    se un processo e' stato avviato con successo (non garantisce che il
    player si sia aperto senza errori, solo che il comando e' partito)."""
    players = ["mpv", "vlc", "totem", "celluloid", "dragon",
               "smplayer", "mplayer", "xplayer"]
    for player in players:
        try:
            subprocess.Popen([player, filepath],
                             stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)
            return True
        except FileNotFoundError:
            continue
        except Exception:
            continue
    # Fallback a xdg-open solo se nessun player dedicato e' stato trovato
    try:
        subprocess.Popen(["xdg-open", filepath],
                         stdout=subprocess.DEVNULL,
                         stderr=subprocess.DEVNULL)
        return True
    except Exception:
        return False


def _guess_ext_from_image(img):
    """Indovina l'estensione corretta dal formato Pillow dell'immagine."""
    fmt = (img.format or "").upper()
    return {
        "JPEG": ".jpg", "JPG": ".jpg",
        "PNG":  ".png", "GIF": ".gif",
        "BMP":  ".bmp", "TIFF": ".tiff",
        "WEBP": ".webp",
    }.get(fmt)


def _copy_score(file_info):
    """Punteggio per ordinare i file: 0=originale (prima), 1=probabile copia (dopo)."""
    import re as _re
    name = os.path.basename(file_info["path"]).lower()
    base = os.path.splitext(name)[0]
    # Pattern tipici delle copie
    patterns = [
        r'\bcop[yi]\b', r'\bcopia\b', r'\bcopy\b',
        r'\bduplicate\b', r'\bdoppione\b',
        r'\(\d+\)$',          # es. "foto (1)", "foto (2)"
        r'_\d+$',               # es. "foto_1", "foto_2"
        r'-copy$', r'-copia$',
        r' copy$', r' copia$',
    ]
    for p in patterns:
        if _re.search(p, base):
            return 1
    return 0


def browse_file_hud(parent, title="Scegli file", initial_dir=None,
                    filetypes=None, config=None):
    """Browser file HUD personalizzato con anteprima immagini."""
    if filetypes is None:
        filetypes = [("Immagini","*.png *.jpg *.jpeg *.gif *.bmp *.webp *.avif")]
    # Estensioni accettate
    exts = set()
    for _, pat in filetypes:
        for p in pat.split():
            exts.add(p.lstrip("*").lower())

    result = [None]
    cur_dir = [initial_dir or os.path.expanduser("~")]

    win = tk.Toplevel(parent)
    win.withdraw()
    win.title(title)
    win.configure(bg=BG_COLOR)
    win.resizable(True, True)
    win.transient(parent)
    win.geometry("700x480")
    win.minsize(500, 360)
    hud_apply(win)

    # Header con percorso corrente
    hdr = tk.Frame(win, bg=PANEL_COLOR)
    hdr.pack(fill="x")
    hdr.columnconfigure(0, weight=1)
    path_var = tk.StringVar(value=cur_dir[0])
    path_entry = tk.Entry(hdr, textvariable=path_var,
                          font=("TkFixedFont", 9), bg=ACCENT_COLOR,
                          fg=HUD_CYAN, insertbackground=HUD_CYAN,
                          relief="flat")
    path_entry.pack(side="left", fill="x", expand=True, padx=8, pady=6, ipady=3)

    # Corpo: lista file a sinistra + anteprima a destra
    body = tk.Frame(win, bg=BG_COLOR)
    body.pack(fill="both", expand=True, padx=4, pady=(0,4))
    body.columnconfigure(0, weight=2)
    body.columnconfigure(1, weight=1)
    body.rowconfigure(0, weight=1)

    # Lista file
    list_fr = tk.Frame(body, bg=PANEL_COLOR)
    list_fr.grid(row=0, column=0, sticky="nsew", padx=(0,4))
    list_fr.rowconfigure(0, weight=1)
    list_fr.columnconfigure(0, weight=1)
    lb = tk.Listbox(list_fr, bg=PANEL_COLOR, fg=TEXT_COLOR,
                    selectbackground=HIGHLIGHT, selectforeground="white",
                    font=("TkFixedFont", 9), relief="flat",
                    activestyle="none", borderwidth=0)
    sb = ttk.Scrollbar(list_fr, command=lb.yview)
    lb.config(yscrollcommand=sb.set)
    sb.grid(row=0, column=1, sticky="ns")
    lb.grid(row=0, column=0, sticky="nsew")

    # Anteprima a destra
    prev_fr = tk.Frame(body, bg=PANEL_COLOR, width=200)
    prev_fr.grid(row=0, column=1, sticky="nsew")
    prev_fr.pack_propagate(False)
    prev_canvas = tk.Canvas(prev_fr, bg=PANEL_COLOR, highlightthickness=0)
    prev_canvas.pack(fill="both", expand=True, padx=4, pady=4)
    prev_lbl = tk.Label(prev_fr, text="", font=("TkFixedFont",7),
                        bg=PANEL_COLOR, fg=MUTED_COLOR, wraplength=180)
    prev_lbl.pack(padx=4, pady=(0,4))
    _prev_img = [None]  # mantiene riferimento

    # Bottoni in fondo
    bot = tk.Frame(win, bg=PANEL_COLOR)
    bot.pack(fill="x")
    sel_lbl = tk.Label(bot, text="", font=("TkFixedFont",8),
                       bg=PANEL_COLOR, fg=MUTED_COLOR, anchor="w")
    sel_lbl.pack(side="left", padx=10, pady=6)
    def _confirm():
        sel = lb.curselection()
        if not sel: return
        item = lb.get(sel[0])
        if item.startswith("[..] "):
            _nav(os.path.dirname(cur_dir[0])); return
        if item.startswith("[/] ") or item.startswith("[ ] "):
            _nav(os.path.join(cur_dir[0], item[4:])); return
        full = os.path.join(cur_dir[0], item)
        if os.path.isdir(full):
            _nav(full); return
        result[0] = full
        win.destroy()
    tk.Button(bot, text="Seleziona", font=("TkFixedFont",9,"bold"),
              bg=SUCCESS, fg="white", relief="flat", padx=14,
              command=_confirm).pack(side="right", padx=8, pady=6, ipady=3)
    tk.Button(bot, text="Annulla", font=("TkFixedFont",9),
              bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=10,
              command=win.destroy).pack(side="right", padx=4, pady=6, ipady=3)

    def _nav(directory):
        if not os.path.isdir(directory): return
        cur_dir[0] = directory
        path_var.set(directory)
        lb.delete(0, tk.END)
        parent_dir = os.path.dirname(directory)
        if parent_dir != directory:
            lb.insert(tk.END, "[..] Su")
        try:
            entries = sorted(os.listdir(directory))
        except PermissionError:
            return
        # Prima le cartelle, poi i file compatibili
        dirs  = [e for e in entries if os.path.isdir(os.path.join(directory,e))
                 and not e.startswith(".")]
        files = [e for e in entries
                 if os.path.splitext(e)[1].lower() in exts
                 and not e.startswith(".")]
        for d in dirs:
            lb.insert(tk.END, f"[/] {d}")
        for f in files:
            lb.insert(tk.END, f)

    def _show_preview(name):
        full = os.path.join(cur_dir[0], name)
        if not os.path.isfile(full): return
        def _load():
            try:
                from PIL import Image, ImageTk
                img = Image.open(full)
                img.thumbnail((190, 190), Image.Resampling.LANCZOS)
                tk_img = ImageTk.PhotoImage(img)
                def _show():
                    if not win.winfo_exists() or not prev_canvas.winfo_exists():
                        return
                    try:
                        _prev_img[0] = tk_img
                        prev_canvas.delete("all")
                        cw = prev_canvas.winfo_width() or 190
                        ch = prev_canvas.winfo_height() or 190
                        prev_canvas.create_image(cw//2, ch//2,
                            anchor="center", image=tk_img)
                        prev_lbl.config(text=f"{img.width}x{img.height}  "
                                            f"{os.path.getsize(full)//1024} KB")
                    except tk.TclError:
                        pass
                win.after(0, _show)
            except Exception: pass
        import threading
        threading.Thread(target=_load, daemon=True).start()

    def _on_select(e):
        sel = lb.curselection()
        if not sel: return
        item = lb.get(sel[0])
        if not item.startswith("["):
            sel_lbl.config(text=item, fg=HUD_CYAN)
            _show_preview(item)
        else:
            sel_lbl.config(text="", fg=MUTED_COLOR)

    lb.bind("<<ListboxSelect>>", _on_select)
    lb.bind("<Double-Button-1>", lambda e: _confirm())
    lb.bind("<Return>",          lambda e: _confirm())
    path_entry.bind("<Return>",  lambda e: _nav(path_var.get()))
    win.bind("<Escape>",         lambda e: win.destroy())

    _nav(cur_dir[0])

    win.update_idletasks()
    pw=parent.winfo_width(); ph=parent.winfo_height()
    px=parent.winfo_rootx(); py=parent.winfo_rooty()
    ww=700; wh=480
    win.geometry(f"{ww}x{wh}+{px+(pw-ww)//2}+{py+(ph-wh)//2}")
    win.deiconify()
    win.grab_set()
    parent.wait_window(win)
    return result[0]


def browse_icon_hud(parent, title="Scegli immagine", initial_dir=None):
    """Browser per SCEGLIERE UN'ICONA (immagine di sfondo di un tasto,
    deck fisico o virtuale): stessa struttura di browse_file_hud
    (percorso in alto, anteprima GRANDE a destra, invariata), ma la
    lista a sinistra mostra nome E una piccola anteprima per ogni file
    — non solo il nome, richiesto da Carlo. tk.Listbox non puo' mostrare
    un'immagine per riga, quindi qui la lista e' un canvas scrollabile
    di righe (Frame), non un Listbox: unica vera differenza strutturale
    da browse_file_hud."""
    exts = {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".webp", ".avif"}
    result = [None]
    cur_dir = [initial_dir or os.path.expanduser("~")]
    THUMB = 30

    win = tk.Toplevel(parent)
    win.withdraw()
    win.title(title)
    win.configure(bg=BG_COLOR)
    win.resizable(True, True)
    win.transient(parent)
    win.geometry("700x480")
    win.minsize(500, 360)
    hud_apply(win)

    hdr = tk.Frame(win, bg=PANEL_COLOR)
    hdr.pack(fill="x")
    hdr.columnconfigure(0, weight=1)
    path_var = tk.StringVar(value=cur_dir[0])
    path_entry = tk.Entry(hdr, textvariable=path_var,
                          font=("TkFixedFont", 9), bg=ACCENT_COLOR,
                          fg=HUD_CYAN, insertbackground=HUD_CYAN,
                          relief="flat")
    path_entry.pack(side="left", fill="x", expand=True, padx=8, pady=6, ipady=3)

    body = tk.Frame(win, bg=BG_COLOR)
    body.pack(fill="both", expand=True, padx=4, pady=(0,4))
    body.columnconfigure(0, weight=2)
    body.columnconfigure(1, weight=1)
    body.rowconfigure(0, weight=1)

    # Lista a sinistra: canvas scrollabile di righe (miniatura + nome)
    list_fr = tk.Frame(body, bg=PANEL_COLOR)
    list_fr.grid(row=0, column=0, sticky="nsew", padx=(0,4))
    list_fr.rowconfigure(0, weight=1)
    list_fr.columnconfigure(0, weight=1)
    list_canvas = tk.Canvas(list_fr, bg=PANEL_COLOR, highlightthickness=0)
    list_sb = ttk.Scrollbar(list_fr, command=list_canvas.yview)
    list_canvas.configure(yscrollcommand=list_sb.set)
    list_sb.grid(row=0, column=1, sticky="ns")
    list_canvas.grid(row=0, column=0, sticky="nsew")
    list_inner = tk.Frame(list_canvas, bg=PANEL_COLOR)
    list_win_id = list_canvas.create_window((0, 0), window=list_inner, anchor="nw")
    list_inner.bind("<Configure>",
                    lambda e: list_canvas.configure(scrollregion=list_canvas.bbox("all")))
    list_canvas.bind("<Configure>",
                     lambda e: list_canvas.itemconfig(list_win_id, width=e.width))
    list_canvas.bind("<Button-4>", lambda e: list_canvas.yview_scroll(-3, "units"))
    list_canvas.bind("<Button-5>", lambda e: list_canvas.yview_scroll(3, "units"))
    list_canvas.bind("<MouseWheel>",
                     lambda e: list_canvas.yview_scroll(-1 if e.delta > 0 else 1, "units"))

    # Anteprima GRANDE a destra — identica a browse_file_hud, "che gia'
    # c'e'" per esplicita richiesta di Carlo: non toccata.
    prev_fr = tk.Frame(body, bg=PANEL_COLOR, width=200)
    prev_fr.grid(row=0, column=1, sticky="nsew")
    prev_fr.pack_propagate(False)
    prev_canvas = tk.Canvas(prev_fr, bg=PANEL_COLOR, highlightthickness=0)
    prev_canvas.pack(fill="both", expand=True, padx=4, pady=4)
    prev_lbl = tk.Label(prev_fr, text="", font=("TkFixedFont", 7),
                        bg=PANEL_COLOR, fg=MUTED_COLOR, wraplength=180)
    prev_lbl.pack(padx=4, pady=(0, 4))
    _prev_img = [None]   # mantiene riferimento (anteprima grande)

    bot = tk.Frame(win, bg=PANEL_COLOR)
    bot.pack(fill="x")
    sel_lbl = tk.Label(bot, text="", font=("TkFixedFont", 8),
                       bg=PANEL_COLOR, fg=MUTED_COLOR, anchor="w")
    sel_lbl.pack(side="left", padx=10, pady=6)

    # rows: lista ordinata di dict {"frame","holder","thumb_lbl","txt_lbl",
    # "kind","name"} — sostituisce curselection()/get() del Listbox
    # originale, che qui non esiste piu'.
    state = {"rows": [], "selected": -1}

    def _confirm():
        i = state["selected"]
        if i < 0 or i >= len(state["rows"]):
            return
        r = state["rows"][i]
        if r["kind"] == "up":
            _nav(os.path.dirname(cur_dir[0])); return
        if r["kind"] == "dir":
            _nav(os.path.join(cur_dir[0], r["name"])); return
        result[0] = os.path.join(cur_dir[0], r["name"])
        win.destroy()

    tk.Button(bot, text="Seleziona", font=("TkFixedFont", 9, "bold"),
              bg=SUCCESS, fg="white", relief="flat", padx=14,
              command=_confirm).pack(side="right", padx=8, pady=6, ipady=3)
    tk.Button(bot, text="Annulla", font=("TkFixedFont", 9),
              bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=10,
              command=win.destroy).pack(side="right", padx=4, pady=6, ipady=3)

    def _make_thumb(path):
        try:
            from PIL import Image, ImageTk
            img = Image.open(path).convert("RGB")
            img.thumbnail((THUMB, THUMB), Image.Resampling.LANCZOS)
            canvas_bg = Image.new("RGB", (THUMB, THUMB), (26, 32, 46))
            canvas_bg.paste(img, ((THUMB - img.width)//2, (THUMB - img.height)//2))
            return ImageTk.PhotoImage(canvas_bg)
        except Exception:
            return None

    def _show_preview(full):
        def _load():
            try:
                from PIL import Image, ImageTk
                img = Image.open(full)
                img.thumbnail((190, 190), Image.Resampling.LANCZOS)
                tk_img = ImageTk.PhotoImage(img)
                def _show():
                    if not win.winfo_exists() or not prev_canvas.winfo_exists():
                        return
                    try:
                        _prev_img[0] = tk_img
                        prev_canvas.delete("all")
                        cw = prev_canvas.winfo_width() or 190
                        ch = prev_canvas.winfo_height() or 190
                        prev_canvas.create_image(cw//2, ch//2,
                            anchor="center", image=tk_img)
                        prev_lbl.config(text=f"{img.width}x{img.height}  "
                                            f"{os.path.getsize(full)//1024} KB")
                    except tk.TclError:
                        pass
                win.after(0, _show)
            except Exception:
                pass
        threading.Thread(target=_load, daemon=True).start()

    def _select_index(i):
        if i < 0 or i >= len(state["rows"]):
            return
        state["selected"] = i
        for j, r in enumerate(state["rows"]):
            bg = HIGHLIGHT if j == i else PANEL_COLOR
            for w in (r["frame"], r["holder"], r["thumb_lbl"], r["txt_lbl"]):
                try: w.config(bg=bg)
                except Exception: pass
        r = state["rows"][i]
        if r["kind"] == "file":
            sel_lbl.config(text=r["name"], fg=HUD_CYAN)
            _show_preview(os.path.join(cur_dir[0], r["name"]))
        else:
            sel_lbl.config(text="", fg=MUTED_COLOR)
            prev_canvas.delete("all")
            prev_lbl.config(text="")

    def _add_row(kind, name, label_text):
        row = tk.Frame(list_inner, bg=PANEL_COLOR)
        row.pack(fill="x")
        holder = tk.Frame(row, bg=PANEL_COLOR, width=THUMB, height=THUMB)
        holder.pack_propagate(False)
        holder.pack(side="left", padx=(4, 6), pady=2)
        thumb_lbl = tk.Label(holder, bg=PANEL_COLOR)
        thumb_lbl.pack(fill="both", expand=True)
        txt_lbl = tk.Label(row, text=label_text, font=("TkFixedFont", 9),
                           bg=PANEL_COLOR, fg=TEXT_COLOR, anchor="w")
        txt_lbl.pack(side="left", fill="x", expand=True, pady=2)
        idx = len(state["rows"])
        state["rows"].append({"frame": row, "holder": holder,
                              "thumb_lbl": thumb_lbl, "txt_lbl": txt_lbl,
                              "kind": kind, "name": name})
        for w in (row, holder, thumb_lbl, txt_lbl):
            w.bind("<Button-1>", lambda e, i=idx: _select_index(i))
            w.bind("<Double-Button-1>", lambda e, i=idx: (_select_index(i), _confirm()))
            # Le righe coprono tutta l'area del canvas: senza questi
            # bind la rotella funziona solo sui pochi pixel di canvas
            # scoperti, non sopra le righe stesse.
            w.bind("<Button-4>", lambda e: list_canvas.yview_scroll(-3, "units"))
            w.bind("<Button-5>", lambda e: list_canvas.yview_scroll(3, "units"))
            w.bind("<MouseWheel>",
                   lambda e: list_canvas.yview_scroll(-1 if e.delta > 0 else 1, "units"))

    def _nav(directory):
        if not os.path.isdir(directory):
            return
        cur_dir[0] = directory
        path_var.set(directory)
        for w in list_inner.winfo_children():
            w.destroy()
        state["rows"] = []
        state["selected"] = -1
        sel_lbl.config(text="", fg=MUTED_COLOR)
        prev_canvas.delete("all")
        prev_lbl.config(text="")
        parent_dir = os.path.dirname(directory)
        if parent_dir != directory:
            _add_row("up", "..", "[..] Su")
        try:
            entries = sorted(os.listdir(directory))
        except PermissionError:
            return
        dirs  = [e for e in entries if os.path.isdir(os.path.join(directory, e))
                 and not e.startswith(".")]
        files = [e for e in entries
                 if os.path.splitext(e)[1].lower() in exts
                 and not e.startswith(".")]
        for d in dirs:
            _add_row("dir", d, f"[/] {d}")
        for f in files:
            _add_row("file", f, f)

        # Miniature caricate in un thread e applicate una alla volta —
        # stesso motivo dell'anteprima grande: niente attesa visibile se
        # la cartella ha molti file. Il controllo "cur_dir[0] != directory"
        # scarta i risultati se nel frattempo si e' navigato altrove.
        file_rows = [r for r in state["rows"] if r["kind"] == "file"]
        def _load_thumbs(rows=file_rows, target_dir=directory):
            for r in rows:
                if cur_dir[0] != target_dir:
                    return
                thumb = _make_thumb(os.path.join(target_dir, r["name"]))
                if thumb is None:
                    continue
                def _apply(r=r, thumb=thumb):
                    if cur_dir[0] != target_dir:
                        return
                    try:
                        r["thumb_lbl"].config(image=thumb)
                        r["thumb_lbl"].image = thumb
                    except Exception:
                        pass
                win.after(0, _apply)
        threading.Thread(target=_load_thumbs, daemon=True).start()

    def _move_selection(delta):
        if not state["rows"]:
            return
        new_i = max(0, min(len(state["rows"]) - 1,
                           (state["selected"] if state["selected"] >= 0 else 0) + delta))
        _select_index(new_i)

    path_entry.bind("<Return>", lambda e: _nav(path_var.get()))
    win.bind("<Escape>", lambda e: win.destroy())
    win.bind("<Return>", lambda e: _confirm())
    win.bind("<Down>", lambda e: _move_selection(1))
    win.bind("<Up>",   lambda e: _move_selection(-1))

    _nav(cur_dir[0])

    win.update_idletasks()
    pw = parent.winfo_width(); ph = parent.winfo_height()
    px = parent.winfo_rootx(); py = parent.winfo_rooty()
    ww = 700; wh = 480
    win.geometry(f"{ww}x{wh}+{px+(pw-ww)//2}+{py+(ph-wh)//2}")
    win.deiconify()
    win.grab_set()
    parent.wait_window(win)
    return result[0]


def _hud_yesno_simple(parent, title, msg, yes_label="Sì", no_label="No"):
    """Dialog di conferma HUD minimale (funzione globale, no ImageSorter)."""
    result = [False]
    dlg = tk.Toplevel(parent)
    dlg.withdraw()
    dlg.title(title)
    dlg.configure(bg=BG_COLOR)
    dlg.resizable(False, False)
    dlg.transient(parent)
    hud_apply(dlg)
    tk.Label(dlg, text=tk_safe(title), font=("TkFixedFont",10,"bold"),
             bg=BG_COLOR, fg=HUD_CYAN).pack(padx=24, pady=(16,4))
    tk.Label(dlg, text=tk_safe(msg), font=("TkFixedFont",9),
             bg=BG_COLOR, fg=TEXT_COLOR, justify="center").pack(padx=24, pady=(0,12))
    bf = tk.Frame(dlg, bg=BG_COLOR)
    bf.pack(pady=(0,16))
    def _yes():
        result[0] = True
        dlg.destroy()
    tk.Button(bf, text=tk_safe(yes_label), font=("TkFixedFont",9,"bold"),
              bg=WARNING, fg="white", relief="flat", padx=16,
              command=_yes).pack(side="left", padx=(0,8), ipady=3)
    tk.Button(bf, text=tk_safe(no_label), font=("TkFixedFont",9),
              bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=12,
              command=dlg.destroy).pack(side="left", ipady=3)
    dlg.update_idletasks()
    pw,ph = parent.winfo_width(), parent.winfo_height()
    px,py = parent.winfo_rootx(), parent.winfo_rooty()
    ww,wh = dlg.winfo_reqwidth()+48, dlg.winfo_reqheight()+16
    dlg.geometry(f"{ww}x{wh}+{px+(pw-ww)//2}+{py+(ph-wh)//2}")
    dlg.deiconify()
    dlg.grab_set()
    parent.wait_window(dlg)
    return result[0]


def _post_menu(menu, x, y, root_win=None):
    """
    Mostra un Menu tkinter e lo chiude al click fuori — compatibile X11/Linux.
    Usa tk_popup() (che acquisisce grab) ma rilascia subito con grab_release,
    poi registra un ButtonPress sulla root per distruggerlo al click fuori.
    """
    import time as _time
    _posted_at = [_time.monotonic()]
    _destroyed = [False]
    # _bid: lista per poter rimuovere il bind dopo
    _bid = [None]
    def _destroy():
        _destroyed[0] = True
        try:
            if _bid[0] and root_win and root_win.winfo_exists():
                root_win.unbind("<ButtonPress>", _bid[0])
        except Exception: pass
        try:
            if menu.winfo_exists(): menu.unpost()
        except Exception: pass
    def _close(e):
        # Il ButtonPress che ha APERTO il menu raggiunge la finestra subito
        # dopo l'apertura. Di solito cade sull'angolo in alto a sinistra
        # del menu, quindi risulta "dentro" e non chiude nulla — ma NON
        # quando il menu e' troppo alto per lo spazio sotto al puntatore:
        # in quel caso Tk lo sposta verso l'alto per farlo stare nello
        # schermo, il click resta dov'era e finisce FUORI dal menu, che si
        # richiude all'istante. E' quello che succedeva in Naviga con un
        # file selezionato, dove il menu e' piu' lungo.
        if _time.monotonic() - _posted_at[0] < 0.30:
            return
        try:
            wx, wy = menu.winfo_rootx(), menu.winfo_rooty()
            ww, wh = menu.winfo_width(), menu.winfo_height()
            if not (wx <= e.x_root <= wx+ww and wy <= e.y_root <= wy+wh):
                _destroy()
        except Exception:
            _destroy()
    # Posizionamento: il menu non deve MAI finire sotto il puntatore.
    # Se non ci sta nello spazio disponibile, Tk lo sposta da solo per
    # farlo rientrare nello schermo — e cosi' facendo lo porta SOTTO il
    # cursore. Il rilascio del tasto destro, che arriva subito dopo,
    # attiva allora la voce che si trova li' sotto: si apriva il menu e
    # partiva una funzione a caso.
    # Calcolando prima l'ingombro e ribaltando il menu verso l'alto o
    # verso sinistra, il puntatore resta sempre su un angolo, fuori dalle
    # voci — la stessa situazione in cui il menu ha sempre funzionato.
    try:
        menu.update_idletasks()
        _mw, _mh = menu.winfo_reqwidth(), menu.winfo_reqheight()
        _sw, _sh = menu.winfo_screenwidth(), menu.winfo_screenheight()
        _px = x if x + _mw <= _sw else max(0, x - _mw - 4)
        _py = y if y + _mh <= _sh else max(0, y - _mh - 4)
    except Exception:
        _px, _py = x, y
    # Il riposizionamento sopra non basta da solo: se il menu e' piu' alto
    # dello spazio disponibile, qualunque collocazione lo fa comunque
    # finire sotto il puntatore, e il rilascio del tasto destro — che
    # arriva subito dopo l'apertura — attiva la voce che si trova li'.
    # Si ignora quindi il rilascio nei primi istanti di vita del menu:
    # non puo' essere una scelta dell'utente, e' il rilascio dello stesso
    # click che ha aperto il menu. Il binding sul widget precede le
    # associazioni di classe di Tk, quindi "break" impedisce
    # l'attivazione della voce.
    def _swallow_release(e):
        if _time.monotonic() - _posted_at[0] < 0.35:
            return "break"
    try:
        menu.bind("<ButtonRelease>", _swallow_release, add="+")
    except Exception:
        pass
    menu.tk_popup(_px, _py)
    _posted_at[0] = _time.monotonic()

    # Sorveglianza della posizione del puntatore, come gia' fatto per il
    # menu della Timeline. Il solo binding sui click non basta: cliccando
    # su un'altra applicazione o sulla barra di sistema l'evento non
    # arriva mai a questa finestra, e il menu restava aperto.
    # Si attiva solo dopo aver visto il puntatore DENTRO l'applicazione,
    # cosi' su un window manager che non espone l'informazione non si
    # chiude nulla per errore.
    if root_win is not None:
        _seen = [False]
        def _poll():
            if _destroyed[0]:
                return
            try:
                if not menu.winfo_exists() or not menu.winfo_ismapped():
                    return
                if _time.monotonic() - _posted_at[0] > 0.35:
                    px, py = root_win.winfo_pointerxy()
                    if root_win.winfo_containing(px, py) is not None:
                        _seen[0] = True
                    elif _seen[0]:
                        _destroy()
                        return
            except Exception:
                pass
            try:
                root_win.after(200, _poll)
            except Exception:
                pass
        try:
            root_win.after(250, _poll)
        except Exception:
            pass
    try: menu.grab_release()
    except Exception: pass
    if root_win:
        _bid[0] = root_win.bind("<ButtonPress>", _close, add=True)
    menu.bind("<Escape>", lambda e: _destroy())


def add_rating_row_reserve(menu):
    """Da chiamare mentre si costruisce il menu, nel punto esatto in cui
    deve comparire la riga 'Valutazione' — aggiunge DUE voci vuote e
    disabilitate che riservano lo spazio verticale di due righe (stelle
    sopra, pallini colore sotto — divisi su due righe perche' tutti
    insieme su una riga sola a volte sbordavano fuori dalla finestra
    del menu, segnalato da Carlo), e ritorna l'indice della prima.
    Serve solo a dare a Tk uno spazio da misurare con yposition(): il
    contenuto vero (stelle e pallini) lo disegna attach_rating_overlay()
    sopra queste righe, non e' mai visibile."""
    _before = menu.index("end")
    _idx = 0 if _before is None else _before + 1
    menu.add_command(label="", state="disabled")
    menu.add_command(label="", state="disabled")
    return _idx


def attach_rating_overlay(menu, row_index, targets, on_change=None):
    """Sovrappone la riga 'Valutazione' (stelle cliccabili + X) esattamente
    sopra la riga vuota riservata da add_rating_row_reserve(), cosi' da
    apparire integrata nello stesso popup — stessa interazione della riga
    gia' presente nel menu dell'immagine principale (_show_image_menu),
    qui replicata anche per Naviga e Timeline che usano un vero tk.Menu
    nativo (che non puo' ospitare widget al proprio interno: da qui la
    sovrapposizione di una seconda finestra, invece di un widget vero e
    proprio dentro il menu).

    Condivisa (non duplicata) tra image_sorter.py e timeline.py.

    on_change: chiamata (senza argomenti) dopo ogni click su una stella
    o su "X", cosi' il chiamante puo' aggiornare la propria griglia
    miniature (dove il rating e' mostrato anche li') senza dover
    ricaricare l'intera cartella.

    Sincronizzazione con la chiusura del menu: un tk.Menu non espone un
    evento univoco "mi sono chiuso" valido per TUTTE le vie di chiusura,
    quindi se ne usano due in parallelo (ridondanti apposta — se uno non
    scattasse su un window manager diverso dal tuo, l'altro fa comunque
    da rete di sicurezza), entrambi verificati con un test reale:
      - <Unmap> sul menu: si attiva quando _post_menu() lo nasconde con
        unpost() (click fuori / Esc).
      - <ButtonRelease-1> sul menu con add="+": si attiva anche quando
        si seleziona una voce vera del menu (che Tk chiude da solo,
        SENZA generare <Unmap> in tempo utile).
    Il click su una stella dell'overlay non tocca invece il menu
    sottostante (sono due finestre distinte): non lo richiude, e puo'
    correggere il rating piu' volte restando aperto, come nel menu
    dell'immagine principale."""
    if not _METADATA_STORE_AVAILABLE or not targets:
        return None
    try:
        menu.update_idletasks()
        mx, my = menu.winfo_rootx(), menu.winfo_rooty()
        mw = menu.winfo_width()
        row_y = menu.yposition(row_index)
        try:
            # +2, non +1: add_rating_row_reserve() ora riserva DUE righe
            # (stelle sopra, pallini sotto), non una sola.
            next_y = menu.yposition(row_index + 2)
            row_h = max(36, next_y - row_y)
        except Exception:
            row_h = 44
    except Exception:
        return None

    ov = tk.Toplevel(menu)
    ov.withdraw()
    ov.wm_overrideredirect(True)
    ov.configure(bg=PANEL_COLOR)
    # NIENTE bordo (ne' hud_apply ne' altro): un bordo netto rendeva
    # ANCORA piu' visibile un eventuale disallineamento di un paio di
    # pixel con il vero tk.Menu sottostante ("doppia linea in alto"),
    # invece di nasconderlo — segnalato da Carlo. Senza bordo, con lo
    # stesso identico bg=PANEL_COLOR del menu, l'overlay si confonde
    # con lo sfondo del menu ovunque non ci sia contenuto: nessuna
    # cucitura da vedere, a prescindere dall'allineamento esatto.

    # Rating corrente: mostrato pieno solo se TUTTI i target hanno lo
    # stesso valore, coerente col criterio gia' usato altrove per
    # evidenziare il rating nella voce di menu.
    _first = metadata_store.get_meta(targets[0])["rating"]
    _same = all(metadata_store.get_meta(t)["rating"] == _first for t in targets[1:])
    _cur = [_first if _same else 0]
    _star_widgets = []

    def _repaint():
        for _idx, _w in enumerate(_star_widgets, start=1):
            _w.config(fg=HUD_CYAN if _cur[0] >= _idx else MUTED_COLOR)

    def _set_rating(v):
        metadata_store.bulk_set_rating(targets, v)
        _cur[0] = v
        _repaint()
        if on_change is not None:
            try:
                on_change()
            except Exception:
                pass

    row = tk.Frame(ov, bg=PANEL_COLOR)
    row.pack(fill="both", expand=True, padx=3, pady=3)
    # Due righe, non una sola: stelle+X sopra, pallini colore subito
    # sotto — prima erano tutti sulla stessa riga e a volte sbordavano
    # fuori dalla finestra del menu (segnalato da Carlo, sia in Naviga
    # che in Timeline: funzione condivisa, un solo posto da correggere).
    stars_row = tk.Frame(row, bg=PANEL_COLOR)
    stars_row.pack(side="top", fill="x")
    dots_row = tk.Frame(row, bg=PANEL_COLOR)
    # padx=(10,0): stesso margine sinistro della prima stella qui sotto
    # (padx=(10,3)) — senza, i pallini iniziavano piu' a sinistra delle
    # stelle, disallineati (segnalato da Carlo).
    dots_row.pack(side="top", fill="x", pady=(2, 0), padx=(10, 0))
    # Niente etichetta "Valutazione:" qui (a differenza del menu
    # dell'immagine principale, dove c'e' spazio): tolta su richiesta di
    # Carlo per risolvere lo spazio quando il menu e' piu' stretto della
    # fila di stelle — le stelle da sole restano leggibili, la posizione
    # (dopo "Ruota antiorario") gia' da' il contesto.
    for _i in range(1, 6):
        _fg = HUD_CYAN if _cur[0] >= _i else MUTED_COLOR
        _star = tk.Label(stars_row, text="*", font=("TkFixedFont", 15, "bold"),
                         bg=PANEL_COLOR, fg=_fg, cursor="hand2")
        _star.pack(side="left", padx=(10,3) if _i == 1 else 3)
        _star.bind("<Button-1>", lambda e, v=_i: _set_rating(v))
        _star_widgets.append(_star)
    _xlbl = tk.Label(stars_row, text="X", font=("TkFixedFont", 9),
                     bg=PANEL_COLOR, fg=MUTED_COLOR, cursor="hand2")
    _xlbl.pack(side="left", padx=(8,8))
    _xlbl.bind("<Button-1>", lambda e: _set_rating(0))

    # Colorlabel: riga propria, subito sotto quella di stelle+X (vedi
    # sopra). Multiple, non escludenti (segnalato da Carlo): _cur_colors
    # parte dall'intersezione dei colori comuni a TUTTI i target
    # (coerente col criterio "presente su tutti" gia' usato da
    # bulk_toggle_color per decidere se aggiungere o togliere in blocco).
    _colors_per_target = [set(metadata_store.get_meta(t)["colors"]) for t in targets]
    _cur_colors = [set.intersection(*_colors_per_target) if _colors_per_target else set()]
    def _set_color(cid):
        metadata_store.bulk_toggle_color(targets, cid)
        if cid in _cur_colors[0]:
            _cur_colors[0].discard(cid)
        else:
            _cur_colors[0].add(cid)
        repaint_colorlabel_dots(_color_dots, _cur_colors[0])
        if on_change is not None:
            try:
                on_change()
            except Exception:
                pass
    _color_dots = draw_colorlabel_dots(dots_row, _cur_colors[0], _set_color)

    # La larghezza dell'overlay deve essere ALMENO quella richiesta dal
    # contenuto (etichetta + 5 stelle + X): se si usasse solo la
    # larghezza del menu (mw) e il menu fosse piu' stretto del
    # contenuto, le stelle piu' a destra finirebbero fuori dall'area
    # visibile della finestra e — non solo invisibili, ma davvero NON
    # cliccabili (verificato con un test mirato: sotto una certa
    # larghezza i widget risultano proprio "non mappati").
    ov.update_idletasks()
    _req_w = ov.winfo_reqwidth()
    _req_h = ov.winfo_reqheight()
    # _inset: l'overlay resta sempre un po' PIU' PICCOLO dell'area
    # riservata, staccato dai bordi del menu su tutti i lati, invece di
    # toccarli esattamente — un margine di sfondo del menu tutto
    # intorno nasconde meglio un eventuale disallineamento di un paio
    # di pixel di quanto potesse fare un bordo (tolto qui sopra), e
    # anche senza disallineamenti si vede meno "incollato" al menu
    # (segnalato da Carlo). Il contenuto resta comunque garantito
    # cliccabile: l'inset si applica solo quando c'e' gia' abbastanza
    # spazio (max(...) non scende mai sotto quanto richiesto da
    # contenuto + il suo stesso padding interno qui sotto).
    _inset = 5
    _final_w = max(mw - 2 * _inset, _req_w)
    _final_h = max(row_h - 2 * _inset, _req_h)
    ov.geometry(f"{_final_w}x{_final_h}+{mx + _inset}+{my + row_y + _inset}")
    ov.deiconify()
    ov.lift()

    _closed = [False]
    def _close_overlay(event=None):
        if _closed[0]:
            return
        _closed[0] = True
        # Distruzione rimandata al prossimo giro di eventi (after_idle),
        # non immediata: distruggere questa finestra DENTRO la gestione
        # dello stesso evento di click che sta selezionando una voce vera
        # del menu interferiva con il completamento di quella selezione
        # da parte di Tk — verificato con un test mirato (il comando
        # sottostante smetteva di partire). Rimandando di un istante,
        # Tk finisce prima di gestire il click, poi si pulisce.
        try:
            ov.after_idle(lambda: ov.destroy() if ov.winfo_exists() else None)
        except Exception:
            try:
                ov.destroy()
            except Exception:
                pass
    try:
        menu.bind("<Unmap>", _close_overlay, add="+")
    except Exception:
        pass
    try:
        menu.bind("<ButtonRelease-1>", _close_overlay, add="+")
    except Exception:
        pass
    try:
        menu.bind("<Destroy>", _close_overlay, add="+")
    except Exception:
        pass

    return ov


if _DEEP_BROWSER_AVAILABLE and _METADATA_STORE_AVAILABLE:
    # Iniezione differita fino a qui (va fatta DOPO che
    # attach_rating_overlay e' definita — vedi il commento accanto a
    # "_db_mod.metadata_store = metadata_store" molto piu' sopra in
    # questo file). timeline.py importa questa funzione PER VALORE
    # ("from image_sorter import (..., attach_rating_overlay, ...)"),
    # eseguito durante il caricamento di _db_mod ancora PRIMA che
    # l'iniezione di metadata_store qui sopra avvenisse: quella riga di
    # import ha quindi preso la funzione dal duplicato ricorsivo di
    # image_sorter.py (stesso meccanismo del doppio import di
    # deck_core/timeline gia' documentato), con un __globals__ — quindi
    # un metadata_store — tutto suo, mai iniettato. L'overlay
    # valutazione del menu tasto destro di Timeline scriveva percio' su
    # un metadata_store SBAGLIATO: rating/colorlabel assegnati da li'
    # sembravano non salvarsi mai (segnalato da Carlo — "in naviga
    # funziona senza problemi" perche' li' non c'e' nessun duplicato di
    # mezzo). Confermato confrontando le identita' di oggetto con un
    # test reale, non assunto dal solo leggere il codice.
    _db_mod.attach_rating_overlay = attach_rating_overlay


def rating_row_sizes(cell_width):
    """Sceglie le dimensioni di stelle e pallini (font stelle, diametro
    pallini, spazio tra i due gruppi, spaziatura tra i pallini, altezza
    complessiva della riga) in base allo spazio orizzontale REALMENTE
    disponibile nella cella, cosi' che ingrandendo le miniature (M/L in
    Naviga, zoom in Timeline) stelle e pallini crescano di conseguenza
    invece di restare fissi al minimo che serve per stare nelle
    miniature piccole ("S") — erano microscopici anche con "L"
    selezionato, segnalato da Carlo.

    Soglie scelte e VERIFICATE misurando con Tk sia la larghezza che
    l'altezza reale richieste da ciascuna combinazione (non a occhio)
    contro le celle "S" (90px), "M" (130px) e "L" (200px) di Naviga.

    Ritorna (star_font, dot_size, group_gap, dot_pad, row_height)."""
    if cell_width < 110:
        return 6, 8, 2, 1, 14         # "S" — 92x14 richiesti su 96 disp.
    elif cell_width < 170:
        return 9, 11, 3, 2, 19        # "M" — 133x19 richiesti su 136 disp.
    else:
        return 14, 17, 5, 3, 28       # "L" — 190x28 richiesti su 206 disp.


def timeline_rating_row_sizes(tw):
    """Dimensioni stelle/pallini per la griglia della TIMELINE — funzione
    separata da rating_row_sizes(), non condivisa: la Timeline ha solo
    due zoom (1x/2x, self._tw()==160/320) con molto piu' spazio
    orizzontale a disposizione rispetto alle miniature piccole di
    Naviga, quindi le stesse soglie le lasciavano piu' piccole del
    necessario ("si vedono male e spazio c'e'", segnalato da Carlo).
    Riusare rating_row_sizes() con soglie piu' generose avrebbe
    ingrandito anche le miniature "M" di Naviga, che invece vanno
    lasciate come sono: da qui una funzione a parte.

    Soglie scelte e VERIFICATE misurando con Tk (non a occhio) contro
    le due larghezze reali della Timeline: 1x (160px, ~164 disponibili)
    e 2x (320px, ~324 disponibili).

    Ritorna (star_font, dot_size, group_gap, dot_pad, row_height)."""
    if tw < 200:
        return 11, 13, 4, 2, 23    # 1x — 149x23 richiesti su ~164 disp.
    else:
        return 18, 22, 6, 4, 34    # 2x — 241x34 richiesti su ~324 disp.


def draw_colorlabel_dots(parent, cur_colors, on_pick, size=14, pad=2):
    """Cinque pallini colorati cliccabili (le colorlabel stile Adobe di
    metadata_store.COLOR_LABELS): vuoti (solo contorno) di default,
    pieni per ciascun colore attualmente assegnato — un po' piu' grandi
    dei pallini GPS/formato gia' usati nelle celle (quelli sono pieni e
    servono solo da indicatore, non sono cliccabili; questi sono
    un'altra cosa, per questo in un'altra zona della cella).

    Le colorlabel NON sono escludenti: un file puo' avere piu' di un
    colore assegnato insieme (segnalato da Carlo — nella prima versione
    erano un valore singolo). cur_colors accetta qualunque collezione di
    id colore presenti (lista, set, ecc.), non un colore solo.

    on_pick(color_id) viene chiamato con l'id GREZZO del pallino
    cliccato — MAI gia' invertito qui dentro: la decisione se e' un
    click di toggle-off (si ricliccava un colore gia' presente) spetta
    al chiamante, che legge sempre lo stato fresco da metadata_store
    invece di fidarsi di un valore catturato al momento del disegno (che
    diventerebbe stantio dopo il primo cambiamento, senza dover
    ricostruire l'intera riga a ogni click) — stessa convenzione gia'
    usata per il rating nei vari _click_rating_star.

    pad: spaziatura orizzontale tra un pallino e l'altro — ridotta nelle
    celle piccole della griglia (dove ogni pixel conta per stare accanto
    alle stelle), normale altrove.

    Ritorna la lista dei Canvas creati, nello stesso ordine di
    metadata_store.COLOR_LABELS, da passare a repaint_colorlabel_dots()
    per ridipingerli dopo un cambiamento senza ricrearli."""
    if not _METADATA_STORE_AVAILABLE:
        return []
    cur_set = set(cur_colors) if cur_colors else set()
    r = size // 2 - 1
    dots = []
    for _cid, _name, _hex in metadata_store.COLOR_LABELS:
        cv = tk.Canvas(parent, width=size, height=size,
                       bg=PANEL_COLOR, highlightthickness=0, cursor="hand2")
        cv.pack(side="left", padx=pad)
        _paint_colorlabel_dot(cv, size, r, _hex, filled=(_cid in cur_set))
        cv.bind("<Button-1>", lambda e, c=_cid: on_pick(c))
        dots.append(cv)
    return dots


def _paint_colorlabel_dot(cv, size, r, hexcol, filled):
    cv.delete("all")
    cx = cy = size // 2
    if filled:
        cv.create_oval(cx-r, cy-r, cx+r, cy+r, fill=hexcol, outline=hexcol)
    else:
        cv.create_oval(cx-r, cy-r, cx+r, cy+r, fill=PANEL_COLOR,
                       outline=hexcol, width=2)


def repaint_colorlabel_dots(dots, cur_colors, size=14):
    """Ridipinge i Canvas creati da draw_colorlabel_dots() coi colori
    correnti (una collezione, non un colore singolo — vedi
    draw_colorlabel_dots), senza ricrearli (stesso principio di
    _refresh_rating_row per le stelle)."""
    cur_set = set(cur_colors) if cur_colors else set()
    r = size // 2 - 1
    for cv, (_cid, _name, _hex) in zip(dots, metadata_store.COLOR_LABELS):
        try:
            if cv.winfo_exists():
                _paint_colorlabel_dot(cv, size, r, _hex, filled=(_cid in cur_set))
        except Exception:
            pass


def save_file_hud(parent, title="Salva file", initial_dir=None,
                  initial_file="", filetypes=None, config=None):
    """Finestra di salvataggio file in stile HUD — alternativa a asksaveasfilename."""
    result = [None]
    cur_dir = [initial_dir or os.path.expanduser("~")]

    win = tk.Toplevel(parent)
    win.withdraw()
    win.title(title)
    win.configure(bg=BG_COLOR)
    win.resizable(True, True)
    win.transient(parent)
    win.geometry("640x440")
    win.minsize(460, 320)
    hud_apply(win)

    # Header: percorso corrente
    hdr = tk.Frame(win, bg=PANEL_COLOR)
    hdr.pack(fill="x")
    path_var = tk.StringVar(value=cur_dir[0])
    path_entry = tk.Entry(hdr, textvariable=path_var,
                          font=("TkFixedFont", 9), bg=ACCENT_COLOR,
                          fg=HUD_CYAN, insertbackground=HUD_CYAN, relief="flat")
    path_entry.pack(side="left", fill="x", expand=True, padx=8, pady=6, ipady=3)

    # Lista file/cartelle
    body = tk.Frame(win, bg=BG_COLOR)
    body.pack(fill="both", expand=True, padx=4, pady=(0,4))
    body.rowconfigure(0, weight=1)
    body.columnconfigure(0, weight=1)

    list_fr = tk.Frame(body, bg=PANEL_COLOR)
    list_fr.grid(row=0, column=0, sticky="nsew")
    list_fr.rowconfigure(0, weight=1)
    list_fr.columnconfigure(0, weight=1)
    lb = tk.Listbox(list_fr, bg=PANEL_COLOR, fg=TEXT_COLOR,
                    selectbackground="#1a3a5a", selectforeground=HUD_CYAN,
                    font=("TkFixedFont", 9), relief="flat",
                    activestyle="none", bd=0)
    vsb = tk.Scrollbar(list_fr, command=lb.yview, bg=PANEL_COLOR)
    lb.config(yscrollcommand=vsb.set)
    lb.grid(row=0, column=0, sticky="nsew")
    vsb.grid(row=0, column=1, sticky="ns")

    entries = []  # (name, is_dir, full_path)

    def _populate(d):
        lb.delete(0, tk.END)
        entries.clear()
        cur_dir[0] = d
        path_var.set(d)
        # Su
        if os.path.dirname(d) != d:
            entries.append(("..", True, os.path.dirname(d)))
            lb.insert(tk.END, "  [/]  ..")
        try:
            items = sorted(os.scandir(d), key=lambda e: (not e.is_dir(), e.name.lower()))
            for e in items:
                if e.name.startswith("."): continue
                if e.is_dir():
                    entries.append((e.name, True, e.path))
                    lb.insert(tk.END, tk_safe(f"  [/]  {e.name}"))
                    lb.itemconfig(tk.END, fg=HUD_CYAN)
                else:
                    entries.append((e.name, False, e.path))
                    lb.insert(tk.END, f"       {e.name}")
        except PermissionError:
            pass

    def _on_double(e):
        sel = lb.curselection()
        if not sel: return
        name, is_dir, path = entries[sel[0]]
        if is_dir:
            _populate(path)
        else:
            fname_var.set(name)

    lb.bind("<Double-Button-1>", _on_double)
    lb.bind("<Return>", _on_double)

    def _nav(d):
        if os.path.isdir(d): _populate(d)
    path_entry.bind("<Return>", lambda e: _nav(path_var.get()))

    # Campo nome file
    bot_fr = tk.Frame(win, bg=PANEL_COLOR)
    bot_fr.pack(fill="x", padx=4, pady=(0,4))
    tk.Label(bot_fr, text="Nome:", font=("TkFixedFont",8),
             bg=PANEL_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(8,4), pady=6)
    fname_var = tk.StringVar(value=initial_file)
    fname_entry = tk.Entry(bot_fr, textvariable=fname_var,
                           font=("TkFixedFont",9), bg=ACCENT_COLOR,
                           fg=TEXT_COLOR, insertbackground=HUD_CYAN,
                           relief="flat")
    fname_entry.pack(side="left", fill="x", expand=True, ipady=3, pady=6)

    def _confirm(*_):
        name = fname_var.get().strip()
        if not name: return
        # Aggiungi estensione se manca
        if filetypes and "." not in name:
            first_ext = filetypes[0][1].split()[0].lstrip("*")
            if first_ext: name += first_ext
        dest = os.path.join(cur_dir[0], name)
        # Conferma sovrascrittura se file già esistente
        if os.path.isfile(dest):
            if not _hud_yesno_simple(win,
                    "File esistente",
                    f"{name}\nesiste già. Sovrascrivere?",
                    yes_label="Sovrascrivi", no_label="Annulla"):
                return
        result[0] = dest
        win.destroy()

    fname_entry.bind("<Return>", _confirm)

    # Bottoni
    bf = tk.Frame(bot_fr, bg=PANEL_COLOR)
    bf.pack(side="right", padx=4)
    tk.Button(bf, text="Salva", font=("TkFixedFont",9,"bold"),
              bg=SUCCESS, fg="white", relief="flat", padx=12,
              command=_confirm).pack(side="left", padx=(0,4), ipady=2, pady=4)
    tk.Button(bf, text="Annulla", font=("TkFixedFont",8),
              bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=8,
              command=win.destroy).pack(side="left", ipady=2, pady=4)

    _populate(cur_dir[0])

    # Posiziona e mostra
    win.update_idletasks()
    pw = parent.winfo_width(); ph = parent.winfo_height()
    px = parent.winfo_rootx(); py = parent.winfo_rooty()
    ww, wh = 640, 440
    win.geometry(f"{ww}x{wh}+{px+(pw-ww)//2}+{py+(ph-wh)//2}")
    win.deiconify()
    win.grab_set()
    fname_entry.focus_set()  # focus sul campo nome
    parent.wait_window(win)
    return result[0]


def browse_folder_hud(parent, title="Scegli cartella",
                      initial_dir=None, config=None):
    """
    Browser cartelle in stile HUD — alternativa a filedialog.askdirectory.
    Mostra accesso rapido (home, Immagini, Video, Scrivania, dischi),
    un campo percorso digitabile e una lista cartelle navigabile.
    Ritorna il percorso scelto o None se annullato.
    """
    result = [None]
    initial = initial_dir or (
        (config.get("last_browse_dir") or os.path.expanduser("~"))
        if config else os.path.expanduser("~"))
    if not os.path.isdir(initial):
        initial = os.path.expanduser("~")

    win = tk.Toplevel(parent)
    win.withdraw()
    win.title(title)
    win.configure(bg=BG_COLOR)
    win.geometry("560x420")
    win.minsize(400, 300)
    win.resizable(True, True)
    win.transient(parent)
    hud_apply(win)

    win.columnconfigure(0, weight=1)
    win.rowconfigure(1, weight=0)
    win.rowconfigure(2, weight=1)
    win.rowconfigure(3, weight=0)

    # ── Accesso rapido ────────────────────────────────────────────────────────
    quick = tk.Frame(win, bg=BG_COLOR)
    quick.grid(row=0, column=0, sticky="ew", padx=6, pady=(6,2))

    def _add_q(lbl, path, color=None):
        if not os.path.isdir(path):
            return
        tk.Button(quick, text=lbl,
                  font=("TkFixedFont", 8),
                  bg=color or ACCENT_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=6,
                  activebackground=HIGHLIGHT,
                  command=lambda p=path: _navigate(p)
                  ).pack(side="left", padx=2, ipady=2)

    pics = os.path.expanduser("~/Immagini")
    if not os.path.isdir(pics): pics = os.path.expanduser("~/Pictures")
    vids = os.path.expanduser("~/Video")
    if not os.path.isdir(vids): vids = os.path.expanduser("~/Videos")
    desk = os.path.expanduser("~/Scrivania")
    if not os.path.isdir(desk): desk = os.path.expanduser("~/Desktop")

    _add_q("~",        os.path.expanduser("~"))
    _add_q("Immagini", pics)
    _add_q("Video",    vids)
    _add_q("Scrivania",desk)
    _add_q("/",        "/")

    try:
        with open("/proc/mounts") as mf:
            for ln in mf:
                parts = ln.split()
                if len(parts) >= 2:
                    mp = parts[1]
                    if mp.startswith("/media/") or mp.startswith("/mnt/"):
                        if os.path.isdir(mp):
                            _add_q(f"[{os.path.basename(mp) or mp}]",
                                   mp, color="#1a3a5a")
    except Exception:
        pass

    # ── Barra percorso ────────────────────────────────────────────────────────
    nav = tk.Frame(win, bg=PANEL_COLOR)
    nav.grid(row=1, column=0, sticky="ew")
    nav.columnconfigure(1, weight=1)

    tk.Label(nav, text="Cartella:", font=("TkFixedFont", 8),
             bg=PANEL_COLOR, fg=MUTED_COLOR
             ).grid(row=0, column=0, padx=(8,4), pady=6)
    path_var = tk.StringVar(value=initial)
    path_entry = tk.Entry(nav, textvariable=path_var,
                          font=("TkFixedFont", 9),
                          bg=ACCENT_COLOR, fg=HUD_CYAN,
                          insertbackground=HUD_CYAN,
                          relief="flat", bd=3)
    path_entry.grid(row=0, column=1, sticky="ew", padx=4, ipady=3)
    path_entry.bind("<Return>", lambda e: _navigate(path_var.get()))

    tk.Button(nav, text="->", font=("TkFixedFont", 8),
              bg=SUCCESS, fg="white", relief="flat",
              command=lambda: _navigate(path_var.get())
              ).grid(row=0, column=2, padx=(0,6), pady=6)

    # ── Lista cartelle ────────────────────────────────────────────────────────
    list_fr = tk.Frame(win, bg=BG_COLOR)
    list_fr.grid(row=2, column=0, sticky="nsew", padx=6, pady=2)
    list_fr.rowconfigure(0, weight=1)
    list_fr.columnconfigure(0, weight=1)

    lb = tk.Listbox(list_fr,
                    font=("TkFixedFont", 10),
                    bg=BG_COLOR, fg=TEXT_COLOR,
                    selectbackground=HIGHLIGHT,
                    selectforeground="white",
                    activestyle="none",
                    relief="flat", bd=0)
    vsb = tk.Scrollbar(list_fr, orient="vertical", command=lb.yview)
    lb.configure(yscrollcommand=vsb.set)
    lb.grid(row=0, column=0, sticky="nsew")
    vsb.grid(row=0, column=1, sticky="ns")
    lb.bind("<Button-4>", lambda e: lb.yview_scroll(-1, "units"))
    lb.bind("<Button-5>", lambda e: lb.yview_scroll(1, "units"))
    lb.bind("<MouseWheel>", lambda e: lb.yview_scroll(-1 if e.delta > 0 else 1, "units"))

    _current = [initial]

    def _navigate(path):
        path = os.path.expanduser(path.strip())
        if not os.path.isdir(path):
            return
        _current[0] = path
        path_var.set(path)
        lb.delete(0, tk.END)
        try:
            entries = sorted(
                [e for e in os.listdir(path)
                 if os.path.isdir(os.path.join(path, e)) and not e.startswith(".")],
                key=str.lower)
            for e in entries:
                lb.insert(tk.END, f"  {e}")
            # Aggiungi ".." se non siamo alla root
            if path != "/":
                lb.insert(0, "  ..")
        except PermissionError:
            lb.insert(tk.END, "  (accesso negato)")

    def _on_dbl(event):
        sel = lb.curselection()
        if not sel:
            return
        name = lb.get(sel[0]).strip()
        if name == "..":
            _navigate(os.path.dirname(_current[0]))
        else:
            _navigate(os.path.join(_current[0], name))

    lb.bind("<Double-Button-1>", _on_dbl)
    lb.bind("<Return>", _on_dbl)
    lb.bind("<KP_Enter>", _on_dbl)

    # ── Bottoni ───────────────────────────────────────────────────────────────
    bot = tk.Frame(win, bg=PANEL_COLOR)
    bot.grid(row=3, column=0, sticky="ew")

    cur_lbl = tk.Label(bot, text="",
                       font=("TkFixedFont", 8),
                       bg=PANEL_COLOR, fg=MUTED_COLOR)
    cur_lbl.pack(side="left", padx=10, pady=6)

    def _update_cur_lbl(*_):
        p = _current[0]
        short = p if len(p) <= 40 else "..." + p[-37:]
        cur_lbl.config(text=short)
    path_var.trace_add("write", _update_cur_lbl)

    def _confirm():
        sel = lb.curselection()
        if sel:
            name = lb.get(sel[0]).strip()
            if name != "..":
                chosen = os.path.join(_current[0], name)
                if os.path.isdir(chosen):
                    _current[0] = chosen
        result[0] = _current[0]
        if config is not None:
            config["last_browse_dir"] = result[0]
        win.destroy()

    tk.Button(bot, text="Scegli questa cartella",
              font=("TkFixedFont", 9, "bold"),
              bg=SUCCESS, fg="white", relief="flat", padx=12,
              command=_confirm).pack(side="right", padx=6, pady=6, ipady=4)
    tk.Button(bot, text="Annulla",
              font=("TkFixedFont", 9),
              bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=8,
              command=win.destroy).pack(side="right", padx=(0,2), pady=6, ipady=4)

    win.bind("<Escape>", lambda e: win.destroy())

    _navigate(initial)

    win.update_idletasks()
    pw, ph = win.winfo_reqwidth(), win.winfo_reqheight()
    px = parent.winfo_rootx() + (parent.winfo_width()  - pw) // 2
    py = parent.winfo_rooty() + (parent.winfo_height() - ph) // 2
    win.geometry(f"+{max(0,px)}+{max(0,py)}")
    win.deiconify()
    win.grab_set()
    win.wait_window()

    return result[0]


class DuplicateFinder:
    """
    Finestra ricerca doppioni — 3 modalità:
      Tab 1 — Contenuto  : SHA256 su una o più cartelle
      Tab 2 — Rapida     : nome + dimensione, nessuna lettura file
      Tab 3 — A vs B     : confronta due cartelle, mostra file in comune
    """

    def __init__(self, parent, sorter, initial_dir=None):
        self.sorter   = sorter
        self._stop    = False
        self._thread  = None

        win = tk.Toplevel(parent)
        win.title(f"{T('dup_title', self.sorter.config.get('language','it'))}  v{VERSION}")
        win.configure(bg=BG_COLOR)
        win.geometry("1200x750")
        win.minsize(700, 450)
        hud_apply(win)
        self.win = win
        win.bind("<Escape>", lambda e: self._on_close())
        win.protocol("WM_DELETE_WINDOW", self._on_close)

        self._initial_dir = initial_dir or os.path.expanduser("~")
        self._build()
        # Traduzione interfaccia
        _lang = sorter.config.get("language", "it")
        if _lang != "it":
            self.win.after(80, lambda: _translate_widgets(self.win, _lang))

    # ── Layout principale ─────────────────────────────────────────────────────

    def _build(self):
        w = self.win
        w.columnconfigure(0, weight=1)
        w.rowconfigure(1, weight=1)
        w.rowconfigure(2, weight=0)

        # Tab bar
        tab_bar = tk.Frame(w, bg=PANEL_COLOR)
        tab_bar.grid(row=0, column=0, sticky="ew")
        self._tab_btns = {}
        self._current_tab = "sha"
        tabs = [("sha",   "  Contenuto (SHA256)  "),
                ("quick", "  Rapida (nome+dim)   "),
                ("ab",    "  Confronta A vs B    ")]
        for key, label in tabs:
            b = tk.Button(tab_bar, text=label,
                          font=("TkFixedFont", 9),
                          relief="flat", bd=0, padx=4, pady=4,
                          activebackground=BG_COLOR, activeforeground=HIGHLIGHT,
                          command=lambda k=key: self._switch_tab(k))
            b.pack(side="left")
            self._tab_btns[key] = b

        # Area contenuto tab
        self._content = tk.Frame(w, bg=BG_COLOR)
        self._content.grid(row=1, column=0, sticky="nsew")
        self._content.columnconfigure(0, weight=1)
        self._content.rowconfigure(0, weight=0)

        self._switch_tab("sha")

    def _switch_tab(self, key):
        self._stop = True   # ferma eventuale scan in corso
        self._current_tab = key
        for k, b in self._tab_btns.items():
            b.config(bg=BG_COLOR if k == key else PANEL_COLOR,
                     fg=HIGHLIGHT if k == key else MUTED_COLOR,
                     font=("TkFixedFont", 9, "bold") if k == key
                          else ("TkFixedFont", 9))
        for child in self._content.winfo_children():
            child.destroy()
        # Reset rowconfigure per evitare che row=0 si espanda
        self._content.rowconfigure(0, weight=0)
        self._content.rowconfigure(1, weight=1)
        if key == "sha":
            self._build_sha_tab()
        elif key == "quick":
            self._build_quick_tab()
        else:
            self._build_ab_tab()
        # Traduzione dopo ogni ricostruzione tab
        _lang = self.sorter.config.get("language","it")
        if _lang != "it":
            self.win.after(50, lambda: _translate_widgets(self.win, _lang))

    # ── Componenti riutilizzabili ─────────────────────────────────────────────

    def _make_folder_list(self, parent, multi=True):
        """
        Pannello lista cartelle con bottoni Aggiungi/Rimuovi.
        Ritorna (frame, getter) dove getter() → lista di (path, recursive).
        """
        fr = tk.Frame(parent, bg=BG_COLOR)

        # Lista
        lst_fr = tk.Frame(fr, bg=ACCENT_COLOR)
        lst_fr.pack(fill="x", padx=0, pady=(0,2))
        lst_fr.columnconfigure(0, weight=1)

        entries = []   # lista di (path_var, rec_var, row_frame)

        def _add(path=""):
            row = tk.Frame(lst_fr, bg=ACCENT_COLOR)
            row.pack(fill="x", padx=4, pady=2)
            row.columnconfigure(1, weight=1)

            rec_var  = tk.BooleanVar(value=True)
            path_var = tk.StringVar(value=path)

            tk.Checkbutton(row, text="Sub",
                           variable=rec_var,
                           font=("TkFixedFont", 7),
                           bg=ACCENT_COLOR, fg=MUTED_COLOR,
                           selectcolor=BG_COLOR,
                           activebackground=ACCENT_COLOR
                           ).grid(row=0, column=0, padx=(4,2))

            tk.Entry(row, textvariable=path_var,
                     font=("TkFixedFont", 8),
                     bg=BG_COLOR, fg=HUD_CYAN,
                     insertbackground=HUD_CYAN,
                     relief="flat", bd=2
                     ).grid(row=0, column=1, sticky="ew", padx=2, ipady=2)

            def _browse_this():
                d = browse_folder_hud(self.win,
                    title="Scegli cartella destinazione",
                    initial_dir=path_var.get() or self._initial_dir)
                if d:
                    path_var.set(d)
            tk.Button(row, text="...",
                      font=("TkFixedFont", 7), bg=PANEL_COLOR, fg=TEXT_COLOR,
                      relief="flat", padx=4,
                      command=_browse_this
                      ).grid(row=0, column=2, padx=2, ipady=2)

            def _remove():
                entries.remove((path_var, rec_var, row))
                row.destroy()
            tk.Button(row, text="x",
                      font=("TkFixedFont", 7), bg=PANEL_COLOR, fg="#c0392b",
                      relief="flat", padx=4,
                      command=_remove
                      ).grid(row=0, column=3, padx=(0,4), ipady=2)

            entries.append((path_var, rec_var, row))

        _add(self._initial_dir)

        # Barra aggiungi (solo se multi)
        if multi:
            add_btn = tk.Button(fr, text="+ Aggiungi cartella",
                                font=("TkFixedFont", 8),
                                bg=PANEL_COLOR, fg=HUD_CYAN,
                                relief="flat", padx=8,
                                command=lambda: _add())
            add_btn.pack(anchor="w", pady=(2,0))

        def _get():
            result = []
            for pv, rv, _ in entries:
                p = pv.get().strip()
                if p and os.path.isdir(p):
                    result.append((p, rv.get()))
            return result

        return fr, _get

    def _make_results_area(self, parent, row_paths=None):
        """Lista risultati + barra stato + bottoni azione."""
        fr = tk.Frame(parent, bg=BG_COLOR)
        fr.columnconfigure(0, weight=1)
        fr.rowconfigure(0, weight=1)
        if row_paths is None:
            row_paths = {}

        # Progresso
        prog_fr = tk.Frame(fr, bg=BG_COLOR)
        prog_fr.grid(row=1, column=0, sticky="ew", padx=8, pady=(0,2))
        prog_fr.columnconfigure(0, weight=1)

        status_lbl = tk.Label(prog_fr, text="",
                              font=("TkFixedFont", 8),
                              bg=BG_COLOR, fg=MUTED_COLOR, anchor="w")
        status_lbl.grid(row=0, column=0, sticky="ew")

        prog_canvas = tk.Canvas(prog_fr, bg=ACCENT_COLOR,
                                height=3, highlightthickness=0)
        prog_canvas.grid(row=1, column=0, sticky="ew")
        prog_bar = prog_canvas.create_rectangle(0, 0, 0, 3,
                                                fill=HUD_CYAN, width=0)

        # Splitter: listbox a sinistra + anteprima a destra
        paned = tk.PanedWindow(fr, orient="horizontal",
                               bg=BG_COLOR, sashwidth=4,
                               sashrelief="flat")
        paned.grid(row=0, column=0, sticky="nsew")

        list_fr = tk.Frame(paned, bg=BG_COLOR)
        list_fr.rowconfigure(0, weight=1)
        list_fr.columnconfigure(0, weight=1)
        paned.add(list_fr, stretch="always")

        # Pannello anteprima destra — griglia verticale gruppo duplicati
        prev_fr = tk.Frame(paned, bg=PANEL_COLOR, width=300)
        prev_fr.pack_propagate(False)
        paned.add(prev_fr, stretch="never", minsize=150)
        # Canvas scrollabile per le anteprime
        prev_canvas = tk.Canvas(prev_fr, bg=PANEL_COLOR,
                                highlightthickness=0)
        prev_vsb = tk.Scrollbar(prev_fr, orient="vertical",
                                command=prev_canvas.yview)
        prev_canvas.configure(yscrollcommand=prev_vsb.set)
        prev_vsb.pack(side="right", fill="y")
        prev_canvas.pack(fill="both", expand=True)
        # Frame interno scrollabile
        prev_inner = tk.Frame(prev_canvas, bg=PANEL_COLOR)
        prev_inner_id = prev_canvas.create_window(
            0, 0, anchor="nw", window=prev_inner)
        def _prev_configure(e):
            prev_canvas.configure(scrollregion=prev_canvas.bbox("all"))
            prev_canvas.itemconfig(prev_inner_id,
                                   width=prev_canvas.winfo_width())
        prev_inner.bind("<Configure>", _prev_configure)
        prev_canvas.bind("<Configure>", lambda e: prev_canvas.itemconfig(
            prev_inner_id, width=e.width))
        prev_canvas.bind("<Button-4>", lambda e: prev_canvas.yview_scroll(-1,"units"))
        prev_canvas.bind("<Button-5>", lambda e: prev_canvas.yview_scroll(1,"units"))
        # Riferimenti per le celle anteprima
        _prev_cells = []   # lista di (frame, canvas, lbl, path)
        _prev_imgs  = []   # PhotoImage refs

        lb = tk.Listbox(list_fr, font=("TkFixedFont", 9),
                        bg=BG_COLOR, fg=TEXT_COLOR,
                        selectbackground=HIGHLIGHT,
                        selectforeground="white",
                        activestyle="none",
                        relief="flat", bd=0,
                        selectmode=tk.EXTENDED)
        vsb = tk.Scrollbar(list_fr, orient="vertical", command=lb.yview)
        lb.configure(yscrollcommand=vsb.set)
        lb.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        lb.bind("<Button-4>", lambda e: (lb.yview_scroll(-1, "units"), "break")[1])
        lb.bind("<Button-5>", lambda e: (lb.yview_scroll( 1, "units"), "break")[1])
        lb.bind("<MouseWheel>", lambda e: (lb.yview_scroll(-1 if e.delta > 0 else 1, "units"), "break")[1])

        def _find_group(idx):
            """Trova tutti i file del gruppo a cui appartiene la riga idx."""
            # Cerca la riga header (path=None, testo inizia con "---")
            # andando verso l'alto
            start = idx
            while start > 0 and row_paths.get(start) is not None:
                start -= 1
            # Raccoglie file dal header fino alla prossima riga vuota
            files = []
            i = start + 1
            while i in row_paths:
                p = row_paths.get(i)
                if p is None: break
                if p: files.append((i, p))
                i += 1
            return files

        def _update_preview(e=None):
            sel = lb.curselection()
            # Svuota pannello
            for w in prev_inner.winfo_children(): w.destroy()
            _prev_cells.clear()
            _prev_imgs.clear()
            if not sel: return
            idx = sel[0]
            sel_path = row_paths.get(idx)  # path selezionato (può essere None)
            group = _find_group(idx)
            if not group: return

            prev_canvas.update_idletasks()
            pw = prev_canvas.winfo_width() or 290
            thumb_size = max(pw - 16, 100)

            for row_idx, path in group:
                is_sel = (path == sel_path)
                # Cella per ogni file
                border_color = HUD_CYAN if is_sel else PANEL_COLOR
                cell = tk.Frame(prev_inner, bg=border_color,
                                padx=2 if is_sel else 0,
                                pady=2 if is_sel else 0)
                cell.pack(fill="x", padx=4, pady=(4,0))
                inner = tk.Frame(cell, bg=PANEL_COLOR)
                inner.pack(fill="x")
                # Canvas anteprima
                cv = tk.Canvas(inner, bg=PANEL_COLOR,
                               height=thumb_size, highlightthickness=0)
                cv.pack(fill="x")
                # Label info
                name = os.path.basename(path)
                short = name if len(name)<=32 else name[:30]+".."
                try: info = f"{os.path.getsize(path)//1024} KB"
                except Exception: info = ""
                ext = os.path.splitext(path)[1].upper().lstrip(".")
                lbl = tk.Label(inner,
                    text=tk_safe(f"{short}\n{info}  {ext}"),
                    font=("TkFixedFont",7), bg=PANEL_COLOR,
                    fg=HUD_CYAN if is_sel else MUTED_COLOR,
                    wraplength=thumb_size, justify="center")
                lbl.pack(pady=(0,2))
                # Menu tasto destro su ogni cella
                for w in (cv, lbl, inner):
                    w.bind("<Button-3>", lambda e, p=path: self._ctx_path(e, p))
                    w.bind("<Double-Button-1>", lambda e, p=path:
                        subprocess.Popen(["xdg-open", p],
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))
                _prev_cells.append((cell, cv, lbl, path))
                # Carica thumbnail in background
                import threading as _thr
                def _load(p=path, c=cv, ts=thumb_size):
                    try:
                        img = load_thumbnail(p, ts)
                        if not img: return
                        img = img.copy()
                        def _show(im=img, cv=c):
                            if not cv.winfo_exists(): return
                            from PIL import ImageTk as _ITk
                            ph = _ITk.PhotoImage(im)
                            _prev_imgs.append(ph)
                            cw = cv.winfo_width() or ts
                            ch = cv.winfo_height() or ts
                            cv.create_image(cw//2, ch//2,
                                anchor="center", image=ph)
                        self.win.after(0, _show)
                    except Exception: pass
                _thr.Thread(target=_load, daemon=True).start()

            prev_inner.update_idletasks()
            prev_canvas.configure(
                scrollregion=prev_canvas.bbox("all"))
            prev_canvas.yview_moveto(0)

        lb.bind("<<ListboxSelect>>", _update_preview, add=True)
        lb._refresh_preview = _update_preview  # accessibile da _trash_row
        lb._row_paths_ref  = row_paths          # per aggiornare riga da anteprima

        # Menu tasto destro sull'anteprima — stesse azioni della listbox
        # (menu tasto destro gestito per-cella in _update_preview)

        # Barra azioni in fondo
        bot = tk.Frame(fr, bg=PANEL_COLOR)
        bot.grid(row=2, column=0, sticky="ew")

        result_lbl = tk.Label(bot, text="",
                              font=("TkFixedFont", 9),
                              bg=PANEL_COLOR, fg=MUTED_COLOR)
        result_lbl.pack(side="left", padx=10, pady=5)

        # Chiudi per primo → appare più a destra
        tk.Button(bot, text="Chiudi",
                  font=("TkFixedFont", 8), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=8,
                  command=self._on_close
                  ).pack(side="right", padx=(0,6), pady=5, ipady=3)

        stop_btn = tk.Button(bot, text="Stop",
                             font=("TkFixedFont", 8, "bold"),
                             bg=HIGHLIGHT, fg="white",
                             relief="flat", padx=8,
                             state="disabled",
                             command=lambda: setattr(self, '_stop', True))
        stop_btn.pack(side="right", padx=6, pady=5, ipady=3)

        clean_btn = tk.Button(bot,
                              text="Cestina tutti i duplicati (mantieni 1)",
                              font=("TkFixedFont", 8, "bold"),
                              bg="#c0392b", fg="white",
                              relief="flat", padx=10,
                              state="disabled")
        clean_btn.pack(side="right", padx=6, pady=5, ipady=3)

        # Bottone "Cestina selezionati" — visibile solo con selezione attiva
        sel_btn = tk.Button(bot, text="Cestina selezionati (0)",
                            font=("TkFixedFont", 8, "bold"),
                            bg="#8e44ad", fg="white",
                            relief="flat", padx=10,
                            state="disabled")
        sel_btn.pack(side="right", padx=6, pady=5, ipady=3)

        # Aggiorna il bottone quando cambia la selezione
        def _on_select(e=None):
            sel = lb.curselection()
            # Considera solo le righe che corrispondono a file reali
            files = [row_paths.get(i) for i in sel if row_paths.get(i)]
            n = len(files)
            if n > 0:
                sel_btn.config(state="normal",
                               text=_Tf("Cestina selezionati ({n})", self.sorter.config.get("language","it"), n=n))
            else:
                sel_btn.config(state="disabled",
                               text="Cestina selezionati (0)")

        lb.bind("<<ListboxSelect>>", _on_select, add=True)

        def _trash_selected():
            sel = lb.curselection()
            files = [(i, row_paths.get(i)) for i in sel if row_paths.get(i)]
            if not files:
                return
            n = len(files)
            if not self.sorter._hud_yesno(
                    "Cestina",
                    f"Spostare nel cestino {n} file selezionati?",
                    yes_label="Cestina", no_label="Annulla",
                    parent=self.win):
                return
            trashed = 0
            for idx, fpath in files:
                if os.path.isfile(fpath):
                    dest = move_to_transit(fpath, self.sorter.config)
                    if dest:
                        append_history({"action": "trashed_transit",
                                        "files": [fpath], "dest": dest,
                                        "note": "doppioni: selezionati"})
                        lb.delete(idx)
                        lb.insert(idx, tk_safe(f"  [CESTINATO]  {fpath}"))
                        lb.itemconfig(idx, fg=MUTED_COLOR)
                        row_paths[idx] = None
                        trashed += 1
            result_lbl.config(text=_Tf("Cestinati {n} file.", self.sorter.config.get("language","it"), n=trashed))
            sel_btn.config(state="disabled", text="Cestina selezionati (0)")

        sel_btn.config(command=_trash_selected)

        return fr, lb, status_lbl, prog_canvas, prog_bar, result_lbl, clean_btn, stop_btn, bot

    # ── TAB 1: SHA256 ─────────────────────────────────────────────────────────

    def _build_sha_tab(self):
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)

        # Pannello cartelle
        top = tk.Frame(f, bg=BG_COLOR)
        top.grid(row=0, column=0, sticky="ew", padx=8, pady=(4,0))
        top.columnconfigure(0, weight=1)

        tk.Label(top, text="Cartelle da analizzare (confronto esatto SHA256):",
                 font=("TkFixedFont", 8), bg=BG_COLOR,
                 fg=MUTED_COLOR).grid(row=0, column=0, sticky="w", pady=(0,3))

        folder_fr, get_folders = self._make_folder_list(top, multi=True)
        folder_fr.grid(row=1, column=0, sticky="ew", pady=(2,4))

        # Area risultati — creata prima così stop_btn è disponibile
        row_paths = {}
        res_fr, lb, status_lbl, prog_canvas, prog_bar, result_lbl, clean_btn, stop_btn, bot_sha = \
            self._make_results_area(f, row_paths)
        res_fr.grid(row=1, column=0, sticky="nsew", pady=(0,0))

        lb.bind("<Button-3>", lambda e: self._ctx(e, lb, row_paths))
        lb.bind("<Double-Button-1>", lambda e: self._open_lb(lb, row_paths))
        clean_btn.config(command=lambda: self._bulk_trash_lb(
            lb, row_paths, result_lbl))

        scan_btn = tk.Button(bot_sha, text="Avvia scansione SHA256",
                             font=("TkFixedFont", 9, "bold"),
                             bg=SUCCESS, fg="white",
                             relief="flat", padx=12,
                             command=lambda: self._run_sha(
                                 get_folders, scan_btn,
                                 result_lbl, status_lbl,
                                 prog_canvas, prog_bar,
                                 lb, clean_btn, row_paths, stop_btn))
        scan_btn.pack(side="left", padx=(6,4), pady=5, ipady=3)

        # Ordinamento risultati
        tk.Label(bot_sha, text="Ordina:",
                 font=("TkFixedFont", 7), bg=BG_COLOR, fg=MUTED_COLOR
                 ).pack(side="left", padx=(10,2))
        self._sha_sort_var = tk.StringVar(value="size")
        for sval, stxt in [("size","Dimensione"),("folder","Cartella"),("name","Nome file")]:
            tk.Radiobutton(bot_sha, text=stxt, variable=self._sha_sort_var,
                           value=sval,
                           font=("TkFixedFont", 7), bg=BG_COLOR, fg=TEXT_COLOR,
                           selectcolor=BG_COLOR, activebackground=BG_COLOR,
                           activeforeground=HUD_CYAN,
                           command=lambda lb=lb, rp=row_paths: self._resort_dups(lb, rp)
                           ).pack(side="left", padx=2)

    def _resort_dups(self, lb, row_paths):
        """Riordina i risultati già in listbox per dimensione/cartella/nome."""
        sort_mode = getattr(self, '_sha_sort_var', None)
        if not sort_mode: return
        mode = sort_mode.get()
        # Raccoglie gruppi dalla listbox tramite row_paths. Sia le righe
        # header sia le righe separatore vuote hanno row_paths[i] = None:
        # vanno distinte guardando il testo, altrimenti ogni separatore
        # verrebbe scambiato per un nuovo gruppo (vuoto), moltiplicando le
        # righe vuote ad ogni riordino.
        groups = {}  # header_idx: [file_idx, ...]
        cur_header = None
        for i in range(lb.size()):
            fp = row_paths.get(i)
            if fp is None:
                if lb.get(i):   # testo non vuoto = riga header vera
                    cur_header = i
                    groups[cur_header] = []
                else:           # testo vuoto = separatore: chiude il gruppo
                    cur_header = None
            elif cur_header is not None:
                groups[cur_header].append(i)
        if not groups: return
        # Leggi testo e path attuali
        items = [(lb.get(i), row_paths.get(i)) for i in range(lb.size())]
        colors = [lb.itemcget(i, 'fg') for i in range(lb.size())]
        bgs    = [lb.itemcget(i, 'background') for i in range(lb.size())]
        # Costruisci lista gruppi
        group_list = []
        for hidx, fidxs in groups.items():
            hdr = items[hidx]
            files = [(items[i], colors[i], bgs[i]) for i in fidxs]
            # key per ordinamento
            if mode == 'size':
                key = -max((os.path.getsize(f[0][1]) for f in files
                            if f[0][1] and os.path.isfile(f[0][1])), default=0)
            elif mode == 'folder':
                key = os.path.dirname(files[0][0][1] or '') if files else ''
            else:  # name
                key = os.path.basename(files[0][0][1] or '') if files else ''
            group_list.append((key, hdr, files))
        group_list.sort(key=lambda x: x[0])
        # Ricostruisci listbox
        lb.delete(0, tk.END)
        row_paths.clear()
        idx = 0
        for _, hdr, files in group_list:
            lb.insert(tk.END, tk_safe(hdr[0]))
            lb.itemconfig(idx, fg='#ff88cc', background=PANEL_COLOR)
            row_paths[idx] = None; idx += 1
            for (txt, fp), fc, bg in files:
                lb.insert(tk.END, tk_safe(txt))
                lb.itemconfig(idx, fg=fc)
                row_paths[idx] = fp; idx += 1
            lb.insert(tk.END, '')
            row_paths[idx] = None; idx += 1

    def _run_sha(self, get_folders, scan_btn, result_lbl, status_lbl,
                 prog_canvas, prog_bar, lb, clean_btn, row_paths, stop_btn=None):
        folders = get_folders()
        if not folders:
            self.sorter._hud_alert("Attenzione", "Aggiungi almeno una cartella.",
                            parent=self.win)
            return
        lb.delete(0, tk.END)
        row_paths.clear()
        result_lbl.config(text="")
        clean_btn.config(state="disabled")
        scan_btn.config(state="disabled", text="Scansione...")
        if stop_btn and stop_btn.winfo_exists(): stop_btn.config(state="normal")
        self._stop = False

        threading.Thread(
            target=self._worker_sha,
            args=(folders, lb, status_lbl, prog_canvas, prog_bar,
                  result_lbl, clean_btn, scan_btn, row_paths, stop_btn),
            daemon=True).start()

    def _worker_sha(self, folders, lb, status_lbl, prog_canvas, prog_bar,
                    result_lbl, clean_btn, scan_btn, row_paths, stop_btn=None):
        hashes, duplicates, all_files = {}, {}, []

        for folder, recursive in folders:
            self._set_st(status_lbl, f"Raccolta file: {folder}")
            try:
                if recursive:
                    for root, _, files in os.walk(folder):
                        for f in files:
                            all_files.append(os.path.join(root, f))
                else:
                    all_files += [os.path.join(folder, f)
                                  for f in os.listdir(folder)
                                  if os.path.isfile(os.path.join(folder, f))]
            except OSError:
                pass

        media = [f for f in all_files
                 if detect_media_type(f) in MEDIA_EXTENSIONS
                 or os.path.splitext(f)[1].lower() in MEDIA_EXTENSIONS]
        total = len(media)

        def _stopped():
            if not self._stop:
                return False
            def _rst():
                if scan_btn.winfo_exists(): scan_btn.config(state="normal", text="Avvia scansione SHA256")
                if stop_btn and stop_btn.winfo_exists(): stop_btn.config(state="disabled")
            self.win.after(0, _rst)
            return True

        # --- Fase 1: raggruppa per dimensione ESATTA — nessuna lettura di
        # contenuto, solo os.path.getsize(). Due file di dimensione diversa
        # non possono mai essere identici: i file con una dimensione unica
        # nell'insieme analizzato si scartano subito, senza calcolare
        # nessun hash. Su cartelle con molti file diversi tra loro, questo
        # da solo elimina la stragrande maggioranza del lavoro.
        self._set_st(status_lbl, f"Controllo dimensioni: {total} file...")
        sizes = {}
        by_size = {}
        for idx, fpath in enumerate(media):
            if idx % 50 == 0:
                self._set_prog(prog_canvas, prog_bar, idx+1, total)
            try:
                size = os.path.getsize(fpath)
            except OSError:
                continue
            if size == 0:
                continue
            sizes[fpath] = size
            by_size.setdefault(size, []).append(fpath)
        if _stopped():
            return
        size_candidates = [fp for group in by_size.values() if len(group) > 1
                           for fp in group]

        # --- Fase 2: hash veloce (solo inizio + fine del file, non il
        # contenuto completo) sui soli candidati che condividono la
        # dimensione con almeno un altro file. Due file di dimensione
        # identica ma con inizio o fine diversi non possono essere
        # identici: si scartano qui senza leggere l'intero file — decisivo
        # per file grandi come i video, dove leggere tutto solo per
        # scoprire che sono diversi sarebbe lo spreco maggiore.
        n_cand = len(size_candidates)
        self._set_st(status_lbl, f"Controllo rapido: {n_cand} file simili per dimensione...")
        by_partial = {}
        for idx, fpath in enumerate(size_candidates):
            if _stopped():
                return
            if idx % 10 == 0:
                self._set_st(status_lbl,
                             tk_safe(f"Controllo rapido {idx+1}/{n_cand}  {os.path.basename(fpath)[:50]}"))
                self._set_prog(prog_canvas, prog_bar, idx+1, n_cand)
            try:
                ph = self._partial_hash_file(fpath, sizes[fpath])
                by_partial.setdefault((sizes[fpath], ph), []).append(fpath)
            except Exception:
                continue
        partial_candidates = [fp for group in by_partial.values() if len(group) > 1
                              for fp in group]

        # --- Fase 3: hash SHA256 completo, di conferma definitiva, solo
        # sui pochi file rimasti (stessa dimensione E stesso inizio/fine).
        n_final = len(partial_candidates)
        self._set_st(status_lbl, f"Verifica completa: {n_final} file...")
        for idx, fpath in enumerate(partial_candidates):
            if _stopped():
                return
            if idx % 10 == 0:
                self._set_st(status_lbl,
                             tk_safe(f"Verifica {idx+1}/{n_final}  {os.path.basename(fpath)[:50]}"))
                self._set_prog(prog_canvas, prog_bar, idx+1, n_final)
            try:
                h = self._hash_file(fpath)
                info = {"path": fpath, "size": sizes[fpath],
                        "ext": os.path.splitext(fpath)[1].upper() or "?"}
                if h in hashes:
                    if h not in duplicates:
                        duplicates[h] = [hashes[h]]
                    duplicates[h].append(info)
                else:
                    hashes[h] = info
            except Exception:
                continue

        self.win.after(0, lambda: self._show_dup_results(
            duplicates, total, lb, status_lbl, prog_canvas, prog_bar,
            result_lbl, clean_btn, scan_btn,
            row_paths, "Avvia scansione SHA256", stop_btn))

    # ── TAB 2: Rapida ─────────────────────────────────────────────────────────

    def _build_quick_tab(self):
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)

        top = tk.Frame(f, bg=BG_COLOR)
        top.grid(row=0, column=0, sticky="ew", padx=8, pady=(4,0))
        top.columnconfigure(0, weight=1)

        tk.Label(top, text="Cartelle da analizzare (confronto nome + dimensione):",
                 font=("TkFixedFont", 8), bg=BG_COLOR,
                 fg=MUTED_COLOR).grid(row=0, column=0, sticky="w", pady=(0,3))

        folder_fr, get_folders = self._make_folder_list(top, multi=True)
        folder_fr.grid(row=1, column=0, sticky="ew", pady=(2,4))

        # Opzioni modalità
        opt_fr = tk.Frame(top, bg=BG_COLOR)
        opt_fr.grid(row=2, column=0, sticky="w", pady=(0,4))

        mode_var = tk.StringVar(value="name_size")
        tk.Label(opt_fr, text="Criteri:",
                 font=("TkFixedFont", 8), bg=BG_COLOR,
                 fg=MUTED_COLOR).pack(side="left", padx=(0,6))
        for val, txt in [("name_size", "Nome + Dimensione"),
                         ("name",      "Solo Nome"),
                         ("size",      "Solo Dimensione")]:
            tk.Radiobutton(opt_fr, text=txt, variable=mode_var, value=val,
                           font=("TkFixedFont", 8), bg=BG_COLOR,
                           fg=TEXT_COLOR, selectcolor=BG_COLOR,
                           activebackground=BG_COLOR,
                           activeforeground=HUD_CYAN
                           ).pack(side="left", padx=4)

        row_paths = {}
        res_fr, lb, status_lbl, prog_canvas, prog_bar, result_lbl, clean_btn, stop_btn, bot_q = \
            self._make_results_area(f, row_paths)
        res_fr.grid(row=1, column=0, sticky="nsew", pady=(0,0))

        lb.bind("<Button-3>", lambda e: self._ctx(e, lb, row_paths))
        lb.bind("<Double-Button-1>", lambda e: self._open_lb(lb, row_paths))
        clean_btn.config(command=lambda: self._bulk_trash_lb(
            lb, row_paths, result_lbl))

        scan_btn = tk.Button(bot_q, text="Avvia scansione rapida",
                             font=("TkFixedFont", 9, "bold"),
                             bg=SUCCESS, fg="white",
                             relief="flat", padx=12,
                             command=lambda: self._run_quick(
                                 get_folders, mode_var.get(), scan_btn,
                                 result_lbl, status_lbl,
                                 prog_canvas, prog_bar,
                                 lb, clean_btn, row_paths, stop_btn))
        scan_btn.pack(side="left", padx=(6,4), pady=5, ipady=3)

    def _run_quick(self, get_folders, mode, scan_btn, result_lbl, status_lbl,
                   prog_canvas, prog_bar, lb, clean_btn, row_paths, stop_btn=None):
        folders = get_folders()
        if not folders:
            self.sorter._hud_alert("Attenzione", "Aggiungi almeno una cartella.",
                            parent=self.win)
            return
        lb.delete(0, tk.END)
        row_paths.clear()
        result_lbl.config(text="")
        clean_btn.config(state="disabled")
        scan_btn.config(state="disabled", text="Scansione...")
        if stop_btn and stop_btn.winfo_exists(): stop_btn.config(state="normal")
        self._stop = False

        threading.Thread(
            target=self._worker_quick,
            args=(folders, mode, lb, status_lbl, prog_canvas, prog_bar,
                  result_lbl, clean_btn, scan_btn, row_paths, stop_btn),
            daemon=True).start()

    def _worker_quick(self, folders, mode, lb, status_lbl, prog_canvas,
                      prog_bar, result_lbl, clean_btn, scan_btn, row_paths, stop_btn=None):
        all_files = []
        for folder, recursive in folders:
            self._set_st(status_lbl, f"Raccolta: {folder}")
            try:
                if recursive:
                    for root, _, files in os.walk(folder):
                        for fn in files:
                            all_files.append(os.path.join(root, fn))
                else:
                    all_files += [os.path.join(folder, fn)
                                  for fn in os.listdir(folder)
                                  if os.path.isfile(os.path.join(folder, fn))]
            except OSError:
                pass

        media = [f for f in all_files
                 if detect_media_type(f) in MEDIA_EXTENSIONS
                 or os.path.splitext(f)[1].lower() in MEDIA_EXTENSIONS]
        total = len(media)
        self._set_st(status_lbl, f"Indicizzazione {total} file...")

        groups = {}
        for idx, fpath in enumerate(media):
            if self._stop:
                def _rst():
                    if scan_btn.winfo_exists(): scan_btn.config(state="normal", text="Avvia scansione rapida")
                    if stop_btn and stop_btn.winfo_exists(): stop_btn.config(state="disabled")
                self.win.after(0, _rst)
                return
            self._set_prog(prog_canvas, prog_bar, idx+1, total)
            try:
                size = os.path.getsize(fpath)
                name = os.path.basename(fpath).lower()
                if mode == "name_size":
                    key = (name, size)
                elif mode == "name":
                    key = name
                else:
                    key = size
                info = {"path": fpath, "size": size,
                        "ext": os.path.splitext(fpath)[1].upper() or "?"}
                groups.setdefault(key, []).append(info)
            except Exception:
                continue

        duplicates = {k: v for k, v in groups.items() if len(v) > 1}
        self.win.after(0, lambda: self._show_dup_results(
            duplicates, total, lb, status_lbl, prog_canvas, prog_bar,
            result_lbl, clean_btn, scan_btn,
            row_paths, "Avvia scansione rapida", stop_btn,
            label_hash=False))

    # ── TAB 3: A vs B ─────────────────────────────────────────────────────────

    def _build_ab_tab(self):
        """Tab confronto A vs B — layout a colonne, barra in fondo coerente."""
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)

        # ── Pannello superiore ────────────────────────────────────────────────
        top = tk.Frame(f, bg=BG_COLOR)
        top.grid(row=0, column=0, sticky="ew", padx=8, pady=(4,0))
        top.columnconfigure(1, weight=1)

        tk.Label(top, text="Confronta A vs B — mostra i file presenti in entrambe le cartelle:",
                 font=("TkFixedFont", 8), bg=BG_COLOR,
                 fg=MUTED_COLOR).grid(row=0, column=0, columnspan=4, sticky="w", pady=(0,4))

        self._ab_vars = {}
        for row_i, (lbl, color) in enumerate([("A", HUD_CYAN), ("B", "#ffaa44")]):
            tk.Label(top, text=_Tf("Cartella {lbl}:", self.sorter.config.get("language","it"), lbl=lbl),
                     font=("TkFixedFont", 9, "bold"),
                     bg=BG_COLOR, fg=color).grid(
                     row=row_i+1, column=0, sticky="w", padx=(0,6), pady=2)
            pvar = tk.StringVar(value=self._initial_dir if lbl == "A" else "")
            tk.Entry(top, textvariable=pvar,
                     font=("TkFixedFont", 9), bg=ACCENT_COLOR, fg=color,
                     insertbackground=color, relief="flat", bd=3
                     ).grid(row=row_i+1, column=1, sticky="ew", padx=4, ipady=3, pady=2)
            def _browse(v=pvar):
                d = browse_folder_hud(self.win, title="Scegli cartella",
                    initial_dir=v.get() or self._initial_dir)
                if d: v.set(d)
            tk.Button(top, text="...",
                      font=("TkFixedFont", 8), bg=PANEL_COLOR, fg=TEXT_COLOR,
                      relief="flat", padx=6, command=_browse
                      ).grid(row=row_i+1, column=2, padx=(0,4), pady=2, ipady=3)
            rec_var = tk.BooleanVar(value=True)
            tk.Checkbutton(top, text="Sottocartelle", variable=rec_var,
                           font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR,
                           selectcolor=BG_COLOR, activebackground=BG_COLOR
                           ).grid(row=row_i+1, column=3, padx=6)
            self._ab_vars[lbl] = (pvar, rec_var)

        opt_fr = tk.Frame(top, bg=BG_COLOR)
        opt_fr.grid(row=3, column=0, columnspan=4, sticky="w", pady=(2,0))
        tk.Label(opt_fr, text="Metodo:",
                 font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR
                 ).pack(side="left", padx=(0,6))
        ab_mode_var = tk.StringVar(value="sha")
        for val, txt in [("sha",       "SHA256 (esatto)"),
                         ("name_size", "Nome + Dimensione"),
                         ("size",      "Solo Dimensione"),
                         ("name",      "Solo Nome")]:
            tk.Radiobutton(opt_fr, text=txt, variable=ab_mode_var, value=val,
                           font=("TkFixedFont", 8), bg=BG_COLOR,
                           fg=TEXT_COLOR, selectcolor=BG_COLOR,
                           activebackground=BG_COLOR, activeforeground=HUD_CYAN
                           ).pack(side="left", padx=4)

        # ── Area risultati: liste sopra, anteprima larga A/B sotto ────────────
        # Divisore verticale (non orizzontale come nelle altre due tab):
        # qui il confronto e' sempre uno-contro-uno, non un gruppo di N
        # doppioni, quindi ha piu' senso vedere le due miniature affiancate
        # e grandi piuttosto che impilate in una colonna stretta.
        paned_ab = tk.PanedWindow(f, orient="vertical", bg=BG_COLOR,
                                  sashwidth=4, sashrelief="flat")
        paned_ab.grid(row=1, column=0, sticky="nsew")

        res_outer = tk.Frame(paned_ab, bg=BG_COLOR)
        res_outer.columnconfigure(0, weight=1)
        res_outer.columnconfigure(1, weight=1)
        res_outer.rowconfigure(1, weight=1)
        paned_ab.add(res_outer, stretch="always", minsize=100)

        for ci, (lbl, color) in enumerate([("A", HUD_CYAN), ("B", "#ffaa44")]):
            hdr = tk.Frame(res_outer, bg=ACCENT_COLOR)
            hdr.grid(row=0, column=ci, sticky="ew",
                     padx=(4 if ci == 0 else 1, 1 if ci == 0 else 4))
            tk.Label(hdr, text=_Tf("Cartella {lbl}:", self.sorter.config.get("language","it"), lbl=lbl),
                     font=("TkFixedFont", 9, "bold"),
                     bg=ACCENT_COLOR, fg=color).pack(side="left", pady=2)

        self._lb_a = tk.Listbox(res_outer, font=("TkFixedFont", 8),
                                bg=BG_COLOR, fg=HUD_CYAN,
                                selectbackground=HIGHLIGHT, selectforeground="white",
                                activestyle="none", relief="flat", bd=0,
                                exportselection=False, selectmode=tk.EXTENDED)
        self._lb_b = tk.Listbox(res_outer, font=("TkFixedFont", 8),
                                bg=BG_COLOR, fg="#ffaa44",
                                selectbackground="#5a3a00", selectforeground="white",
                                activestyle="none", relief="flat", bd=0,
                                exportselection=False, selectmode=tk.EXTENDED)

        vsb = ttk.Scrollbar(res_outer, orient="vertical")
        vsb.grid(row=1, column=2, sticky="ns")

        def _scroll_both(*args):
            self._lb_a.yview(*args)
            self._lb_b.yview(*args)
        vsb.config(command=_scroll_both)
        self._lb_a.config(yscrollcommand=lambda *a: (vsb.set(*a), self._lb_b.yview_moveto(a[0])))
        self._lb_b.config(yscrollcommand=lambda *a: (vsb.set(*a), self._lb_a.yview_moveto(a[0])))
        self._lb_a.grid(row=1, column=0, sticky="nsew", padx=(4,1))
        self._lb_b.grid(row=1, column=1, sticky="nsew", padx=(1,0))

        for lb in (self._lb_a, self._lb_b):
            lb.bind("<Button-4>", lambda e: _scroll_both("scroll", -1, "units"))
            lb.bind("<Button-5>", lambda e: _scroll_both("scroll",  1, "units"))
            lb.bind("<MouseWheel>",
                    lambda e: _scroll_both("scroll", -1 if e.delta>0 else 1, "units"))

        # ── Pannello inferiore: anteprima larga della coppia selezionata ──────
        prev_fr = tk.Frame(paned_ab, bg=PANEL_COLOR, height=230)
        prev_fr.pack_propagate(False)
        paned_ab.add(prev_fr, stretch="never", minsize=130)
        prev_fr.columnconfigure(0, weight=1)
        prev_fr.columnconfigure(1, weight=1)
        prev_fr.rowconfigure(0, weight=1)

        self._ab_prev_imgs = []   # riferimenti PhotoImage, altrimenti Tk li scarta
        _ab_prev_widgets = {}     # "A"/"B" -> (canvas, label)

        for ci, (side, color) in enumerate([("A", HUD_CYAN), ("B", "#ffaa44")]):
            cell = tk.Frame(prev_fr, bg=PANEL_COLOR)
            cell.grid(row=0, column=ci, sticky="nsew",
                     padx=(6 if ci == 0 else 3, 3 if ci == 0 else 6), pady=6)
            cv = tk.Canvas(cell, bg=BG_COLOR, highlightthickness=1,
                          highlightbackground=ACCENT_COLOR)
            cv.pack(fill="both", expand=True)
            info = tk.Label(cell, text="", font=("TkFixedFont", 8),
                           bg=PANEL_COLOR, fg=color, anchor="w")
            info.pack(fill="x", pady=(3,0))
            _ab_prev_widgets[side] = (cv, info)

        def _ab_ctx_preview(side, fp, e):
            """Menu tasto destro su una cella di anteprima: stesse azioni
            del menu tasto destro sulla riga, ma partendo dal file gia'
            noto invece che dalla posizione del click nella listbox."""
            if not fp:
                return
            lb  = self._lb_a if side == "A" else self._lb_b
            rmap = self._ab_row_a if side == "A" else self._ab_row_b
            sel = lb.curselection()
            if not sel:
                return
            idx = sel[0]
            menu = tk.Menu(self.win, tearoff=0,
                           bg=PANEL_COLOR, fg=TEXT_COLOR,
                           activebackground=HIGHLIGHT, activeforeground="white",
                           relief="flat")
            menu.add_command(label="Apri file",
                             command=lambda: subprocess.Popen(
                                 ["xdg-open", fp],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))
            menu.add_command(label="Mostra in file manager",
                             command=lambda: open_in_filemanager(fp))
            menu.add_separator()
            menu.add_command(label="Cestina questo file",
                             command=lambda: (self._trash_ab(idx, fp, lb, rmap),
                                              _update_ab_preview()))
            _post_menu(menu, e.x_root, e.y_root, self.win)

        def _update_ab_preview(e=None, src=None):
            """Ridisegna le due miniature per la riga appena cliccata.

            Chiamata ad ogni cambio di selezione in A o B (che restano
            sincronizzate fra loro, vedi _sync_sel). Con la selezione
            multipla curselection() torna sempre gli indici in ordine
            CRESCENTE, non nell'ordine dei clic: usare sel[0] mostrava
            sempre la riga con l'indice piu' basso fra quelle scelte,
            non quella su cui si era appena fatto Ctrl+clic — sembrava
            che l'anteprima "non si aggiornasse" quando in realta'
            stava mostrando, correttamente, un'altra riga della stessa
            selezione. index("active") segue invece l'ultima riga
            toccata dal clic, qualunque sia il suo indice.
            """
            lb  = src if src is not None else self._lb_a
            sel = lb.curselection()
            active = lb.index("active")
            idx = active if active in sel else (sel[0] if sel else None)
            for side, rowmap in (("A", self._ab_row_a), ("B", self._ab_row_b)):
                cv, info = _ab_prev_widgets[side]
                cv.delete("all")
                for w in (cv, info):
                    w.unbind("<Button-3>")
                fp = rowmap.get(idx) if idx is not None else None
                if not fp or not os.path.isfile(fp):
                    info.config(text="")
                    continue
                name = os.path.basename(fp)
                short = name if len(name) <= 40 else name[:38] + ".."
                try:
                    size_txt = f"{os.path.getsize(fp)//1024} KB"
                except Exception:
                    size_txt = ""
                ext = os.path.splitext(fp)[1].upper().lstrip(".")
                info.config(text=tk_safe(f"{short}  -  {size_txt}  {ext}"))
                for w in (cv, info):
                    w.bind("<Button-3>",
                           lambda e, s=side, p=fp: _ab_ctx_preview(s, p, e))
                    w.bind("<Double-Button-1>", lambda e, p=fp:
                        subprocess.Popen(["xdg-open", p],
                            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))

                cv.update_idletasks()
                cw, ch = cv.winfo_width() or 260, cv.winfo_height() or 200
                ts = max(min(cw, ch) - 12, 80)

                def _load(p=fp, c=cv, ts=ts, cw=cw, ch=ch):
                    try:
                        img = load_thumbnail(p, ts)
                        if not img:
                            return
                        img = img.copy()
                        def _show(im=img, c=c, cw=cw, ch=ch):
                            if not c.winfo_exists():
                                return
                            ph = ImageTk.PhotoImage(im)
                            self._ab_prev_imgs.append(ph)
                            c.create_image(cw//2, ch//2, anchor="center", image=ph)
                        self.win.after(0, _show)
                    except Exception:
                        pass
                threading.Thread(target=_load, daemon=True).start()

        # Richiamabile anche da _run_ab_col(), che vive fuori da questa
        # chiusura: serve per svuotare l'anteprima quando parte una
        # nuova scansione, altrimenti resterebbero a video le miniature
        # della ricerca precedente finche' non si clicca una riga nuova.
        self._ab_update_preview = _update_ab_preview

        self._ab_row_a = {}
        self._ab_row_b = {}

        def _sync_sel(lb_src, lb_dst):
            """Rispecchia TUTTA la selezione (non solo la prima riga) da
            una lista all'altra: con la selezione multipla, scegliendo
            piu' righe in A si vedono evidenziate le stesse righe anche
            in B, cosi' si vede su entrambi i lati cosa si sta per
            cestinare prima di confermare."""
            sel = lb_src.curselection()
            lb_dst.selection_clear(0, tk.END)
            for i in sel:
                lb_dst.selection_set(i)
            if sel:
                lb_dst.see(sel[0])
        self._lb_a.bind("<<ListboxSelect>>", lambda e: (_sync_sel(self._lb_a, self._lb_b), _update_ab_preview(src=self._lb_a)))
        self._lb_b.bind("<<ListboxSelect>>", lambda e: (_sync_sel(self._lb_b, self._lb_a), _update_ab_preview(src=self._lb_b)))

        def _open_ab(lb, row_map, e=None):
            sel = lb.curselection()
            if not sel: return
            fp = row_map.get(sel[0])
            if fp and os.path.isfile(fp):
                subprocess.Popen(["xdg-open", fp],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        self._lb_a.bind("<Double-Button-1>", lambda e: _open_ab(self._lb_a, self._ab_row_a))
        self._lb_b.bind("<Double-Button-1>", lambda e: _open_ab(self._lb_b, self._ab_row_b))

        def _ctx_ab(lb, row_map, e):
            idx = lb.nearest(e.y)
            fp  = row_map.get(idx)
            if not fp: return
            # Se la riga cliccata fa gia' parte di una selezione multipla
            # (Ctrl/Shift-clic), il tasto destro NON la deve azzerare: e'
            # quello che permette di scegliere piu' righe e poi cestinarle
            # tutte insieme, invece che una alla volta. Solo se si clicca
            # una riga fuori dalla selezione corrente si riparte da capo
            # con quella sola, com'era prima.
            cur_sel = lb.curselection()
            multi = len(cur_sel) > 1 and idx in cur_sel
            if not multi:
                lb.selection_clear(0, tk.END); lb.selection_set(idx)
            side_label = "A" if lb is self._lb_a else "B"
            menu = tk.Menu(self.win, tearoff=0,
                           bg=PANEL_COLOR, fg=TEXT_COLOR,
                           activebackground=HIGHLIGHT, activeforeground="white",
                           relief="flat")
            menu.add_command(label="Apri file",
                             command=lambda: subprocess.Popen(
                                 ["xdg-open", fp],
                                 stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL))
            menu.add_command(label="Mostra in file manager",
                             command=lambda: open_in_filemanager(fp))
            menu.add_separator()
            if multi:
                n = len(cur_sel)
                menu.add_command(label=f"Cestina i {n} file selezionati",
                                 command=lambda: self._trash_selected_ab(
                                     lb, row_map, side_label))
            else:
                menu.add_command(label="Cestina questo file",
                                 command=lambda: self._trash_ab(idx, fp, lb, row_map))
            # <Unmap> rimosso: distruggeva il menu prima del click
            _post_menu(menu, e.x_root, e.y_root, self.win)
        self._lb_a.bind("<Button-3>", lambda e: _ctx_ab(self._lb_a, self._ab_row_a, e))
        self._lb_b.bind("<Button-3>", lambda e: _ctx_ab(self._lb_b, self._ab_row_b, e))

        # ── Barra progresso (sopra barra bottoni) ────────────────────────────
        prog_fr = tk.Frame(f, bg=BG_COLOR)
        prog_fr.grid(row=2, column=0, sticky="ew", padx=8, pady=(0,2))
        prog_fr.columnconfigure(0, weight=1)
        self._ab_status_lbl = tk.Label(prog_fr, text="",
                                       font=("TkFixedFont", 8),
                                       bg=BG_COLOR, fg=MUTED_COLOR, anchor="w")
        self._ab_status_lbl.grid(row=0, column=0, sticky="ew")
        self._ab_prog_canvas = tk.Canvas(prog_fr, bg=ACCENT_COLOR,
                                         height=3, highlightthickness=0)
        self._ab_prog_canvas.grid(row=1, column=0, sticky="ew")
        self._ab_prog_bar = self._ab_prog_canvas.create_rectangle(
            0, 0, 0, 3, fill=HUD_CYAN, width=0)

        # ── Barra bottoni in fondo (coerente con SHA/Rapida) ─────────────────
        bot = tk.Frame(f, bg=PANEL_COLOR)
        bot.grid(row=3, column=0, sticky="ew")

        self._ab_result_lbl = tk.Label(bot, text="",
                                       font=("TkFixedFont", 9),
                                       bg=PANEL_COLOR, fg=MUTED_COLOR)
        self._ab_result_lbl.pack(side="left", padx=10, pady=5)

        # Chiudi per primo → appare più a destra
        tk.Button(bot, text="Chiudi",
                  font=("TkFixedFont", 8), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=8,
                  command=self._on_close
                  ).pack(side="right", padx=(0,6), pady=5, ipady=3)

        stop_btn = tk.Button(bot, text="Stop",
                             font=("TkFixedFont", 8, "bold"),
                             bg=HIGHLIGHT, fg="white",
                             relief="flat", padx=8, state="disabled",
                             command=lambda: setattr(self, "_stop", True))
        stop_btn.pack(side="right", padx=6, pady=5, ipady=3)

        self._ab_clean_btn = tk.Button(bot,
                             text="Cestina tutti i duplicati di B (mantieni A)",
                             font=("TkFixedFont", 8, "bold"),
                             bg="#c0392b", fg="white",
                             relief="flat", padx=10, state="disabled",
                             command=lambda: self._bulk_trash_ab())
        self._ab_clean_btn.pack(side="right", padx=6, pady=5, ipady=3)

        # Versione "selettiva" del bottone qui sopra: stessa idea (tieni
        # A, cestina B) ma solo per le righe che hai scelto tu con la
        # selezione multipla, invece che per tutte. La stessa cosa si
        # otteneva gia' col tasto destro sulla lista B, ma non era
        # visibile finche' non lo si scopriva da soli.
        self._ab_clean_sel_btn = tk.Button(bot,
                             text="Cestina selezionati (B)",
                             font=("TkFixedFont", 8, "bold"),
                             bg="#8a4a1e", fg="white",
                             relief="flat", padx=10, state="disabled",
                             command=lambda: self._trash_selected_ab(
                                 self._lb_b, self._ab_row_b, "B"))
        self._ab_clean_sel_btn.pack(side="right", padx=6, pady=5, ipady=3)

        # ── Bottone avvia nella barra in fondo (a sinistra) ─────────────────
        scan_btn = tk.Button(bot, text="Confronta A vs B",
                             font=("TkFixedFont", 9, "bold"),
                             bg=SUCCESS, fg="white",
                             relief="flat", padx=12,
                             command=lambda: self._run_ab_col(
                                 ab_mode_var.get(), scan_btn, stop_btn))
        scan_btn.pack(side="left", padx=(6,4), pady=5, ipady=3)

    def _trash_selected_ab(self, lb, row_map, side_label):
        """Cestina in blocco i file attualmente selezionati in UNA sola
        lista (A o B), con un'unica conferma invece di una per file.

        Raggiunta sia dal bottone "Cestina selezionati (B)" in fondo alla
        finestra sia dal menu tasto destro quando la riga cliccata fa
        parte di una selezione multipla (Ctrl/Shift-clic sulle righe):
        prima l'unico modo per togliere piu' file era ripetere "Cestina
        questo file" uno alla volta, oppure usare il bottone che cestina
        TUTTI i duplicati di B senza poter scegliere quali.
        """
        sel = lb.curselection()
        paths = [(i, row_map.get(i)) for i in sel]
        paths = [(i, p) for i, p in paths if p and os.path.isfile(p)]
        if not paths:
            # Dal tasto destro questo caso non si presenta mai (la voce
            # compare solo se c'e' gia' una selezione multipla), ma dal
            # bottone in barra si': senza avviso sembrerebbe che il
            # bottone non faccia nulla.
            self._ab_result_lbl.config(text=tk_safe(
                f"Nessuna riga selezionata in {side_label}"))
            return
        if not self.sorter._hud_yesno(f"Cestina {len(paths)} file",
                f"Spostare nel cestino {len(paths)} file "
                f"dalla cartella {side_label}?",
                yes_label="Cestina tutti", no_label="Annulla",
                parent=self.win):
            return
        done = 0
        for idx, fpath in paths:
            dest = move_to_transit(fpath, self.sorter.config)
            if dest:
                append_history({"action": "trashed_transit", "files": [fpath],
                                "dest": dest,
                                "note": f"doppioni: A vs B ({side_label}, "
                                       f"selezione multipla)"})
                lb.delete(idx)
                lb.insert(idx, tk_safe(f"  [cestinato]  {os.path.basename(fpath)}"))
                lb.itemconfig(idx, fg=MUTED_COLOR)
                row_map[idx] = None
                done += 1
        self._ab_result_lbl.config(text=tk_safe(f"{done} file cestinati"))
        upd = getattr(self, "_ab_update_preview", None)
        if upd:
            upd()

    def _trash_ab(self, idx, fpath, lb, row_map):
        """Cestina un file dalla vista colonne A vs B."""
        if not os.path.isfile(fpath):
            return
        if not self.sorter._hud_yesno("Cestina",
                f"Spostare nel cestino?\n{os.path.basename(fpath)}",
                yes_label="Cestina", no_label="Annulla",
                parent=self.win):
            return
        dest = move_to_transit(fpath, self.sorter.config)
        if dest:
            append_history({"action": "trashed_transit", "files": [fpath],
                            "dest": dest, "note": "doppioni: A vs B"})
            lb.delete(idx)
            lb.insert(idx, tk_safe(f"  [cestinato]  {os.path.basename(fpath)}"))
            lb.itemconfig(idx, fg=MUTED_COLOR)
            row_map[idx] = None
            upd = getattr(self, "_ab_update_preview", None)
            if upd:
                upd()

    def _bulk_trash_ab(self):
        """Cestina tutti i file di B (mantieni A)."""
        to_del = [(i, p) for i,p in self._ab_row_b.items()
                  if p and os.path.isfile(p)]
        if not to_del:
            return
        if not self.sorter._hud_yesno("Cestina duplicati B",
                f"Verranno cestinati TUTTI i {len(to_del)} file trovati "
                f"nella cartella B in questa ricerca (i corrispondenti "
                f"in A restano intatti).\n\nProcedere?",
                yes_label="Cestina tutti", no_label="Annulla",
                parent=self.win):
            return
        done = 0
        for idx, fp in to_del:
            dest = move_to_transit(fp, self.sorter.config)
            if dest:
                append_history({"action": "trashed_transit", "files": [fp],
                                "dest": dest, "note": "doppioni: A vs B tutti"})
                self._lb_b.delete(idx)
                self._lb_b.insert(idx, "  [cestinato]")
                self._lb_b.itemconfig(idx, fg=MUTED_COLOR)
                self._ab_row_b[idx] = None
                done += 1
        self._ab_result_lbl.config(text=_Tf("{done} file cestinati", self.sorter.config.get("language","it"), done=done))

    def _run_ab_col(self, mode, scan_btn, stop_btn):
        """Avvia la scansione A vs B per la vista a colonne."""
        pa, ra = self._ab_vars["A"]
        pb, rb = self._ab_vars["B"]
        dir_a, dir_b = pa.get().strip(), pb.get().strip()
        if not os.path.isdir(dir_a) or not os.path.isdir(dir_b):
            self.sorter._hud_alert("Attenzione",
                "Specifica due cartelle valide.", parent=self.win)
            return
        self._lb_a.delete(0, tk.END)
        self._lb_b.delete(0, tk.END)
        self._ab_row_a.clear()
        self._ab_row_b.clear()
        upd = getattr(self, "_ab_update_preview", None)
        if upd:
            upd()
        self._ab_result_lbl.config(text="")
        self._ab_clean_btn.config(state="disabled")
        self._ab_clean_sel_btn.config(state="disabled")
        scan_btn.config(state="disabled", text="Confronto...")
        stop_btn.config(state="normal")
        self._stop = False

        threading.Thread(
            target=self._worker_ab_col,
            args=(dir_a, ra.get(), dir_b, rb.get(), mode,
                  scan_btn, stop_btn),
            daemon=True).start()

    def _worker_ab_col(self, dir_a, rec_a, dir_b, rec_b, mode,
                       scan_btn, stop_btn):
        """Thread worker per confronto A vs B con vista a colonne."""

        def collect(folder, recursive):
            files = []
            try:
                if recursive:
                    for root, _, fns in os.walk(folder):
                        for fn in fns:
                            files.append(os.path.join(root, fn))
                else:
                    files = [os.path.join(folder, fn)
                             for fn in os.listdir(folder)
                             if os.path.isfile(os.path.join(folder, fn))]
            except OSError:
                pass
            return [f for f in files
                    if detect_media_type(f) in MEDIA_EXTENSIONS
                    or os.path.splitext(f)[1].lower() in MEDIA_EXTENSIONS]

        def key_of(fpath):
            try:
                size = os.path.getsize(fpath)
                name = os.path.basename(fpath).lower()
                if mode == "sha":      return self._hash_file(fpath)
                elif mode == "name_size": return (name, size)
                elif mode == "size":   return size
                else:                  return name
            except Exception:
                return None

        def upd_status(msg):
            self.win.after(0, lambda: self._ab_status_lbl.config(text=msg)
                           if self.win.winfo_exists() else None)
        def upd_prog(cur, tot):
            self.win.after(0, lambda: self._set_prog(
                self._ab_prog_canvas, self._ab_prog_bar, cur, tot)
                if self.win.winfo_exists() else None)

        upd_status("Raccolta file cartella A...")
        files_a = collect(dir_a, rec_a)
        upd_status("Raccolta file cartella B...")
        files_b = collect(dir_b, rec_b)
        total = len(files_a) + len(files_b)

        upd_status(f"Indicizzazione {len(files_a)} + {len(files_b)} file...")

        # Indice A: key → lista file
        index_a = {}
        for i, fp in enumerate(files_a):
            if self._stop: break
            upd_prog(i+1, total)
            k = key_of(fp)
            if k is not None:
                try: size = os.path.getsize(fp)
                except Exception: size = 0
                ext  = os.path.splitext(fp)[1].upper() or "?"
                rel  = os.path.relpath(fp, dir_a)
                index_a.setdefault(k, []).append(
                    {"path": fp, "size": size, "ext": ext, "rel": rel})

        # Scansiona B e trova corrispondenze
        matches = []  # [(key, file_a, file_b)]
        for i, fp in enumerate(files_b):
            if self._stop: break
            upd_prog(len(files_a)+i+1, total)
            k = key_of(fp)
            if k is not None and k in index_a:
                try: size = os.path.getsize(fp)
                except Exception: size = 0
                ext  = os.path.splitext(fp)[1].upper() or "?"
                rel  = os.path.relpath(fp, dir_b)
                b_info = {"path": fp, "size": size, "ext": ext, "rel": rel}
                for a_info in index_a[k]:
                    matches.append((a_info, b_info))

        self.win.after(0, lambda: self._show_ab_col_results(
            matches, len(files_a)+len(files_b), dir_a, dir_b,
            scan_btn, stop_btn))

    def _show_ab_col_results(self, matches, total, dir_a, dir_b,
                              scan_btn, stop_btn):
        """Mostra i risultati nella vista a colonne."""
        if not self.win.winfo_exists():
            return
        scan_btn.config(state="normal", text="Confronta A vs B")
        stop_btn.config(state="disabled")
        self._set_prog(self._ab_prog_canvas, self._ab_prog_bar, 1, 1)

        if not matches:
            self._ab_status_lbl.config(
                text=_Tf("Nessun duplicato trovato ({total} file scansionati).", self.sorter.config.get("language","it"), total=total))
            self._ab_result_lbl.config(text="Nessun duplicato.")
            play_sound("done")
            return

        # Ordina per dimensione decrescente
        matches.sort(key=lambda m: -m[0]["size"])

        self._ab_result_lbl.config(text=_Tf("{n} coppie trovate", self.sorter.config.get("language","it"), n=len(matches)))
        self._ab_status_lbl.config(
            text=_Tf("{n} coppie duplicate su {total} file scansionati.", self.sorter.config.get("language","it"), n=len(matches), total=total))
        self._ab_clean_btn.config(state="normal")
        self._ab_clean_sel_btn.config(state="normal")
        play_sound("done")

        row = 0
        for a_info, b_info in matches:
            # Intestazione riga: dimensione + nome file
            size_str = self._fmt(a_info["size"])
            name_a   = os.path.basename(a_info["path"])
            name_b   = os.path.basename(b_info["path"])
            same_name = name_a.lower() == name_b.lower()

            # Colonna A
            line_a = tk_safe(f"  {a_info['ext']:<6} {size_str:>9}  {a_info['rel']}")
            self._lb_a.insert(tk.END, line_a)
            col_a = HUD_CYAN if same_name else "#88ffcc"
            self._lb_a.itemconfig(row, fg=col_a)
            self._ab_row_a[row] = a_info["path"]

            # Colonna B
            size_b_str = self._fmt(b_info["size"])
            line_b = tk_safe(f"  {b_info['ext']:<6} {size_b_str:>9}  {b_info['rel']}")
            self._lb_b.insert(tk.END, line_b)
            col_b = "#ffaa44" if same_name else "#ffdd88"
            self._lb_b.itemconfig(row, fg=col_b)
            self._ab_row_b[row] = b_info["path"]
            row += 1

        # Aggiorna label intestazioni con percorsi
        # (non possiamo accedere agli header label facilmente, usiamo status)
        self._ab_status_lbl.config(
            text=tk_safe(f"A: {dir_a}   |   B: {dir_b}   |   {len(matches)} coppie"))

    def _run_ab(self, mode, scan_btn, result_lbl, status_lbl,
                prog_canvas, prog_bar, lb, clean_btn, row_paths, stop_btn=None):
        pa, ra = self._ab_vars["A"]
        pb, rb = self._ab_vars["B"]
        dir_a, dir_b = pa.get().strip(), pb.get().strip()
        if not os.path.isdir(dir_a) or not os.path.isdir(dir_b):
            self.sorter._hud_alert("Attenzione",
                "Specifica due cartelle valide.", parent=self.win)
            return
        lb.delete(0, tk.END)
        row_paths.clear()
        result_lbl.config(text="")
        clean_btn.config(state="disabled")
        scan_btn.config(state="disabled", text="Confronto...")
        if stop_btn and stop_btn.winfo_exists(): stop_btn.config(state="normal")
        self._stop = False

        threading.Thread(
            target=self._worker_ab,
            args=(dir_a, ra.get(), dir_b, rb.get(), mode,
                  lb, status_lbl, prog_canvas, prog_bar,
                  result_lbl, clean_btn, scan_btn, row_paths, stop_btn),
            daemon=True).start()

    def _worker_ab(self, dir_a, rec_a, dir_b, rec_b, mode,
                   lb, status_lbl, prog_canvas, prog_bar,
                   result_lbl, clean_btn, scan_btn, row_paths, stop_btn=None):

        def collect(folder, recursive):
            files = []
            try:
                if recursive:
                    for root, _, fns in os.walk(folder):
                        for fn in fns:
                            files.append(os.path.join(root, fn))
                else:
                    files = [os.path.join(folder, fn)
                             for fn in os.listdir(folder)
                             if os.path.isfile(os.path.join(folder, fn))]
            except OSError:
                pass
            return [f for f in files
                    if detect_media_type(f) in MEDIA_EXTENSIONS
                    or os.path.splitext(f)[1].lower() in MEDIA_EXTENSIONS]

        def key_of(fpath, mode):
            try:
                size = os.path.getsize(fpath)
                name = os.path.basename(fpath).lower()
                if mode == "sha":
                    return self._hash_file(fpath)
                elif mode == "name_size":
                    return (name, size)
                elif mode == "size":
                    return size
                else:
                    return name
            except Exception:
                return None

        self._set_st(status_lbl, "Raccolta file cartella A...")
        files_a = collect(dir_a, rec_a)
        self._set_st(status_lbl, "Raccolta file cartella B...")
        files_b = collect(dir_b, rec_b)

        total = len(files_a) + len(files_b)
        self._set_st(status_lbl,
                     f"Indicizzazione {len(files_a)} + {len(files_b)} file...")

        # Indice A
        index_a = {}
        for idx, fpath in enumerate(files_a):
            if self._stop:
                self.win.after(0, lambda: (scan_btn.config(state="normal", text="Confronta A vs B") if scan_btn.winfo_exists() else None, stop_btn.config(state="disabled") if stop_btn and stop_btn.winfo_exists() else None))
                return
            self._set_prog(prog_canvas, prog_bar, idx+1, total)
            k = key_of(fpath, mode)
            if k:
                size = os.path.getsize(fpath)
                index_a.setdefault(k, []).append(
                    {"path": fpath, "size": size,
                     "ext": os.path.splitext(fpath)[1].upper() or "?"})

        # Scansiona B, trova corrispondenze in A
        duplicates = {}
        for idx, fpath in enumerate(files_b):
            if self._stop:
                self.win.after(0, lambda: (scan_btn.config(state="normal", text="Confronta A vs B") if scan_btn.winfo_exists() else None, stop_btn.config(state="disabled") if stop_btn and stop_btn.winfo_exists() else None))
                return
            self._set_prog(prog_canvas, prog_bar,
                           len(files_a)+idx+1, total)
            k = key_of(fpath, mode)
            if k and k in index_a:
                size = os.path.getsize(fpath)
                b_info = {"path": fpath, "size": size,
                          "ext": os.path.splitext(fpath)[1].upper() or "?"}
                # Gruppo: [file A, file B]
                group_key = k
                if group_key not in duplicates:
                    duplicates[group_key] = list(index_a[k])
                duplicates[group_key].append(b_info)

        self.win.after(0, lambda: self._show_dup_results(
            duplicates, total, lb, status_lbl, prog_canvas, prog_bar,
            result_lbl, clean_btn, scan_btn,
            row_paths, "Confronta A vs B", stop_btn,
            label_hash=False,
            origin_a=dir_a))

    # ── Visualizzazione risultati ─────────────────────────────────────────────

    def _show_dup_results(self, duplicates, total_scanned,
                          lb, status_lbl, prog_canvas, prog_bar,
                          result_lbl, clean_btn, scan_btn,
                          row_paths, btn_label, stop_btn=None,
                          label_hash=True, origin_a=None):
        if not self.win.winfo_exists():
            return
        def _scan_done():
            if scan_btn.winfo_exists():
                scan_btn.config(state="normal", text=btn_label)
            if stop_btn and stop_btn.winfo_exists():
                stop_btn.config(state="disabled")
        self.win.after(0, _scan_done)
        self._set_prog(prog_canvas, prog_bar, 1, 1)

        if not duplicates:
            self._set_st(status_lbl,
                         f"Nessun duplicato trovato ({total_scanned} file).")
            result_lbl.config(text="")
            play_sound("done")
            return

        n_groups = len(duplicates)
        n_dupes  = sum(len(v)-1 for v in duplicates.values())
        _lang = self.sorter.config.get("language","it")
        result_lbl.config(
            text=_Tf("{n_groups} gruppi  —  {n_dupes} file duplicati su {total_scanned} analizzati",
                     _lang, n_groups=n_groups, n_dupes=n_dupes, total_scanned=total_scanned))
        self._set_st(status_lbl, "")
        clean_btn.config(state="normal")
        play_sound("done")

        # Prepara tutte le righe in anticipo (no rendering)
        all_rows = []  # lista di (testo, bg, fg, fpath)
        for h, files in sorted(duplicates.items(),
                                key=lambda x: -x[1][0]["size"]):
            files = sorted(files, key=_copy_score)
            total_sz = sum(fi["size"] for fi in files)
            suffix   = f"hash {str(h)[:10]}" if label_hash else ""
            header   = tk_safe(f"  --- {len(files)} file identici | "
                               f"{self._fmt(total_sz)} | {suffix} ---")
            all_rows.append((header, PANEL_COLOR, "#ff88cc", None))
            for i, fi in enumerate(files):
                if origin_a:
                    tag = "  [A]  " if fi["path"].startswith(origin_a) else "  [B]  "
                    col = TEXT_COLOR if fi["path"].startswith(origin_a) else "#ffaa44"
                else:
                    tag = "  [ORIG]  " if i == 0 else "  [COPIA] "
                    col = TEXT_COLOR if i == 0 else "#ffaa88"
                line = tk_safe(f"{tag}{fi['ext']:<6} {self._fmt(fi['size']):>10}  {fi['path']}")
                all_rows.append((line, None, col, fi["path"]))
            all_rows.append(("", None, None, None))

        # Inserisce in batch da 50 righe con after() per non bloccare X11
        BATCH = 50
        def _insert_batch(start_idx):
            end_idx = min(start_idx + BATCH, len(all_rows))
            for i in range(start_idx, end_idx):
                text, bg, fg, fpath = all_rows[i]
                row_idx = i
                lb.insert(tk.END, text)
                if bg: lb.itemconfig(row_idx, bg=bg)
                if fg: lb.itemconfig(row_idx, fg=fg)
                row_paths[row_idx] = fpath
            if end_idx < len(all_rows):
                self.win.after(10, lambda: _insert_batch(end_idx))

        _insert_batch(0)

    # ── Azioni lista ──────────────────────────────────────────────────────────

    def _ctx_path(self, event, fpath):
        """Menu contestuale per un singolo file (usato anche dall'anteprima)."""
        menu = tk.Menu(self.win, tearoff=0,
                       bg=PANEL_COLOR, fg=TEXT_COLOR,
                       activebackground=HIGHLIGHT,
                       activeforeground="white", relief="flat")
        menu.add_command(label="Apri file",
                         command=lambda: subprocess.Popen(
                             ["xdg-open", fpath],
                             stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL))
        menu.add_command(label="Mostra in file manager",
                         command=lambda p=fpath: open_in_filemanager(p))
        menu.add_separator()
        menu.add_command(label="Copia percorso",
                         command=lambda: (self.win.clipboard_clear(),
                                          self.win.clipboard_append(fpath)))
        menu.add_separator()
        menu.add_command(label="Sposta nel cestino",
                         command=lambda: self._trash_and_refresh(fpath))
        _post_menu(menu, event.x_root, event.y_root, self.win)

    def _trash_and_refresh(self, fpath):
        """Cestina file dal pannello anteprima con conferma."""
        fname = os.path.basename(fpath)
        if not self.sorter._hud_yesno("Cestina",
                f"Spostare nel cestino?\n{fname}",
                yes_label="Cestina", no_label="Annulla",
                parent=self.win):
            return
        dest = move_to_transit(fpath, self.sorter.config)
        if dest:
            append_history({"action": "trashed_transit", "files": [fpath],
                            "dest": dest, "note": "doppioni: menu contestuale"})
            self.win.after(50, lambda p=fpath: self._refresh_current_lb(p))

    def _refresh_current_lb(self, trashed_path=None):
        """Aggiorna listbox e anteprima dopo cestinamento."""
        def _find_lb(widget):
            for child in widget.winfo_children():
                if isinstance(child, tk.Listbox) and hasattr(child, '_refresh_preview'):
                    # Aggiorna la riga del file cestinato
                    if trashed_path:
                        rp = getattr(child, '_row_paths_ref', None)
                        if rp:
                            for i, p in rp.items():
                                if p == trashed_path:
                                    short = os.path.basename(trashed_path)
                                    child.delete(i)
                                    child.insert(i, tk_safe(f"  -- CESTINATO: {short}"))
                                    child.itemconfig(i, fg=MUTED_COLOR, bg=BG_COLOR)
                                    rp[i] = None
                                    break
                    child._refresh_preview()
                    return
                _find_lb(child)
        _find_lb(self.win)

    def _ctx(self, event, lb, row_paths):
        idx = lb.nearest(event.y)
        fpath = row_paths.get(idx)
        lb.selection_clear(0, tk.END)
        lb.selection_set(idx)
        menu = tk.Menu(self.win, tearoff=0,
                       bg=PANEL_COLOR, fg=TEXT_COLOR,
                       activebackground=HIGHLIGHT,
                       activeforeground="white", relief="flat")

        if fpath:
            # Riga file
            menu.add_command(label="Apri file",
                             command=lambda: subprocess.Popen(
                                 ["xdg-open", fpath],
                                 stdout=subprocess.DEVNULL,
                                 stderr=subprocess.DEVNULL))
            menu.add_command(label="Mostra in file manager",
                             command=lambda p=fpath: open_in_filemanager(p))
            menu.add_separator()
            menu.add_command(label="Sposta nel cestino",
                             command=lambda: self._trash_row(idx, fpath, lb, row_paths,
                                 refresh_cb=lb._refresh_preview if hasattr(lb, "_refresh_preview") else None))
        else:
            # Riga header gruppo — raccogli tutti i file del gruppo
            # Un gruppo inizia dalla riga header (None) e prosegue fino alla prossima None
            group_files = []
            i = idx + 1
            while i in row_paths:
                p = row_paths.get(i)
                if p is None:
                    break
                if p:
                    group_files.append(p)
                i += 1
            # Cartelle uniche del gruppo
            folders = list(dict.fromkeys(os.path.dirname(p) for p in group_files))
            if folders:
                def _open_all_folders(fds=folders):
                    for fd in fds:
                        open_in_filemanager(fd)
                menu.add_command(
                    label=f"Apri {len(folders)} cartel{'la' if len(folders)==1 else 'le'} in file manager",
                    command=_open_all_folders)
            else:
                menu.add_command(label="Nessun file nel gruppo", state="disabled")

        _post_menu(menu, event.x_root, event.y_root, self.win)

    def _open_lb(self, lb, row_paths, event=None):
        sel = lb.curselection()
        if not sel:
            return
        fpath = row_paths.get(sel[0])
        if fpath and os.path.isfile(fpath):
            subprocess.Popen(["xdg-open", fpath],
                             stdout=subprocess.DEVNULL,
                             stderr=subprocess.DEVNULL)

    def _trash_row(self, idx, fpath, lb, row_paths, refresh_cb=None):
        if not os.path.isfile(fpath):
            return
        fname = os.path.basename(fpath)
        if not self.sorter._hud_yesno("Cestina", f"Spostare nel cestino?\n{fname}",
                 yes_label="Cestina", no_label="Annulla",
                 parent=self.win):
            return
        dest = move_to_transit(fpath, self.sorter.config)
        if dest:
            append_history({"action": "trashed_transit", "files": [fpath],
                            "dest": dest, "note": "doppioni: menu contestuale"})
            short = os.path.basename(fpath)
            lb.delete(idx)
            lb.insert(idx, tk_safe(f"  -- CESTINATO: {short}"))
            lb.itemconfig(idx, fg=MUTED_COLOR, bg=BG_COLOR)
            lb.selection_set(idx)
            lb.see(idx)
            row_paths[idx] = None
            if refresh_cb: refresh_cb()

    def _bulk_trash_lb(self, lb, row_paths, result_lbl):
        to_trash = [(idx, path) for idx, path in row_paths.items()
                    if path and os.path.isfile(path)]
        # Mantieni solo il primo file di ogni gruppo (idx più basso)
        # I gruppi sono separati da righe header (None)
        # Logica: salta il primo file valido di ogni gruppo
        keep = set()
        in_group = False
        for idx in sorted(row_paths.keys()):
            p = row_paths.get(idx)
            if p is None:
                in_group = False
                continue
            if not in_group:
                keep.add(idx)
                in_group = True

        to_delete = [(idx, p) for idx, p in to_trash if idx not in keep]
        count = len(to_delete)
        n_groups = len(keep)
        if not self.sorter._hud_yesno(
                "Cestina duplicati",
                f"Verranno cestinati TUTTI i {count} duplicati trovati in "
                f"questa ricerca ({n_groups} gruppi), non solo quelli "
                f"eventualmente selezionati.\n"
                f"Per ogni gruppo verrà conservato un solo file (il primo).\n\n"
                f"Procedere?",
                yes_label="Cestina tutti", no_label="Annulla",
                parent=self.win):
            return
        def _do():
            trashed = 0
            for i, (idx, fpath) in enumerate(to_delete):
                dest = move_to_transit(fpath, self.sorter.config)
                if dest:
                    append_history({"action": "trashed_transit",
                                    "files": [fpath], "dest": dest,
                                    "note": "doppioni: mantieni 1"})
                    trashed += 1
                    row_paths[idx] = None
                if i % 5 == 0:
                    self.win.after(0, lambda d=trashed, t=count:
                        result_lbl.config(text=f"{d}/{t}..."))
            _lang = self.sorter.config.get("language","it")
            self.win.after(0, lambda n=trashed:
                result_lbl.config(text=_Tf("Cestinati {n} file.", _lang, n=n)))
        import threading as _thr
        _thr.Thread(target=_do, daemon=True).start()

    # ── Utility ──────────────────────────────────────────────────────────────

    def _hash_file(self, path):
        h = hashlib.sha256()
        with open(path, "rb") as f:
            while chunk := f.read(65536):
                h.update(chunk)
        return h.hexdigest()

    def _partial_hash_file(self, path, size):
        """Hash veloce di pre-filtro: solo i primi e gli ultimi 64KB del
        file (più la dimensione stessa), non l'intero contenuto. Due file
        della stessa dimensione ma con inizio o fine diversi non possono
        essere identici — si scartano qui, prima dell'hash completo che è
        l'unica fase a leggere davvero tutto il file. Decisivo per i file
        grandi (video): la maggior parte di quelli che risultano solo
        "simili per dimensione" vengono scartati leggendo appena ~128KB
        invece dell'intero file."""
        CHUNK = 65536
        h = hashlib.sha256()
        with open(path, "rb") as f:
            h.update(f.read(CHUNK))
            if size > CHUNK * 2:
                f.seek(-CHUNK, os.SEEK_END)
                h.update(f.read(CHUNK))
        h.update(str(size).encode())
        return h.hexdigest()

    def _fmt(self, b):
        for u in ["B","KB","MB","GB"]:
            if b < 1024: return f"{b:.1f} {u}"
            b /= 1024
        return f"{b:.1f} TB"

    def _set_st(self, lbl, msg):
        msg = tk_safe(str(msg))
        self.win.after(0, lambda: lbl.config(text=msg)
                       if self.win.winfo_exists() else None)

    def _set_prog(self, canvas, bar, val, total):
        def _up():
            if not self.win.winfo_exists(): return
            w = canvas.winfo_width() or 1
            canvas.coords(bar, 0, 0, int(w * val / total) if total else 0, 3)
        self.win.after(0, _up)

    def _on_close(self):
        # Avvisa solo se c'è davvero un thread di scansione attivo
        thread = getattr(self, '_thread', None)
        scanning = thread is not None and thread.is_alive()
        if scanning:
            if not self.sorter._hud_yesno(
                    "Scansione in corso",
                    "Interrompere la scansione e chiudere?",
                    yes_label="Interrompi", no_label="Annulla",
                    parent=self.win):
                return
        self._stop = True
        self.win.destroy()

class FolderBrowser:
    """
    Finestra ad albero per navigare le cartelle e caricare immagini.
    Doppio click su una cartella -> carica la prima immagine in ImageSorter.
    """
    def __init__(self, parent, sorter):
        self.sorter          = sorter
        self._thumb_size     = 200
        self._current_folder = None
        self._nav_history     = []   # ultime 3 cartelle navigate
        self._nav_back_stack  = []   # cartelle precedenti per il pulsante Indietro
        self._nav_forward_stack = [] # cartelle per il pulsante Avanti (si popola tornando Indietro)
        self._size_btns      = {}
        self._action_frame   = None
        self._sort_mode      = "name"
        self._sort_btns      = {}
        self._sort_reverse   = False
        self._view_mode      = "grid"   # "grid" | "list"
        self._view_btn       = None
        self._show_hidden    = False    # mostra cartelle nascoste (punto iniziale)
        self._search_results = None     # percorsi relativi trovati, o None
        self._search_root    = None     # cartella da cui e' partita la ricerca
        self._search_thread  = None
        self._selected_files = set()   # file selezionati per operazioni multiple
        self._cell_refs      = {}      # {fpath: cell_frame} per aggiornare stile
        self.win = tk.Toplevel(parent)
        _lang = self.sorter.config.get("language","it")
        self.win.title(f"{T('browse', _lang)}  v{VERSION}")
        self.win.configure(bg=BG_COLOR)
        _saved_geom = self.sorter.config.get("nav_window_geometry")
        self.win.geometry(_saved_geom if _saved_geom else "1100x700")
        self.win.minsize(400, 340)
        self.win.resizable(True, True)
        self.win.protocol("WM_DELETE_WINDOW", self._on_close)
        self.win.bind("<Escape>", lambda e: self._on_close())
        self.win.bind("<Control-z>", lambda e: self.sorter._undo_last())
        self.win.bind("<Control-Z>", lambda e: self.sorter._undo_last())
        hud_apply(self.win)
        # Icona finestra — usa i refs già caricati dalla root
        try:
            if getattr(sorter.root, "_icon_refs_main", []):
                self.win.iconphoto(False, *sorter.root._icon_refs_main)
        except Exception:
            pass
        self._build()
        _lang = self.sorter.config.get("language","it")
        if _lang != "it":
            self.win.after(100, lambda: _translate_widgets(self.win, _lang))
        # Mostra la finestra subito, poi popola l'albero in background.
        self.win.update_idletasks()
        self.win.after(10, self._deferred_init)

    def _deferred_init(self):
        """Popola l'albero dopo che la finestra è già visibile."""
        sorter = self.sorter
        start = (sorter.config.get("last_source", "")
                 or os.path.expanduser("~/Immagini")
                 or os.path.expanduser("~"))
        if not os.path.isdir(start):
            start = os.path.expanduser("~")
        self._populate_root()
        current = sorter._current_file()
        if current and os.path.isfile(current):
            start = os.path.dirname(current)
            self._start_file = current
        else:
            self._start_file = None
        self._expand_to(start)

    def _build(self):
        w = self.win
        w.columnconfigure(0, weight=1)
        w.rowconfigure(0, weight=0)   # nav
        w.rowconfigure(1, weight=0)   # qf_top
        w.rowconfigure(2, weight=0)   # qf (S/M/L, ordina, vista)
        w.rowconfigure(3, weight=1)   # paned
        w.rowconfigure(4, weight=0)   # sel_bar
        w.rowconfigure(5, weight=0)   # action bar


        # Barra percorso (spanning entrambe le colonne)
        nav = tk.Frame(w, bg=PANEL_COLOR)
        nav.grid(row=0, column=0, columnspan=2, sticky="ew")
        nav.columnconfigure(1, weight=1)
        tk.Label(nav, text="Vai a:", font=("TkFixedFont", 8),
                 bg=PANEL_COLOR, fg=MUTED_COLOR).grid(
                 row=0, column=0, padx=(8,4), pady=6)
        self._path_var = tk.StringVar()
        e = tk.Entry(nav, textvariable=self._path_var,
                     font=("TkFixedFont", 8),
                     bg=ACCENT_COLOR, fg=TEXT_COLOR,
                     insertbackground=TEXT_COLOR, relief="flat", bd=4)
        e.grid(row=0, column=1, sticky="ew", padx=4, pady=6)
        e.bind("<Return>", lambda ev=None: self._go_to_path())
        tk.Button(nav, text="Vai →", font=("TkFixedFont", 8),
                  bg=SUCCESS, fg="white", relief="flat",
                  activebackground=HIGHLIGHT,
                  command=self._go_to_path).grid(
                  row=0, column=2, padx=(0,6), pady=6)

        # Riga 1: preferiti + accesso rapido
        qf_top = tk.Frame(w, bg=BG_COLOR)
        qf_top.grid(row=1, column=0, columnspan=2, sticky="ew", padx=6, pady=(4,0))
        self._qf_top_frame = qf_top

        # Pulsante Indietro: torna alla cartella precedente, qualunque sia
        # il modo in cui si è arrivati a quella corrente (click su una
        # cartella nell'albero, doppio click su una cartella nell'elenco
        # corrente, o scorciatoie rapide). Disabilitato quando non c'è
        # una cartella precedente a cui tornare.
        self._back_btn = tk.Button(qf_top, text="< Indietro",
                       font=("TkFixedFont", 8), bg=ACCENT_COLOR,
                       fg=TEXT_COLOR, relief="flat", padx=6,
                       activebackground=HIGHLIGHT, activeforeground="white",
                       state="disabled",
                       command=self._nav_back)
        self._back_btn.pack(side="left", padx=(0,4))

        # Pulsante Avanti: complemento di Indietro. Si popola solo quando
        # si torna Indietro (esattamente come in un browser); navigando
        # verso una cartella qualsiasi diversa, la cronologia avanti viene
        # invalidata (vedi _record_nav_back).
        self._forward_btn = tk.Button(qf_top, text="Avanti >",
                       font=("TkFixedFont", 8), bg=ACCENT_COLOR,
                       fg=TEXT_COLOR, relief="flat", padx=6,
                       activebackground=HIGHLIGHT, activeforeground="white",
                       state="disabled",
                       command=self._nav_forward)
        self._forward_btn.pack(side="left", padx=(0,4))
        self.win.bind("<Alt-Left>",  lambda e: self._nav_back())
        self.win.bind("<Alt-Right>", lambda e: self._nav_forward())
        self.win.bind("<Control-n>", lambda e: self._create_new_folder())
        self.win.bind("<Control-N>", lambda e: self._create_new_folder())

        # Pulsante Nuova cartella: crea una sottocartella dentro quella
        # attualmente aperta, senza dover passare da Impostazioni.
        tk.Button(qf_top, text="+ Nuova cartella",
                       font=("TkFixedFont", 8), bg=ACCENT_COLOR,
                       fg=TEXT_COLOR, relief="flat", padx=6,
                       activebackground=HIGHLIGHT, activeforeground="white",
                       command=self._create_new_folder
                       ).pack(side="left", padx=(0,4))

        # Riga 2: controlli vista
        qf = tk.Frame(w, bg=BG_COLOR)
        qf.grid(row=2, column=0, columnspan=2, sticky="ew", padx=6, pady=(0,2))

        def _add_quick(parent, label, fpath, color=None):
            c = color or ACCENT_COLOR
            b = tk.Button(parent, text=label, font=("TkFixedFont", 8),
                          bg=c, fg=TEXT_COLOR, relief="flat", padx=6,
                          activebackground=HIGHLIGHT, activeforeground="white",
                          command=lambda p=fpath: self._expand_to(p))
            b.pack(side="left", padx=2, pady=2, ipady=2)
            return b

        # Posti fissi
        pics = os.path.expanduser("~/Immagini")
        if not os.path.isdir(pics): pics = os.path.expanduser("~/Pictures")
        vids = os.path.expanduser("~/Video")
        if not os.path.isdir(vids): vids = os.path.expanduser("~/Videos")
        desk = os.path.expanduser("~/Scrivania")
        if not os.path.isdir(desk): desk = os.path.expanduser("~/Desktop")
        docs = os.path.expanduser("~/Documenti")
        if not os.path.isdir(docs): docs = os.path.expanduser("~/Documents")

        for lbl, fp in [("Immagini", pics), ("Video", vids),
                        ("Scrivania", desk), ("Documenti", docs)]:
            if os.path.isdir(fp):
                _add_quick(qf_top, lbl, fp)

        # Dischi montati — aggiunge i bottoni in after() per non bloccare
        def _add_mounts():
            try:
                with open("/proc/mounts") as _mf:
                    mounts = []
                    for _line in _mf:
                        _parts = _line.split()
                        if len(_parts) >= 2:
                            _mp = _parts[1]
                            if _mp.startswith("/media/") or _mp.startswith("/mnt/"):
                                if os.path.isdir(_mp):
                                    mounts.append(_mp)
                def _add_to_ui():
                    # I dischi vengono rilevati in un thread e aggiunti a
                    # cose gia' disegnate: senza un contenitore riservato
                    # finivano in fondo alla riga, dopo il campo filtro.
                    for _mp in mounts:
                        _name = os.path.basename(_mp) or _mp
                        _add_quick(self._mounts_frame, f"[{_name}]", _mp,
                                   color="#1a3a5a")
                self.win.after(0, _add_to_ui)
            except Exception:
                pass
        # Posto riservato ai dischi montati, che arrivano dopo (vedi sopra)
        self._mounts_frame = tk.Frame(qf_top, bg=BG_COLOR)
        self._mounts_frame.pack(side="left")
        threading.Thread(target=_add_mounts, daemon=True).start()

        # Separatore | Cronologia navigazione (ultime 3 cartelle)
