# =============================================================================
# STREAM DECK — IDLE PAGE MANAGER
# =============================================================================

# Schema config pagine idle (salvato in image_sorter_config.json):
# "deck_idle_pages": [
#   [  # pagina 0 — lista di 15 slot (Standard), None = vuoto
#     {"label": "Documenti", "color": [20,60,120],
#      "action": "folder", "param": "/home/carlo/Documenti", "image": null},
#     {"label": "Copia", "color": [80,40,0],
#      "action": "hotkey", "param": "ctrl+c", "image": null},
#     ...
#   ],
#   [ ... ],  # pagina 1
# ]
#
# Tipi di azione:
#   "folder"   param = percorso cartella  -> apre in file manager
#   "app"      param = comando            -> subprocess.Popen
#   "hotkey"   param = "ctrl+c" ecc.     -> xdotool key
#   "url"      param = https://...       -> xdg-open
#   "mute"     param = ""               -> pactl set-sink-mute @DEFAULT_SINK@ toggle
#   "sorter"   param = percorso          -> apre Image Sorter su quella cartella
#   "page"     param = "next"/"prev"     -> cambia pagina idle
#   "command"  param = uno degli id in DECK_COMMANDS -> chiama direttamente
#              un metodo del programma, invece di simulare la tastiera
#   "rating"       param = "1".."5"           -> imposta la valutazione
#                  del file aperto (stessa stella = azzera)
#   "color_label"  param = uno degli id colore -> toggle di quella
#                  colorlabel sul file aperto

def _make_ratings_flags_page():
    """Costruisce la pagina "Rating/Flag" richiesta da Carlo: riga 1 = 5
    colori etichetta (stesso ordine di metadata_store.COLOR_LABELS),
    riga 2 = 5 stelle di valutazione (1..5), riga 3 libera per le
    funzioni normalmente assegnabili. 15 slot, il presupposto (Standard
    3x5) gia' fatto altrove in questo modulo per il deck fisico."""
    page = [None] * 15
    if _METADATA_STORE_AVAILABLE:
        for i, (cid, _cname, _chex) in enumerate(metadata_store.COLOR_LABELS[:5]):
            page[i] = {"label": "", "color": [20, 20, 20],
                      "action": "color_label", "param": cid, "image": None}
    for i in range(5):
        n = i + 1
        page[5 + i] = {"label": "", "color": [20, 20, 20],
                       "action": "rating", "param": str(n), "image": None}
    return page


def _ensure_ratings_flags_deck_page(config):
    """Aggiunge UNA VOLTA SOLA la pagina "Rating/Flag" in fondo alle
    pagine idle del deck, se non l'ha ancora ricevuta — richiesto da
    Carlo: "una nuova pagina, gia' impostata e automaticamente inserita
    alla fine delle varie pagine". Un marcatore in config impedisce di
    riaggiungerla ad ogni avvio (l'utente potrebbe averla spostata,
    modificata o anche cancellata di proposito nel frattempo)."""
    if config.get("deck_ratings_page_added"):
        return
    pages = config.setdefault("deck_idle_pages", [])
    pages.append(_make_ratings_flags_page())
    config["deck_ratings_page_added"] = True
    save_config(config)


# IDLE_ACTION_TYPES / IDLE_ACTION_LABELS vivono ora in deck_core.py
# (importato in testa al file): sono dati puri, senza dipendenze dalla
# finestra, quindi non hanno motivo di stare qui.

def _deck_cmd_convert_jpg(sorter):
    """Converte in JPG il file corrente, solo se il formato lo permette
    (stessa lista di estensioni del menu tasto destro)."""
    fp = sorter._current_file()
    ext = os.path.splitext(fp)[1].lower() if fp else ""
    if fp and ext in {".webp",".png",".bmp",".tiff",".gif",".heic",".heif",
                      ".jpg",".jpeg",".pnm",".pbm",".pgm",".ppm",".avif"}:
        sorter._convert_to_jpg(fp)

def _deck_cmd_copy_path(sorter):
    fp = sorter._current_file()
    if fp:
        sorter._copy_to_clipboard(fp)

def _deck_cmd_open_filemanager(sorter):
    fp = sorter._current_file()
    if fp:
        open_in_filemanager(fp)

def _deck_cmd_copy_gps(sorter):
    """Copia la posizione GPS solo se il file corrente ne ha una — senza
    controllo, un tasto premuto su un file senza GPS solleverebbe un
    errore invece di non fare nulla."""
    fp = sorter._current_file()
    if not fp:
        return
    try:
        from exif_editor import read_gps as _rg
        if _rg(fp):
            sorter._gps_copy_current(fp)
    except Exception:
        pass

def _deck_cmd_show_map(sorter):
    fp = sorter._current_file()
    if not fp:
        return
    try:
        from exif_editor import read_gps as _rg
        if _rg(fp):
            sorter._open_map_single(fp)
    except Exception:
        pass

def _deck_cmd_send_to_editor(sorter):
    """Invia il file corrente al programma di modifica configurato in
    'Modifica con...' (self.config['edit_with']) — SENZA MAI mostrare
    popup, a differenza di 'Modifica con...' stesso: un tasto fisico
    deve dare un'azione immediata e prevedibile ad ogni pressione, non
    aprire una finestra che aspetta altre interazioni. Per questo
    "Modifica con..." di per se' era escluso dai comandi diretti (vedi
    il commento sopra DECK_COMMANDS) — questo comando e' la versione
    silenziosa apposta per il tasto fisico, usa sempre il programma gia'
    salvato, mai quello scelto al volo nel popup."""
    fp = sorter._current_file()
    if not fp:
        return
    editor = sorter.config.get("edit_with", "gimp").strip() or "gimp"
    try:
        subprocess.Popen([editor, fp],
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    except Exception as ex:
        log_error(f"Comando Deck 'Invia a modifica': '{editor}' non "
                 f"avviabile su {fp}\n{ex}", tag="deck_send_to_editor")

def _deck_cmd_open_resize(sorter):
    """Apre il popup di ridimensionamento sul file corrente — a
    differenza degli altri comandi diretti, apre un dialogo invece di
    agire subito (vedi l'eccezione motivata nel commento sopra
    DECK_COMMANDS): il ridimensionamento ha sempre bisogno di un numero
    che il tasto fisico da solo non puo' fornire."""
    fp = sorter._current_file()
    if not fp:
        return
    sorter._open_resize(fp)

# Comandi diretti richiamabili da un tasto idle con action="command". Ogni
# voce e' (id salvato nel config, etichetta mostrata nel menu a tendina
# dell'editor, funzione che riceve il sorter). A differenza di "hotkey"
# chiamano il metodo del programma direttamente: nessun xdotool, nessuna
# dipendenza dal fatto che la finestra di Image Sorter abbia il fuoco in
# quel momento — funzionano anche se in quell'istante e' un'altra
# finestra ad avere il focus.
# Esclusi di proposito: azioni che aprono un dialogo di scelta o una
# finestra di conferma (Ritaglia, Modifica con..., Modifica EXIF) — non
# si prestano a un singolo tasto senza interazione successiva.
# Eccezione deliberata: "Ridimensiona" APRE il popup invece di agire
# subito, perche' ha sempre bisogno di un numero (larghezza/altezza) che
# il tasto fisico da solo non puo' fornire — aprire il popup e' comunque
# piu' utile che escluderlo del tutto, a differenza di Ritaglia (che ha
# un'interazione ben piu' lunga: trascinamento, aspetto, conferma) o di
# Modifica con... (che ha gia' la sua alternativa a un tasto solo, vedi
# "send_to_editor" qui sotto).
# Restano QUI (non in deck_core.py) perche' ogni funzione chiama un
# metodo dell'interfaccia grafica — richiedono per forza un'istanza di
# ImageSorter viva. deck_core.py ha pero' la stessa lista di id ed
# etichette in DECK_COMMAND_IDS, usata per esempio da una futura finestra
# Deck indipendente: il controllo qui sotto si accerta che le due liste
# non divergano mai in silenzio.
DECK_COMMANDS = [
    ("next_file",         "File successivo",                lambda s: s._skip()),
    ("prev_file",         "File precedente",                lambda s: s._go_back()),
    ("rotate_cw",         "Ruota 90 gradi orario",           lambda s: s._rotate_current(90)),
    ("rotate_ccw",        "Ruota 90 gradi antiorario",       lambda s: s._rotate_current(-90)),
    ("delete_current",    "Elimina (doppia pressione)",      lambda s: s._delete_current()),
    ("delete_previous",   "Elimina precedente (Ctrl+Canc)",  lambda s: s._delete_previous()),
    ("undo_last",         "Annulla ultimo spostamento",      lambda s: s._undo_last()),
    ("rename_current",    "Rinomina file corrente",          lambda s: s._open_rename_current()),
    ("convert_jpg",       "Converti in JPG",                 _deck_cmd_convert_jpg),
    ("copy_path",         "Copia percorso file corrente",    _deck_cmd_copy_path),
    ("open_filemanager",  "Apri cartella nel file manager",  _deck_cmd_open_filemanager),
    ("copy_gps",          "Copia posizione GPS",             _deck_cmd_copy_gps),
    ("show_map",          "Mostra posizione su mappa",       _deck_cmd_show_map),
    ("zoom_fit",          "Adatta al canvas",                lambda s: s._zoom_fit()),
    ("zoom_original",     "Dimensione originale",            lambda s: s._zoom_original()),
    ("zoom_in",           "Zoom avanti",                     lambda s: s._zoom(1.25)),
    ("zoom_out",          "Zoom indietro",                   lambda s: s._zoom(0.80)),
    ("toggle_info",       "Mostra/nascondi info EXIF",       lambda s: s._toggle_info()),
    ("toggle_header",     "Mostra/nascondi intestazione",    lambda s: s._toggle_header()),
    ("toggle_fullscreen", "Schermo intero",                  lambda s: s._toggle_fullscreen()),
    ("toggle_sidebar",    "Mostra/nascondi sidebar",         lambda s: s._toggle_sidebar()),
    ("toggle_keypad",     "Apri/chiudi il deck software",    lambda s: s._toggle_keypad()),
    ("toggle_browser",    "Apri/chiudi il browser cartelle", lambda s: s._toggle_browser()),
    ("open_new_source",   "Scegli nuova cartella",           lambda s: s._open_new_source()),
    ("open_timeline",     "Apri/chiudi Timeline",            lambda s: s._open_timeline()),
    ("open_history",      "Apri/chiudi storico operazioni",  lambda s: s._open_history()),
    ("open_settings",     "Apri/chiudi impostazioni",        lambda s: s._open_settings()),
    ("next_preset",       "Preset successivo",               lambda s: s._next_preset()),
    ("prev_preset",       "Preset precedente",               lambda s: s._prev_preset()),
    ("send_to_editor",    "Invia a modifica (programma configurato)", _deck_cmd_send_to_editor),
    ("open_resize",       "Ridimensiona... (apre il popup)", _deck_cmd_open_resize),
]
DECK_COMMAND_LABELS = {cid: lbl for cid, lbl, _fn in DECK_COMMANDS}
DECK_COMMAND_FUNCS  = {cid: fn for cid, _lbl, fn in DECK_COMMANDS}

# Controllo di coerenza fra questa lista e quella "gemella" in
# deck_core.py: se in futuro si modifica una delle due dimenticando
# l'altra, questo lo fa notare subito all'avvio invece di lasciare un
# comando fantasma nella finestra Deck indipendente o in questa.
if DECK_COMMAND_LABELS != deck_core.DECK_COMMAND_LABELS:
    print("[StreamDeck] ATTENZIONE: DECK_COMMANDS (image_sorter.py) e "
          "DECK_COMMAND_IDS (deck_core.py) non coincidono piu' — "
          "controllare che le due liste siano allineate.")


def _deck_execute_action(action_dict, sorter=None):
    """Esegue l'azione di un tasto del deck fisico. Chiamata nel thread
    principale — anche quando l'azione arriva dalla casella di
    instradamento (send_to_inbox/poll_inbox), non solo da una pressione
    diretta: e' lo stesso identico dizionario in entrambi i casi.

    Gestisce qui "command"/"sorter" (modalita' idle) e le cinque azioni
    "preset_*" (modalita' preset — smistamento: prima erano chiamate
    dirette a un metodo, ora sono anche loro dizionari, cosi' possono
    attraversare la casella di un'altra istanza). Tutte richiedono
    un'istanza grafica viva. Il resto delle azioni idle — che non
    toccano mai l'interfaccia — e' delegato a
    deck_core.execute_headless_action(), che le sa eseguire anche senza
    nessuna finestra aperta: e' la stessa funzione che usera' un domani
    un eventuale processo in background, senza doverle riscrivere qui.
    """
    if not action_dict or not sorter:
        if action_dict and action_dict.get("action") not in (
                "command", "sorter", "preset_key", "preset_nav",
                "preset_delete", "preset_prev", "preset_next"):
            deck_core.execute_headless_action(action_dict, sorter)
        return
    kind = action_dict.get("action", "")
    if kind == "preset_key":
        sorter.root.after(0, lambda k=action_dict.get("param",""):
                          sorter._move_to(k))
        return
    if kind == "preset_nav":
        if action_dict.get("param") == "left":
            sorter.root.after(0, sorter._go_back)
        else:
            sorter.root.after(0, sorter._skip)
        return
    if kind == "preset_delete":
        sorter.root.after(0, sorter._delete_current)
        return
    if kind == "preset_prev":
        sorter.root.after(0, lambda: sorter._cycle_preset(-1))
        return
    if kind == "preset_next":
        sorter.root.after(0, lambda: sorter._cycle_preset(1))
        return
    if kind == "sorter":
        param = action_dict.get("param", "")
        try:
            sorter.root.after(0, lambda: sorter._load_source(param))
        except Exception:
            pass
        return
    if kind == "command":
        fn = DECK_COMMAND_FUNCS.get(action_dict.get("param", ""))
        if fn:
            try:
                fn(sorter)
            except Exception:
                pass
        return
    if kind == "rating":
        # Tasto "stella" della pagina Rating/Flag: stessa stella gia' al
        # valore corrente azzera, altrimenti imposta il valore del tasto
        # — identico principio di toggle di _set_overlay_rating(), qui
        # applicato al file attualmente aperto invece che a uno passato
        # esplicitamente (il tasto fisico non "sa" quale file, agisce
        # sempre su quello che si sta guardando in questo momento).
        if _METADATA_STORE_AVAILABLE:
            fp = sorter._current_file()
            try:
                n = int(action_dict.get("param", ""))
            except (TypeError, ValueError):
                n = None
            if fp and n is not None:
                cur = metadata_store.get_meta(fp)["rating"]
                metadata_store.set_rating(fp, 0 if cur == n else n)
                sorter._draw_rating_overlay(fp)
                if getattr(sorter, "_stream_deck", None):
                    sorter._stream_deck.refresh_all()
        return
    if kind == "color_label":
        # Tasto "colore" della pagina Rating/Flag: stesso toggle di
        # _toggle_overlay_color(), sul file attualmente aperto.
        if _METADATA_STORE_AVAILABLE:
            fp = sorter._current_file()
            param = action_dict.get("param", "")
            if fp and param:
                metadata_store.toggle_color(fp, param)
                sorter._draw_rating_overlay(fp)
                if getattr(sorter, "_stream_deck", None):
                    sorter._stream_deck.refresh_all()
        return
    deck_core.execute_headless_action(action_dict, sorter)



# StreamDeckManager e' stata spostata in deck_core.py: gestisce il
# dispositivo fisico senza bisogno di questa finestra, cosi' domani un
# processo separato (demone) potra' importarla e tenere vivo il deck
# anche a Image Sorter chiuso. Importata sopra, insieme al resto di
# quel modulo (vedi "import deck_core" in testa al file).


# =============================================================================
# FINESTRA IMPOSTAZIONI (tab Preset + tab Destinazioni)
# =============================================================================

class SettingsDialog:
    """Finestra impostazioni unificata con due tab:
    - Preset: gestione e selezione preset (ex PresetSelector)
    - Destinazioni: configurazione cartelle per tasto (ex FolderConfigDialog)
    """
    def __init__(self, parent, sorter, initial_tab="preset", history_only=False):
        """history_only: apre la sola finestra Storico, senza le schede.

        Lo Storico non e' un'impostazione: e' un registro di operazioni che
        si consulta mentre si lavora. Tenerlo dentro le Impostazioni
        obbligava ad aprire una finestra di configurazione per annullare
        uno spostamento. La finestra e' la stessa, costruita dallo stesso
        codice, ma senza barra delle schede e con un titolo proprio.
        """
        self.sorter = sorter
        self.config = sorter.config
        self.result = None   # preset selezionato (per compatibilità)
        self.history_only = history_only

        self.win = tk.Toplevel(parent)
        self.win.withdraw()   # nasconde finché non è posizionata
        _cfg_lang = self.config.get("language","it")
        self.win.title((f"{T('tab_history', _cfg_lang).strip()}  v{VERSION}"
                        if history_only else
                        f"{T('settings', _cfg_lang)}  v{VERSION}"))
        self.win.configure(bg=BG_COLOR)
        self.win.minsize(600, 480)
        self.win.resizable(True, True)
        self.win.transient(parent)
        hud_apply(self.win)
        self._build("history" if history_only else initial_tab)
        # SettingsDialog usa T() per tutti i testi — non serve _translate_widgets
        # Posiziona nel terzo sinistro dello schermo senza flash
        self.win.update_idletasks()
        sw = self.win.winfo_screenwidth()
        sh = self.win.winfo_screenheight()
        ww = min(780, sw * 2 // 5)
        wh = min(640, sh - 80)
        wx = sw // 5 - ww // 2   # circa 1/5 da sinistra
        wx = max(20, wx)
        wy = (sh - wh) // 2
        self.win.geometry(f"{ww}x{wh}+{wx}+{wy}")
        self.win.deiconify()
        self.win.bind("<Return>", lambda e: self._on_enter())
        self.win.bind("<Escape>", lambda e: self._on_close_request())
        self.win.protocol("WM_DELETE_WINDOW", self._on_close_request)

    def _on_enter(self):
        tab = self._current_tab.get() if hasattr(self, '_current_tab') else "preset"
        if tab == "preset":
            self._confirm_preset()
        elif tab == "dest":
            self._apply_dest()
        else:
            pass   # tab visualizza: le checkbox si applicano in tempo reale

    def _dest_has_unsaved_changes(self):
        """True se il tab Destinazioni ha modifiche non ancora salvate."""
        if self._current_tab.get() != "dest":
            return False
        if not hasattr(self, 'label_vars') or not hasattr(self, 'path_vars'):
            return False
        try:
            preset_name = self._dest_preset_var.get()
            saved = self.config["presets"].get(preset_name, {})
            for k in KEYS:
                saved_slot  = saved.get(k, {})
                cur_label   = self.label_vars[k].get().strip()
                cur_path    = self.path_vars[k].get().strip()
                saved_label = saved_slot.get("label", "").strip()
                saved_path  = saved_slot.get("path",  "").strip()
                if cur_label != saved_label or cur_path != saved_path:
                    return True
        except Exception:
            pass
        return False

    def _on_close_request(self, e=None):
        """Chiude la finestra, chiedendo conferma se ci sono modifiche non salvate."""
        if self._dest_has_unsaved_changes():
            answer = self._hud_yesno(
                "Modifiche non salvate",
                "Il tab Destinazioni ha modifiche non ancora salvate.\n\n"
                "Salvare prima di chiudere?",
                yes_label="Salva", no_label="Ignora",
                parent=self.win)
            if answer is None:      # Annulla → rimani
                return
            if answer:              # Sì → salva e chiudi
                self._apply_dest()
        self.win.destroy()

    def _hud_alert(self, title, message, btn_label="OK", parent=None,
                   auto_close_ms=None):
        """Delega a ImageSorter._hud_alert."""
        self.sorter._hud_alert(title, message, btn_label, parent or self.win,
                               auto_close_ms=auto_close_ms)

    def _hud_yesno(self, title, message, yes_label="Si", no_label="No", parent=None):
        """Delega a ImageSorter._hud_yesno."""
        return self.sorter._hud_yesno(title, message, yes_label, no_label,
                                      parent or self.win)

    def _build(self, initial_tab):
        w = self.win
        w.columnconfigure(0, weight=1)
        w.rowconfigure(1, weight=1)
        w.rowconfigure(2, weight=0)

        # --- Tab bar in cima ---
        tab_bar = tk.Frame(w, bg=PANEL_COLOR)
        if not getattr(self, "history_only", False):
            tab_bar.grid(row=0, column=0, sticky="ew")
        self._tab_btns = {}
        self._current_tab = tk.StringVar(value=initial_tab)

        cfg_lang = self.config.get("language", "it")
        # Lo Storico ha ora una finestra propria: non compare piu' fra le
        # schede delle Impostazioni.
        _tabs = ([] if getattr(self, "history_only", False) else [
            ("preset",   T("tab_preset",   cfg_lang)),
            ("dest",     T("tab_dest",     cfg_lang)),
            ("view",     T("tab_view",     cfg_lang)),
            ("tags",     T("tab_tags",     cfg_lang)),
            ("keys",     T("tab_keys",     cfg_lang)),
            ("deck",     T("tab_deck",     cfg_lang)),
            ("info",     T("tab_info",     cfg_lang)),
        ])
        for key, label in _tabs:
            btn = tk.Button(tab_bar, text=label,
                            font=("TkFixedFont", 10),
                            relief="flat", bd=0, padx=4, pady=8,
                            activebackground=BG_COLOR, activeforeground=HIGHLIGHT,
                            command=lambda k=key: self._switch_tab(k))
            btn.pack(side="left")
            self._tab_btns[key] = btn

        # --- Area contenuto ---
        self._content = tk.Frame(w, bg=BG_COLOR)
        self._content.grid(row=1, column=0, sticky="nsew")
        self._content.columnconfigure(0, weight=1)
        self._content.rowconfigure(0, weight=0)

        # --- Barra fondo: area sinistra contestuale + Chiudi a destra ---
        bot = tk.Frame(w, bg=PANEL_COLOR)
        bot.grid(row=2, column=0, sticky="ew")
        # Frame sinistro per bottoni del tab corrente (aggiornato da _switch_tab)
        self._bot_left = tk.Frame(bot, bg=PANEL_COLOR)
        self._bot_left.pack(side="left", fill="y")
        tk.Button(bot, text=T("close", cfg_lang),
                  font=("TkFixedFont", 9),
                  bg=ACCENT_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=16,
                  command=self._on_close_request
                  ).pack(side="right", padx=10, pady=6, ipady=3)

        self._switch_tab(initial_tab)

    def _switch_tab(self, key):
        # Avvisa se si cambia tab con modifiche Destinazioni non salvate
        if key != "dest" and self._dest_has_unsaved_changes():
            answer = self._hud_yesno(
                "Modifiche non salvate",
                "Il tab Destinazioni ha modifiche non ancora salvate.\n\n"
                "Salvare prima di cambiare tab?",
                parent=self.win)
            if answer:
                self._apply_dest()
        self._current_tab.set(key)
        # Aggiorna stile bottoni tab — SOLO colore, mai il peso del font:
        # cambiare normale/grassetto in un font monospazio come TkFixedFont
        # cambia comunque la larghezza richiesta dal bottone, e con
        # pack(side="left") questo fa "saltare" tutte le linguette ad ogni
        # cambio tab (ognuna si allarga/restringe e si stacca dalle altre).
        for k, btn in self._tab_btns.items():
            if k == key:
                btn.config(bg=BG_COLOR, fg=HIGHLIGHT)
            else:
                btn.config(bg=PANEL_COLOR, fg=MUTED_COLOR)
        # Nasconde temporaneamente l'area di contenuto durante la
        # ricostruzione (grid_remove, non destroy) — evita che l'utente
        # veda i passaggi intermedi del layout (widget vecchi distrutti,
        # nuovi aggiunti uno alla volta, pesi riga ricalcolati) come un
        # doppio movimento. Tutto appare in un solo aggiornamento visivo.
        self._content.grid_remove()
        if hasattr(self, '_bot_left'):
            self._bot_left.pack_forget()
        # Svuota e ricostruisce contenuto — resetta anche i rowconfigure
        for child in self._content.winfo_children():
            child.destroy()
        # Pulisci bottoni contestuali nella barra fondo
        if hasattr(self, '_bot_left'):
            for child in self._bot_left.winfo_children():
                child.destroy()
        # Resetta weight righe per evitare layout residui dai tab precedenti
        for i in range(10):
            self._content.rowconfigure(i, weight=0)
        self._content.rowconfigure(0, weight=0)
        if key == "preset":
            self._build_preset_tab()
        elif key == "dest":
            self._build_dest_tab()
        elif key == "view":
            self._build_view_tab()
        elif key == "tags":
            self._build_tags_tab()
        elif key == "keys":
            self._build_keys_tab()
        elif key == "deck":
            self._build_deck_tab()
        elif key == "private":
            self._build_private_tab()
        elif key == "info":
            self._build_info_tab()
        elif key == "history":
            self._build_history_tab()
        # Ripristina contenuto e barra bottoni ora che sono pronti
        self._content.grid()
        if hasattr(self, '_bot_left'):
            self._bot_left.pack(side="left", fill="y")
        # Traduzione dopo ogni ricostruzione tab
        _lang = self.config.get("language","it")
        if _lang != "it":
            self.win.after(50, lambda: _translate_widgets(self.win, _lang))

    # ------------------------------------------------------------------
    # TAB PRESET
    # ------------------------------------------------------------------
    def _build_preset_tab(self):
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)

        _cfg_lang2 = self.config.get("language","it")
        tk.Label(f, text=T("preset_hint", _cfg_lang2),
                 font=("TkFixedFont", 7), bg=BG_COLOR, fg=MUTED_COLOR,
                 justify="left").grid(row=0, column=0, sticky="w",
                                      padx=20, pady=(8, 2))

        # Lista + frecce
        list_outer = tk.Frame(f, bg=BG_COLOR)
        list_outer.grid(row=1, column=0, sticky="nsew", padx=20, pady=4)
        list_outer.rowconfigure(0, weight=1)
        list_outer.columnconfigure(0, weight=1)

        lf = tk.Frame(list_outer, bg=ACCENT_COLOR)
        lf.grid(row=0, column=0, sticky="nsew")
        lf.rowconfigure(0, weight=1)
        lf.columnconfigure(0, weight=1)
        sb = tk.Scrollbar(lf, orient="vertical", bg=ACCENT_COLOR, troughcolor=BG_COLOR)
        sb.grid(row=0, column=1, sticky="ns")
        self.listbox = tk.Listbox(lf, font=("TkFixedFont", 11),
                                  bg=PANEL_COLOR, fg=TEXT_COLOR,
                                  selectbackground=HIGHLIGHT, selectforeground="white",
                                  activestyle="none", relief="flat", bd=0,
                                  width=28,
                                  yscrollcommand=sb.set, exportselection=False)
        self.listbox.grid(row=0, column=0, sticky="nsew")
        sb.config(command=self.listbox.yview)
        self.listbox.bind("<Button-4>", lambda e: self.listbox.yview_scroll(-1, "units"))
        self.listbox.bind("<Button-5>", lambda e: self.listbox.yview_scroll(1, "units"))
        self.listbox.bind("<MouseWheel>", lambda e: self.listbox.yview_scroll(-1 if e.delta > 0 else 1, "units"))
        self.listbox.bind("<Double-Button-1>", lambda e: self._confirm_preset())
        self.listbox.bind("<<ListboxSelect>>", lambda e: self._update_preview())

        arrows = tk.Frame(list_outer, bg=BG_COLOR)
        arrows.grid(row=0, column=1, sticky="ns", padx=(4, 0))
        _ico_arr_up = make_icon("up", size=16, fg=(0,200,255), bg=(20,28,48))
        tk.Button(arrows, image=_ico_arr_up, text="", compound="none",
                  bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat",
                  activebackground=HIGHLIGHT, activeforeground="white",
                  command=self._move_up).pack(fill="x", pady=(0, 3), ipady=4)
        _ico_arr_dn = make_icon("down", size=16, fg=(0,200,255), bg=(20,28,48))
        tk.Button(arrows, image=_ico_arr_dn, text="", compound="none",
                  bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat",
                  activebackground=HIGHLIGHT, activeforeground="white",
                  command=self._move_down).pack(fill="x", ipady=4)

        # Anteprima cartelle
        pf = tk.Frame(f, bg=BG_COLOR)
        pf.grid(row=2, column=0, sticky="ew", padx=20, pady=(4, 2))
        tk.Label(pf, text="Cartelle:", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).pack(side="left")
        self.preview_label = tk.Label(pf, text="", font=("TkFixedFont", 8),
                                      bg=BG_COLOR, fg=TEXT_COLOR,
                                      anchor="w", wraplength=440, justify="left")
        self.preview_label.pack(side="left", padx=6, fill="x", expand=True)

        self._refresh_list()

        # Azioni preset
        af = tk.Frame(f, bg=BG_COLOR)
        af.grid(row=3, column=0, sticky="ew", padx=20, pady=4)
        for txt, cmd, col in [
            ("+ Nuovo",  self._new_preset,    SUCCESS),
            ("Copia",    self._copy_preset,   "#4a90e2"),
            ("Rinomina", self._rename_preset, WARNING),
            ("Elimina",  self._delete_preset, "#c0392b"),
        ]:
            tk.Button(af, text=txt, font=("TkFixedFont", 8),
                      bg=col, fg="white", relief="flat", padx=6,
                      activebackground=HIGHLIGHT, activeforeground="white",
                      command=cmd).pack(side="left", padx=3, pady=4,
                                        fill="x", expand=True)

        # --- Separatore ---
        tk.Frame(f, bg=ACCENT_COLOR, height=1).grid(
            row=4, column=0, sticky="ew", padx=20, pady=(8,4))

        # Sezione Tastierino + Sidebar affiancati
        bottom_f = tk.Frame(f, bg=BG_COLOR)
        bottom_f.grid(row=5, column=0, sticky="ew", padx=20, pady=(0,4))
        bottom_f.columnconfigure(0, weight=1)
        bottom_f.columnconfigure(1, weight=0, minsize=8)
        bottom_f.columnconfigure(2, weight=1)

        # --- Tastierino ---
        kf = tk.Frame(bottom_f, bg=PANEL_COLOR,
                      highlightbackground=HUD_DIM, highlightthickness=1)
        kf.grid(row=0, column=0, sticky="nsew", padx=(0,4), pady=2)
        tk.Label(kf, text="Deck", font=("TkFixedFont", 9, "bold"),
                 bg=PANEL_COLOR, fg=WARNING).pack(anchor="w", padx=8, pady=(6,2))
        tk.Frame(kf, bg=ACCENT_COLOR, height=1).pack(fill="x", padx=4, pady=(0,4))
        cols_row = tk.Frame(kf, bg=PANEL_COLOR)
        cols_row.pack(fill="x", padx=8, pady=(0,8))
        tk.Label(cols_row, text="Colonne (3+):", font=("TkFixedFont", 8),
                 bg=PANEL_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(0,6))
        self._col_btns = {}
        for n in range(3, 9):   # 1 e 2 col gestite dal ciclo tasto Deck
            b = tk.Button(cols_row, text=str(n),
                          font=("TkFixedFont", 9, "bold"),
                          relief="flat", bd=0, width=2,
                          activebackground=HUD_CYAN, activeforeground="#0a1a2e",
                          command=lambda v=n: self._set_keypad_cols(v))
            b.pack(side="left", padx=1, ipady=3)
            self._col_btns[n] = b
        self._refresh_col_btns()

        # --- Sidebar ---
        sf = tk.Frame(bottom_f, bg=PANEL_COLOR,
                      highlightbackground=HUD_DIM, highlightthickness=1)
        sf.grid(row=0, column=2, sticky="nsew", padx=(4,0), pady=2)
        tk.Label(sf, text="Sidebar", font=("TkFixedFont", 9, "bold"),
                 bg=PANEL_COLOR, fg=WARNING).pack(anchor="w", padx=8, pady=(6,2))
        tk.Frame(sf, bg=ACCENT_COLOR, height=1).pack(fill="x", padx=4, pady=(0,4))

        np_row = tk.Frame(sf, bg=PANEL_COLOR)
        np_row.pack(fill="x", padx=8, pady=(0,4))
        tk.Label(np_row, text="Preset:", font=("TkFixedFont", 8),
                 bg=PANEL_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(0,6))
        self._sb_preset_btns = {}
        for n in (1, 2, 3):
            b = tk.Button(np_row, text=str(n),
                          font=("TkFixedFont", 9, "bold"),
                          relief="flat", bd=0, width=3, padx=4,
                          activebackground=HUD_CYAN, activeforeground="#0a1a2e",
                          command=lambda v=n: self._set_sidebar_presets(v))
            b.pack(side="left", padx=2, ipady=3)
            self._sb_preset_btns[n] = b
        self._refresh_sb_preset_btns()

        mode_row = tk.Frame(sf, bg=PANEL_COLOR)
        mode_row.pack(fill="x", padx=8, pady=(0,8))
        tk.Label(mode_row, text="Modalita:", font=("TkFixedFont", 8),
                 bg=PANEL_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(0,4))
        self._sidebar_mode_var = tk.StringVar(value=get_sidebar_mode(self.config))
        for val, label in [("inline","Fissa"), ("popup","Finestra"), ("hidden","Off")]:
            tk.Radiobutton(mode_row, text=label,
                           variable=self._sidebar_mode_var, value=val,
                           font=("TkFixedFont", 8),
                           bg=PANEL_COLOR, fg=TEXT_COLOR,
                           selectcolor=ACCENT_COLOR,
                           activebackground=PANEL_COLOR, activeforeground=HUD_CYAN,
                           command=self._apply_sidebar_settings
                           ).pack(side="left", padx=4)

        # Aspetto: griglia storica (numero + nome affiancati, 3 colonne per
        # preset) oppure elenco verticale (un tasto per riga, dal 9 in alto
        # allo 0 in basso, etichetta a tutta larghezza). L'elenco lascia
        # molto piu' spazio al nome della cartella, che nella griglia
        # risultava meno leggibile del numero colorato.
        layout_row = tk.Frame(sf, bg=PANEL_COLOR)
        layout_row.pack(fill="x", padx=8, pady=(0,8))
        tk.Label(layout_row, text="Aspetto:", font=("TkFixedFont", 8),
                 bg=PANEL_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(0,4))
        self._sidebar_layout_var = tk.StringVar(value=get_sidebar_layout(self.config))
        for val, label in [("grid","Griglia"), ("list","Elenco")]:
            tk.Radiobutton(layout_row, text=label,
                           variable=self._sidebar_layout_var, value=val,
                           font=("TkFixedFont", 8),
                           bg=PANEL_COLOR, fg=TEXT_COLOR,
                           selectcolor=ACCENT_COLOR,
                           activebackground=PANEL_COLOR, activeforeground=HUD_CYAN,
                           command=self._apply_sidebar_layout
                           ).pack(side="left", padx=4)

        # Bottone nella barra fondo a sinistra
        tk.Button(self._bot_left, text="  USA QUESTO PRESET  ",
                  font=("TkFixedFont", 9, "bold"),
                  bg=HIGHLIGHT, fg="white", relief="flat",
                  activebackground="#c73652",
                  command=self._confirm_preset
                  ).pack(side="left", padx=10, pady=6, ipady=3)
    # --- helpers tab preset ---
    def _refresh_list(self, select_name=None):
        self.listbox.delete(0, tk.END)
        presets = list(self.config["presets"].keys())
        active  = self.config.get("active_preset", "")
        for i, name in enumerate(presets):
            star = "* " if name == active else "  "
            self.listbox.insert(tk.END, f"  {star}  {name}")
            color = (PRESET_COLORS[i] if i < len(PRESET_COLORS)
                     else TEXT_COLOR)
            self.listbox.itemconfig(i, fg=color)
        target = select_name or active
        idx = presets.index(target) if target in presets else 0
        if presets:
            self.listbox.selection_set(idx)
            self.listbox.see(idx)
        self._update_preview()

    def _selected_name(self):
        sel = self.listbox.curselection()
        if not sel:
            return None
        presets = list(self.config["presets"].keys())
        return presets[sel[0]] if sel[0] < len(presets) else None

    def _update_preview(self):
        name = self._selected_name()
        if not name:
            self.preview_label.config(text="")
            return
        slots = self.config["presets"][name]
        parts = [f"{k}:{slots[k].get('label',k)}" for k in KEYS]
        self.preview_label.config(text="  ".join(parts))

    def _confirm_preset(self):
        name = self._selected_name()
        if not name:
            return
        self.config["active_preset"] = name
        save_config(self.config)
        self.sorter.labels = self.config["presets"][name]
        errors = []
        for k in KEYS:
            try:
                os.makedirs(self.sorter._dest_path(k), exist_ok=True)
            except PermissionError as ex:
                errors.append(str(ex))
        if errors:
            self.sorter._show_toast(
                f"Permesso negato su {len(errors)} cartelle",
                color="#e74c3c", duration=3000)
        self.sorter._update_preset_label()
        self.sorter._build_sidebar()
        if self.sorter.keypad_popup:
            cols = get_keypad_cols(self.config)
            self.sorter._reopen_keypad(cols)
        self.win.destroy()

    def _move_up(self):
        name = self._selected_name()
        if not name:
            return
        presets = list(self.config["presets"].keys())
        idx = presets.index(name)
        if idx == 0:
            return
        presets.insert(idx-1, presets.pop(idx))
        self.config["presets"] = {k: self.config["presets"][k] for k in presets}
        save_config(self.config)
        self._refresh_list(select_name=name)
        self.sorter._build_sidebar()
        # Il Deck aggiornerà l'ordine alla prossima apertura

    def _move_down(self):
        name = self._selected_name()
        if not name:
            return
        presets = list(self.config["presets"].keys())
        idx = presets.index(name)
        if idx >= len(presets)-1:
            return
        presets.insert(idx+1, presets.pop(idx))
        self.config["presets"] = {k: self.config["presets"][k] for k in presets}
        save_config(self.config)
        self._refresh_list(select_name=name)
        self.sorter._build_sidebar()
        # Il Deck aggiornerà l'ordine alla prossima apertura

    def _new_preset(self):
        name = self.sorter._hud_prompt("Nuovo preset", "Nome:",
                                       ok_label="Crea", parent=self.win)
        if not name:
            return
        name = sanitize_name(name)
        if not name or name in self.config["presets"]:
            self._hud_alert("Nome non valido", f"'{name}' non valido o gia' esistente.", parent=self.win)
            return
        self.config["presets"][name] = default_preset()
        save_config(self.config)
        self._refresh_list(select_name=name)

    def _copy_preset(self):
        src = self._selected_name()
        if not src:
            return
        name = self.sorter._hud_prompt(
            "Copia preset", f"Nome della copia di '{src}':",
            initial=f"{src} copia", ok_label="Copia", parent=self.win)
        if not name:
            return
        name = sanitize_name(name)
        if not name or name in self.config["presets"]:
            self._hud_alert("Nome non valido", f"'{name}' non valido.", parent=self.win)
            return
        self.config["presets"][name] = copy.deepcopy(self.config["presets"][src])
        save_config(self.config)
        self._refresh_list(select_name=name)

    def _rename_preset(self):
        old = self._selected_name()
        if not old:
            return
        new = self.sorter._hud_prompt(
            "Rinomina", f"Nuovo nome per '{old}':",
            initial=old, ok_label="Rinomina", parent=self.win)
        if not new or new == old:
            return
        new = sanitize_name(new)
        if not new or new in self.config["presets"]:
            self._hud_alert("Nome non valido", f"'{new}' non valido.", parent=self.win)
            return
        self.config["presets"][new] = self.config["presets"].pop(old)
        if self.config.get("active_preset") == old:
            self.config["active_preset"] = new
        save_config(self.config)
        self._refresh_list(select_name=new)

    def _delete_preset(self):
        name = self._selected_name()
        if not name:
            return
        if len(self.config["presets"]) <= 1:
            self._hud_alert("Impossibile", "Deve esistere almeno un preset.", parent=self.win)
            return
        if not self._hud_yesno("Elimina preset",
                f"Eliminare il preset '{name}'?\n"
                "(Le cartelle su disco NON vengono toccate.)",
                yes_label="Elimina", no_label="Annulla", parent=self.win):
            return
        del self.config["presets"][name]
        if self.config.get("active_preset") == name:
            self.config["active_preset"] = next(iter(self.config["presets"]))
        save_config(self.config)
        self._refresh_list()

    def _set_keypad_cols(self, n):
        self.config["keypad_cols"] = n
        self.config["keypad_cols_configured"] = n   # valore utente, non sovrascritto dal ciclo
        save_config(self.config)
        self._refresh_col_btns()
        if self.sorter.keypad_popup:
            self.sorter._reopen_keypad(n)

    def _refresh_col_btns(self):
        n = get_keypad_cols(self.config)
        for v, b in self._col_btns.items():
            b.config(bg=HIGHLIGHT if v == n else ACCENT_COLOR, fg="white")

    # ------------------------------------------------------------------
    # TAB DESTINAZIONI (ex FolderConfigDialog)
    # ------------------------------------------------------------------
    def _apply_sidebar_settings(self):
        mode = self._sidebar_mode_var.get()
        self.config["sidebar_mode"] = mode
        save_config(self.config)
        self.sorter._apply_sidebar_mode()

    def _apply_sidebar_layout(self):
        self.config["sidebar_layout"] = self._sidebar_layout_var.get()
        save_config(self.config)
        # _build_sidebar() aggiorna gia' da sola anche la finestra separata
        # quando la modalita' e' "popup" (vedi li' per il perche'): non
        # serve piu' controllare la modalita' qui.
        self.sorter._build_sidebar()

    def _set_sidebar_presets(self, n):
        self.config["sidebar_presets"] = n
        save_config(self.config)
        self._refresh_sb_preset_btns()
        # Aggiorna sidebar attiva
        mode = get_sidebar_mode(self.config)
        if mode == "inline":
            self.sorter._build_sidebar()
        elif mode == "popup" and self.sorter.sidebar_popup:
            self.sorter.sidebar_popup.refresh()

    def _refresh_sb_preset_btns(self):
        n = get_sidebar_presets(self.config)
        for v, b in self._sb_preset_btns.items():
            b.config(bg=HUD_CYAN if v == n else ACCENT_COLOR,
                     fg="#0a1a2e" if v == n else TEXT_COLOR)

    def _build_dest_tab(self):
        self.slots = copy.deepcopy(self.sorter.labels)
        self.label_vars = {}
        self.path_vars  = {}
        self.mode_vars  = {}

        f = self._content
        f.rowconfigure(0, weight=0)   # header preset
        f.rowconfigure(1, weight=1)   # scroll area tasti (si espande)
        f.rowconfigure(2, weight=0)   # bottoni
        f.columnconfigure(0, weight=1)

        # Selettore preset + label descrittiva in un unico header compatto
        hdr = tk.Frame(f, bg=PANEL_COLOR)
        hdr.grid(row=0, column=0, columnspan=2, sticky="ew", padx=0, pady=0)
        hdr.columnconfigure(1, weight=1)
        tk.Label(hdr, text="  Preset:",
                 font=("TkFixedFont", 9, "bold"),
                 bg=PANEL_COLOR, fg=WARNING).grid(row=0, column=0, padx=(8,6), pady=6)
        self._dest_preset_var = tk.StringVar(value=self.config["active_preset"])
        preset_names = list(self.config["presets"].keys())
        om = tk.OptionMenu(hdr, self._dest_preset_var, *preset_names,
                           command=lambda _: self._reload_dest_preset())
        om.config(font=("TkFixedFont", 12, "bold"), bg=ACCENT_COLOR, fg=HUD_CYAN,
                  activebackground=HIGHLIGHT, activeforeground="white",
                  highlightthickness=0, relief="flat", bd=0, padx=10)
        om["menu"].config(font=("TkFixedFont", 11), bg=PANEL_COLOR, fg=TEXT_COLOR,
                          activebackground=HIGHLIGHT, activeforeground="white")
        om.grid(row=0, column=1, sticky="w", padx=(0, 8), pady=6, ipady=4)
        tk.Label(hdr, text="nome + percorso per tasto  |  AUTO = ~/Immagini/Smistati/  |  ... = percorso libero",
                 font=("TkFixedFont", 7), bg=PANEL_COLOR,
                 fg=MUTED_COLOR).grid(row=1, column=0, columnspan=3,
                                       sticky="w", padx=8, pady=(0, 2))
        self._dup_lbl = tk.Label(hdr, text="", font=("TkFixedFont", 7),
                                  bg=PANEL_COLOR, fg=PRIVACY_RED, anchor="w")
        self._dup_lbl.grid(row=2, column=0, columnspan=3,
                            sticky="w", padx=8, pady=(0, 4))

        # Scroll area tasti (riga 1, si espande)
        canvas = tk.Canvas(f, bg=BG_COLOR, highlightthickness=0)
        canvas.grid(row=1, column=0, sticky="nsew", padx=8, pady=(4, 2))
        vsb = tk.Scrollbar(f, orient="vertical", command=canvas.yview)
        vsb.grid(row=1, column=1, sticky="ns", pady=(4, 2))
        canvas.configure(yscrollcommand=vsb.set)
        self._dest_canvas = canvas

        inner = tk.Frame(canvas, bg=BG_COLOR)
        inner_id = canvas.create_window((0, 0), window=inner, anchor="nw")
        inner.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>", lambda e: canvas.itemconfig(inner_id, width=e.width))
        inner.bind("<Button-4>", lambda e: canvas.yview_scroll(-1, "units"))
        inner.bind("<Button-5>", lambda e: canvas.yview_scroll(1, "units"))
        self._dest_inner = inner
        self._dest_inner_id = inner_id

        self._build_dest_keys()
        self._schedule_dest_dup_check(150)

        # Bottone nella barra fondo a sinistra
        tk.Button(self._bot_left, text="  APPLICA  ",
                  font=("TkFixedFont", 9, "bold"),
                  bg=HIGHLIGHT, fg="white", relief="flat",
                  activebackground="#c73652",
                  command=self._apply_dest
                  ).pack(side="left", padx=10, pady=6, ipady=3)
    def _schedule_dest_dup_check(self, delay_ms):
        """Rischedula _check_dest_duplicates annullando l'eventuale chiamata
        già in coda — evita di accumulare controlli ridondanti se l'utente
        digita velocemente in un campo percorso."""
        pending = getattr(self, "_dup_check_after_id", None)
        if pending:
            try:
                self.win.after_cancel(pending)
            except Exception:
                pass
        self._dup_check_after_id = self.win.after(delay_ms, self._check_dest_duplicates)

    def _check_dest_duplicates(self):
        """Controlla percorsi duplicati tra i tasti del preset corrente.
        Colora in rosso i campi percorso duplicati e aggiorna un indicatore."""
        # Guard: può essere chiamata in ritardo (after) o da una trace su
        # una StringVar, anche dopo che il tab Destinazioni non è più quello
        # visibile (i widget sono stati distrutti/ricostruiti nel frattempo)
        inner = getattr(self, "_dest_inner", None)
        if inner is None or not inner.winfo_exists():
            return
        if getattr(self, "_current_tab", None) is None or self._current_tab.get() != "dest":
            return
        # Raccoglie tutti i path non vuoti
        path_to_keys = {}
        for k, pv in self.path_vars.items():
            p = pv.get().strip()
            if p:
                path_to_keys.setdefault(p, []).append(k)

        duplicates = {p: keys for p, keys in path_to_keys.items() if len(keys) > 1}
        dup_keys = {k for keys in duplicates.values() for k in keys}

        # Aggiorna colore campo percorso
        inner = self._dest_inner
        for ri, k in enumerate(KEYS, start=1):
            slaves = inner.grid_slaves(row=ri, column=2)
            if slaves:
                entry = slaves[0]
                try:
                    if k in dup_keys:
                        entry.config(bg="#4a1a1a", fg="#ff8888")
                    else:
                        entry.config(bg=BG_COLOR, fg=MUTED_COLOR)
                except Exception:
                    pass

        # Aggiorna indicatore duplicati nell'header
        if hasattr(self, '_dup_lbl') and self._dup_lbl.winfo_exists():
            if duplicates:
                paths_str = "; ".join(
                    f"{'+'.join(keys)}: {os.path.basename(p) or p}"
                    for p, keys in duplicates.items())
                self._dup_lbl.config(
                    text=tk_safe(f"  Percorsi duplicati: {paths_str}"),
                    fg=PRIVACY_RED)
            else:
                self._dup_lbl.config(text="", fg=MUTED_COLOR)

    def _reload_dest_preset(self):
        pname = self._dest_preset_var.get()
        self.slots = copy.deepcopy(self.config["presets"][pname])
        self.label_vars.clear()
        self.path_vars.clear()
        self.mode_vars.clear()
        for w in self._dest_inner.winfo_children():
            w.destroy()
        self.label_vars.clear()
        self.path_vars.clear()
        self.mode_vars.clear()
        self._build_dest_keys()
        self._dest_canvas.yview_moveto(0)

    def _build_dest_keys(self):
        """Layout a griglia compatta: ogni riga = un tasto, colonne = badge | nome | percorso | btn."""
        inner = self._dest_inner
        inner.columnconfigure(0, minsize=28)  # badge
        inner.columnconfigure(1, weight=2)    # nome
        inner.columnconfigure(2, weight=3)    # percorso
        inner.columnconfigure(3, minsize=28)  # btn ...
        inner.columnconfigure(4, minsize=28)  # btn X

        # Intestazione
        for ci, txt in enumerate(["", "Nome etichetta", "Percorso (vuoto = AUTO)", "", ""]):
            if txt:
                tk.Label(inner, text=txt, font=("TkFixedFont", 7),
                         bg=BG_COLOR, fg=MUTED_COLOR).grid(
                         row=0, column=ci, sticky="w", padx=4, pady=(4,2))

        for ri, k in enumerate(KEYS, start=1):
            self._build_key_row(inner, ri, k)

    def _build_key_row(self, inner, ri, k):
        color     = KEY_COLORS[KEYS.index(k)]
        slot      = self.slots[k]
        is_custom = bool(slot.get("path", "").strip())

        # Badge colorato
        tk.Label(inner, text=f" {k} ", font=("TkFixedFont", 10, "bold"),
                 bg=color, fg="white", anchor="center").grid(
                 row=ri, column=0, sticky="ew", padx=(6,2), pady=2, ipady=2)

        # Campo nome
        lv = tk.StringVar(value=slot.get("label", ""))
        self.label_vars[k] = lv
        tk.Entry(inner, textvariable=lv, font=("TkFixedFont", 9),
                 bg=ACCENT_COLOR, fg=TEXT_COLOR, insertbackground=TEXT_COLOR,
                 relief="flat", bd=3).grid(
                 row=ri, column=1, sticky="ew", padx=2, pady=2, ipady=3)

        # Campo percorso
        pv = tk.StringVar(value=slot.get("path", ""))
        self.path_vars[k] = pv
        mv = tk.StringVar(value="custom" if is_custom else "auto")
        self.mode_vars[k] = mv

        path_entry = tk.Entry(inner, textvariable=pv,
                              font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR,
                              insertbackground=TEXT_COLOR, relief="flat", bd=3,
                              state="normal" if is_custom else "disabled")
        path_entry.grid(row=ri, column=2, sticky="ew", padx=2, pady=2, ipady=3)

        # Check duplicati al cambio percorso
        pv.trace_add("write", lambda *_: self._schedule_dest_dup_check(100))

        # Drag & drop su badge e campo etichetta
        def _dest_dnd(dropped, key=k, pvar=pv, lvar=lv,
                       entry=path_entry, mvar=mv):
            if isinstance(dropped, list): dropped=dropped[0] if dropped else ""
            if not dropped: return
            if os.path.isfile(dropped): dropped=os.path.dirname(dropped)
            if not os.path.isdir(dropped): return
            folder_name = os.path.basename(dropped) or dropped
            pvar.set(dropped)
            mvar.set("custom")
            entry.config(state="normal")
            # Aggiorna etichetta solo se vuota
            if not lvar.get().strip():
                lvar.set(folder_name[:16])
            # Aggiorna self.slots e salva subito
            self.slots[key] = {
                "path":  dropped,
                "label": lvar.get().strip() or folder_name[:16],
            }
            self._apply_dest()
        if _TKDND_OK:
            for _w in [inner.grid_slaves(row=ri, column=0)[0],
                        inner.grid_slaves(row=ri, column=1)[0]]:
                _dnd_register(_w, _dest_dnd)
            _dnd_register(path_entry, _dest_dnd)

        def browse(key=k, pvar=pv, entry=path_entry, lvar=lv):
            try:
                initial = (pvar.get().strip()
                           or self.config.get("last_browse_dir", "")
                           or os.path.expanduser("~"))
                if not os.path.isdir(initial):
                    initial = os.path.expanduser("~")
                self._browse_with_mkdir(key, pvar, entry, initial, lvar)
            except Exception:
                import traceback
                traceback.print_exc()
                # Fallback a dialogo nativo
                folder = browse_folder_hud(self.win, title="Scegli cartella destinazione", initial_dir=initial, config=self.config)
                if folder:
                    pvar.set(folder)
                    self.mode_vars[key].set("custom")
                    entry.config(state="normal")
                    if lvar is not None:
                        current_label = lvar.get().strip()
                        old_basename = os.path.basename(pvar.get().strip()) if pvar.get().strip() else ""
                        if not current_label or current_label == old_basename:
                            lvar.set(os.path.basename(folder) or folder)

        def _browse_with_mkdir_impl(key, pvar, entry, initial_dir, lvar=None):
            """Browser cartelle avanzato con accesso rapido a dischi e nuova cartella."""
            # Ricorda ultima cartella
            last_dir = self.config.get("last_browse_dir", initial_dir) or initial_dir
            if not os.path.isdir(last_dir):
                last_dir = os.path.expanduser("~")

            dlg = tk.Toplevel(self.win)
            dlg.withdraw()
            dlg.title(f"Scegli destinazione — tasto {key}")
            dlg.configure(bg=BG_COLOR)
            dlg.resizable(True, True)
            dlg.geometry("680x500")
            hud_apply(dlg)
            dlg.columnconfigure(0, weight=1)
            dlg.rowconfigure(1, weight=1)

            # ── Barra superiore: percorso ──────────────────────────────────
            top = tk.Frame(dlg, bg=PANEL_COLOR)
            top.grid(row=0, column=0, columnspan=2, sticky="ew", padx=0, pady=0)
            top.columnconfigure(1, weight=1)
            tk.Label(top, text="Percorso:", font=("TkFixedFont", 8),
                     bg=PANEL_COLOR, fg=MUTED_COLOR).grid(
                     row=0, column=0, padx=(10,4), pady=6)
            path_v = tk.StringVar(value=last_dir)
            path_e = tk.Entry(top, textvariable=path_v,
                              font=("TkFixedFont", 9),
                              bg=ACCENT_COLOR, fg=HUD_CYAN,
                              insertbackground=HUD_CYAN,
                              relief="flat", bd=3)
            path_e.grid(row=0, column=1, sticky="ew", padx=4, pady=6, ipady=3)
            tk.Button(top, text="Vai", font=("TkFixedFont", 8),
                      bg=SUCCESS, fg="white", relief="flat", padx=8,
                      command=lambda: go_path()).grid(
                      row=0, column=2, padx=(0,8), pady=6, ipady=3)

            # ── Colonna sinistra: accesso rapido ───────────────────────────
            left = tk.Frame(dlg, bg=PANEL_COLOR, width=140)
            left.grid(row=1, column=0, sticky="nsew", padx=0, pady=0)
            left.grid_propagate(False)
            left.columnconfigure(0, weight=1)

            tk.Label(left, text="Accesso rapido",
                     font=("TkFixedFont", 8, "bold"),
                     bg=PANEL_COLOR, fg=MUTED_COLOR,
                     anchor="w").pack(fill="x", padx=8, pady=(8,4))

            # Raccoglie mount points: home, dischi montati
            def get_quick_access():
                places = [
                    ("[~] Home",    os.path.expanduser("~")),
                    ("[i] Immagini", os.path.expanduser("~/Immagini")),
                    ("[v] Video",   os.path.expanduser("~/Video")),
                    ("[d] Documenti", os.path.expanduser("~/Documenti")),
                    ("[s] Scrivania", os.path.expanduser("~/Scrivania")),
                ]
                # Dischi montati
                try:
                    mounts = []
                    with open("/proc/mounts") as f:
                        for line in f:
                            parts = line.split()
                            if len(parts) >= 2:
                                mp = parts[1]
                                if mp.startswith("/media/") or mp.startswith("/mnt/"):
                                    mounts.append(("[D] " + os.path.basename(mp), mp))
                    places += mounts
                except Exception:
                    pass
                places.append(("[/] Root", "/"))
                return [(label, p) for label, p in places if os.path.isdir(p)]

            quick_btns = []
            def build_quick():
                for w in left.winfo_children()[1:]:
                    w.destroy()
                for label, fpath in get_quick_access():
                    b = tk.Button(left, text=label,
                                  font=("TkFixedFont", 8),
                                  bg=PANEL_COLOR, fg=TEXT_COLOR,
                                  activebackground=ACCENT_COLOR,
                                  activeforeground=HUD_CYAN,
                                  relief="flat", anchor="w", padx=10,
                                  command=lambda p=fpath: populate(p))
                    b.pack(fill="x", pady=1, ipady=3)
                    quick_btns.append(b)

            build_quick()

            # Separatore
            tk.Frame(left, bg=ACCENT_COLOR, height=1).pack(fill="x", padx=6, pady=6)

            # Ultima cartella usata
            if self.config.get("last_browse_dir"):
                tk.Label(left, text="Ultima usata:",
                         font=("TkFixedFont", 7), bg=PANEL_COLOR,
                         fg=MUTED_COLOR, anchor="w").pack(fill="x", padx=8)
                last_lbl = tk.Label(left,
                    text=os.path.basename(self.config["last_browse_dir"]) or "/",
                    font=("TkFixedFont", 8), bg=PANEL_COLOR,
                    fg=HUD_CYAN, anchor="w", cursor="hand2", wraplength=120)
                last_lbl.pack(fill="x", padx=8, pady=(0,4))
                last_lbl.bind("<Button-1>",
                    lambda e: populate(self.config["last_browse_dir"]))

            # ── Colonna destra: lista cartelle ────────────────────────────
            right = tk.Frame(dlg, bg=BG_COLOR)
            right.grid(row=1, column=1, sticky="nsew", padx=0, pady=0)
            right.rowconfigure(0, weight=1)
            right.columnconfigure(0, weight=1)
            dlg.columnconfigure(1, weight=1)

            # Canvas + scrollbar per la lista
            canvas = tk.Canvas(right, bg=BG_COLOR, highlightthickness=0)
            vsb = tk.Scrollbar(right, orient="vertical", command=canvas.yview)
            canvas.configure(yscrollcommand=vsb.set)
            canvas.grid(row=0, column=0, sticky="nsew")
            vsb.grid(row=0, column=1, sticky="ns")

            inner = tk.Frame(canvas, bg=BG_COLOR)
            inner_id = canvas.create_window((0,0), window=inner, anchor="nw")
            inner.bind("<Configure>",
                lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
            canvas.bind("<Configure>",
                lambda e: canvas.itemconfig(inner_id, width=e.width))
            canvas.bind("<Button-4>",  lambda e: canvas.yview_scroll(-1,"units"))
            canvas.bind("<Button-5>",  lambda e: canvas.yview_scroll( 1,"units"))
            canvas.bind("<MouseWheel>",
                        lambda e: canvas.yview_scroll(-1 if e.delta > 0 else 1,"units"))
            inner.bind("<Button-4>",   lambda e: canvas.yview_scroll(-1,"units"))
            inner.bind("<Button-5>",   lambda e: canvas.yview_scroll( 1,"units"))
            # Propaga scroll dai widget figli (righe cartelle)
            def _bind_rows_scroll(e=None):
                for child in inner.winfo_children():
                    child.bind("<Button-4>", lambda e: canvas.yview_scroll(-1,"units"))
                    child.bind("<Button-5>", lambda e: canvas.yview_scroll( 1,"units"))
                    for grandchild in child.winfo_children():
                        grandchild.bind("<Button-4>", lambda e: canvas.yview_scroll(-1,"units"))
                        grandchild.bind("<Button-5>", lambda e: canvas.yview_scroll( 1,"units"))
            inner.bind("<Configure>", _bind_rows_scroll, add=True)

            current_dir = [os.path.normpath(last_dir)]
            selected_dir = [os.path.normpath(last_dir)]

            def populate(d):
                if not os.path.isdir(d):
                    return
                d = os.path.normpath(d)
                current_dir[0] = d
                selected_dir[0] = d
                path_v.set(d)
                for w in inner.winfo_children():
                    w.destroy()

                # Riga ".."
                if d != "/":
                    parent = os.path.dirname(d)
                    row = tk.Frame(inner, bg=BG_COLOR, cursor="hand2")
                    row.pack(fill="x", padx=4, pady=1)
                    tk.Label(row, text="[>]", font=("TkFixedFont", 10),
                             bg=BG_COLOR, fg=MUTED_COLOR).pack(side="left", padx=(6,4))
                    tk.Label(row, text="..", font=("TkFixedFont", 9),
                             bg=BG_COLOR, fg=MUTED_COLOR).pack(side="left")
                    for w in (row,) + tuple(row.winfo_children()):
                        w.bind("<Double-Button-1>", lambda e, p=parent: populate(p))
                        w.bind("<Button-1>", lambda e, p=parent: select_row(p, row))

                # Sottocartelle
                try:
                    entries = sorted(
                        (e for e in os.scandir(d)
                         if e.is_dir() and not e.name.startswith(".")),
                        key=lambda e: e.name.lower())
                except OSError:
                    entries = []

                row_refs = {}
                for e in entries:
                    fpath = e.path
                    # Conta file
                    try:
                        n_files = sum(1 for f in os.scandir(fpath)
                                      if f.is_file())
                    except OSError:
                        n_files = 0

                    bg_row = BG_COLOR
                    row = tk.Frame(inner, bg=bg_row, cursor="hand2")
                    row.pack(fill="x", padx=4, pady=1)

                    tk.Label(row, text="[>]", font=("TkFixedFont", 10),
                             bg=bg_row, fg=HUD_CYAN).pack(side="left", padx=(6,4))
                    tk.Label(row, text=e.name, font=("TkFixedFont", 9, "bold"),
                             bg=bg_row, fg=TEXT_COLOR).pack(side="left")
                    if n_files:
                        tk.Label(row, text=f"  {n_files}",
                                 font=("TkFixedFont", 7),
                                 bg=bg_row, fg=MUTED_COLOR).pack(side="left")
                    row_refs[fpath] = row

                    def _bind(row=row, fpath=fpath):
                        for w in [row] + list(row.winfo_children()):
                            w.bind("<Button-1>",
                                   lambda e, p=fpath, r=row: select_row(p, r))
                            w.bind("<Double-Button-1>",
                                   lambda e, p=fpath: populate(p))
                    _bind()

                canvas.yview_moveto(0)

            def select_row(fpath, row_widget):
                selected_dir[0] = fpath
                path_v.set(fpath)
                # Evidenzia riga selezionata
                for w in inner.winfo_children():
                    try:
                        w.config(bg=BG_COLOR)
                        for c in w.winfo_children():
                            c.config(bg=BG_COLOR)
                    except Exception:
                        pass
                try:
                    row_widget.config(bg=ACCENT_COLOR)
                    for c in row_widget.winfo_children():
                        c.config(bg=ACCENT_COLOR)
                except Exception:
                    pass

            def go_path(e=None):
                d = path_v.get().strip()
                if os.path.isdir(d):
                    populate(d)

            path_e.bind("<Return>", go_path)
            populate(last_dir)

            # ── Barra inferiore ────────────────────────────────────────────
            bot = tk.Frame(dlg, bg=PANEL_COLOR)
            bot.grid(row=2, column=0, columnspan=2, sticky="ew")
            dlg.rowconfigure(2, weight=0)

            def mkdir_action():
                base = selected_dir[0] or current_dir[0]
                name = self.sorter._hud_prompt(
                    "Nuova cartella",
                    f"Nome della nuova cartella in:\n{base}",
                    ok_label="Crea", parent=dlg)
                if not name:
                    return
                new_d = os.path.join(base, name)
                try:
                    os.makedirs(new_d, exist_ok=True)
                    populate(current_dir[0])
                    selected_dir[0] = new_d
                    path_v.set(new_d)
                except Exception as ex:
                    self._hud_alert("Errore", f"Impossibile creare:\n{ex}", parent=dlg)

            def confirm():
                chosen = selected_dir[0] or path_v.get().strip()
                if not chosen or not os.path.isdir(chosen):
                    chosen = current_dir[0]
                pvar.set(chosen)
                self.mode_vars[key].set("custom")
                entry.config(state="normal")
                # Auto-compila etichetta col nome cartella se è vuota
                # o se coincide ancora col basename del percorso precedente
                if lvar is not None:
                    current_label = lvar.get().strip()
                    old_basename = os.path.basename(pvar.get().strip()) if pvar.get().strip() else ""
                    if not current_label or current_label == old_basename:
                        lvar.set(os.path.basename(chosen) or chosen)
                self.config["last_browse_dir"] = chosen
                save_config(self.config)
                dlg.destroy()

            _ico_nf  = make_icon("new_folder", size=15, fg=(0,255,128), bg=(10,15,26))
            _ico_sel = make_icon("check",      size=15, fg=(0,200,255), bg=(10,26,42))
            _btn_nf = tk.Button(bot, text="  Nuova cartella", image=_ico_nf,
                      compound="left",
                      font=("TkFixedFont", 9), bg=BG_COLOR, fg=HUD_CYAN,
                      relief="flat", padx=10,
                      command=mkdir_action)
            _btn_nf._ico = _ico_nf
            _btn_nf.pack(side="left", padx=8, pady=8, ipady=4)
            tk.Label(bot, text="", bg=PANEL_COLOR).pack(side="left", expand=True)
            tk.Button(bot, text="Annulla",
                      font=("TkFixedFont", 9), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                      relief="flat", padx=10,
                      command=dlg.destroy).pack(side="right", padx=6, pady=8, ipady=4)
            _btn_sel = tk.Button(bot, text="  Seleziona", image=_ico_sel,
                      compound="left",
                      font=("TkFixedFont", 9, "bold"), bg=HUD_CYAN, fg="#0a1a2e",
                      relief="flat", padx=14,
                      command=confirm)
            _btn_sel._ico = _ico_sel
            _btn_sel.pack(side="right", padx=(0,8), pady=8, ipady=4)
            dlg.bind("<Return>", lambda e: confirm())
            dlg.bind("<Escape>", lambda e: dlg.destroy())

            # Posiziona nel terzo destro dello schermo
            dlg.update_idletasks()
            screen_w = self.win.winfo_screenwidth()
            screen_h = self.win.winfo_screenheight()
            pw = min(700, screen_w * 2 // 5)
            ph = min(560, screen_h - 80)
            px = screen_w * 3 // 5 - pw // 2   # circa 3/5 da sinistra
            px = min(px, screen_w - pw - 20)
            py = (screen_h - ph) // 2
            dlg.geometry(f"{pw}x{ph}+{px}+{py}")
            dlg.deiconify()
            dlg.grab_set()


        self._browse_with_mkdir = _browse_with_mkdir_impl

        def clear(key=k, pvar=pv, entry=path_entry, lvar=lv):
            pvar.set("")
            lvar.set("")
            self.mode_vars[key].set("auto")
            entry.config(state="disabled")

        def update_placeholder(*_):
            if not self.mode_vars[k].get() == "custom" or not self.path_vars[k].get().strip():
                path_entry.config(state="disabled")
                if not pv.get():
                    # mostra hint
                    pass
            else:
                path_entry.config(state="normal")

        mv.trace_add("write", update_placeholder)
        pv.trace_add("write", update_placeholder)

        tk.Button(inner, text="...", font=("TkFixedFont", 8),
                  bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat",
                  activebackground=HIGHLIGHT,
                  command=browse).grid(row=ri, column=3, padx=2, pady=2, sticky="ew")
        tk.Button(inner, text="X", font=("TkFixedFont", 8),
                  bg="#c0392b", fg="white", relief="flat",
                  activebackground=HIGHLIGHT,
                  command=clear).grid(row=ri, column=4, padx=(2,6), pady=2, sticky="ew")

    def _build_view_tab(self):
        """Tab Visualizza: scegli quali tipi di file mostrare."""
        f = self._content
        f.columnconfigure(0, weight=1)

        tk.Label(f, text="Tipi di file da visualizzare",
                 font=("TkFixedFont", 11, "bold"),
                 bg=BG_COLOR, fg=HUD_CYAN).pack(padx=24, pady=(20,4), anchor="w")
        tk.Label(f, text="Le impostazioni vengono applicate al prossimo caricamento cartella.",
                 font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).pack(padx=24, pady=(0,16), anchor="w")

        cfg = self.config
        entries = [
            ("show_images", "Immagini",
             ".jpg  .jpeg  .png  .gif  .bmp  .tiff  .webp  .pnm  .pbm  .pgm  .ppm  .heic  .heif"),
            ("show_videos", "Video",
             ".mp4  .mov  .avi  .mkv  .webm  .m4v  .flv  (richiede ffmpeg)"),
            ("show_pdfs",   "PDF",
             ".pdf  (richiede poppler-utils)"),
            ("show_no_ext", "File senza estensione",
             "rilevati automaticamente tramite magic bytes"),
        ]

        self._view_vars = {}

        def _make_toggle(parent, cfg_key, label, desc):
            val = cfg.get(cfg_key, True)
            var = tk.BooleanVar(value=val)
            self._view_vars[cfg_key] = var

            row = tk.Frame(parent, bg=ACCENT_COLOR)
            row.pack(fill="x", padx=20, pady=4)
            row.columnconfigure(2, weight=1)

            # Bottone ON/OFF visuale
            btn_frame = tk.Frame(row, bg=ACCENT_COLOR)
            btn_frame.grid(row=0, column=0, rowspan=2, padx=(10,8), pady=8)

            on_btn  = [None]
            off_btn = [None]

            def _toggle(new_val):
                var.set(new_val)
                _refresh_btns()
                self._apply_view_filter(cfg_key, var)

            def _refresh_btns():
                v = var.get()
                on_btn[0].config(
                    bg=SUCCESS if v else ACCENT_COLOR,
                    fg="white" if v else MUTED_COLOR,
                    relief="flat" if v else "flat")
                off_btn[0].config(
                    bg="#c0392b" if not v else ACCENT_COLOR,
                    fg="white" if not v else MUTED_COLOR)

            on_btn[0]  = tk.Button(btn_frame, text=" ON  ",
                                   font=("TkFixedFont", 8, "bold"),
                                   relief="flat", bd=0, padx=4, pady=2,
                                   command=lambda: _toggle(True))
            on_btn[0].pack(side="left")
            off_btn[0] = tk.Button(btn_frame, text=" OFF ",
                                   font=("TkFixedFont", 8, "bold"),
                                   relief="flat", bd=0, padx=4, pady=2,
                                   command=lambda: _toggle(False))
            off_btn[0].pack(side="left")
            _refresh_btns()

            tk.Label(row, text=label,
                     font=("TkFixedFont", 10, "bold"),
                     bg=ACCENT_COLOR, fg=TEXT_COLOR,
                     anchor="w").grid(row=0, column=2, sticky="w")
            tk.Label(row, text=desc,
                     font=("TkFixedFont", 8),
                     bg=ACCENT_COLOR, fg=MUTED_COLOR,
                     anchor="w").grid(row=1, column=2, sticky="w",
                                      padx=(0,10), pady=(0,8))

        for cfg_key, label, desc in entries:
            _make_toggle(f, cfg_key, label, desc)

        # Sezione estensioni personalizzate
        tk.Frame(f, bg=ACCENT_COLOR, height=1).pack(fill="x", padx=20, pady=(16,8))
        tk.Label(f, text="Estensioni aggiuntive da includere (separate da virgola):",
                 font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).pack(padx=24, anchor="w")

        extra_frame = tk.Frame(f, bg=BG_COLOR)
        extra_frame.pack(fill="x", padx=20, pady=4)
        extra_frame.columnconfigure(0, weight=1)

        extra_var = tk.StringVar(value=", ".join(sorted(cfg.get("extra_extensions", []))))
        extra_entry = tk.Entry(extra_frame, textvariable=extra_var,
                               font=("TkFixedFont", 9),
                               bg=ACCENT_COLOR, fg=TEXT_COLOR,
                               insertbackground=TEXT_COLOR,
                               relief="flat", bd=4)
        extra_entry.grid(row=0, column=0, sticky="ew", ipady=4)

        def save_extra(e=None):
            raw = extra_var.get()
            exts = [x.strip().lower() for x in raw.split(",") if x.strip()]
            exts = ["." + e if not e.startswith(".") else e for e in exts]
            cfg["extra_extensions"] = exts
            save_config(cfg)
            self._reload_sorter_list()

        tk.Button(extra_frame, text="Salva",
                  font=("TkFixedFont", 8), bg=SUCCESS, fg="white",
                  relief="flat", padx=8,
                  command=save_extra).grid(row=0, column=1, padx=(6,0), ipady=4)
        extra_entry.bind("<Return>", save_extra)

        tk.Label(f, text="Es: .heic, .arw, .cr2, .dng",
                 font=("TkFixedFont", 7),
                 bg=BG_COLOR, fg=MUTED_COLOR).pack(padx=24, pady=(2,0), anchor="w")

    def _apply_view_filter(self, cfg_key, var):
        """Salva la preferenza di visualizzazione e ricarica la lista."""
        self.config[cfg_key] = var.get()
        save_config(self.config)
        self._reload_sorter_list()

    def _reload_sorter_list(self):
        """Ricarica la lista immagini nel sorter applicando i filtri correnti."""
        if self.sorter.source_folder:
            self.sorter.images = self.sorter._load_images()
            self.sorter.current_index = min(
                self.sorter.current_index, max(0, len(self.sorter.images)-1))
            self.sorter._show_image()

    # ------------------------------------------------------------------
    # TAB TAG (libreria tag + Gruppi Tag)
    # ------------------------------------------------------------------
    def _build_tags_tab(self):
        """Tab Tag: crea/elenca/rinomina/elimina i tag della libreria e i
        Gruppi Tag (raggruppamenti liberi di tag, base per funzioni
        future — solo organizzazione per ora, come richiesto)."""
        f = self._content
        if not _METADATA_STORE_AVAILABLE:
            tk.Label(f, text="Modulo metadata_store non disponibile.",
                     font=("TkFixedFont", 10), bg=BG_COLOR, fg=MUTED_COLOR
                     ).pack(padx=24, pady=20, anchor="w")
            return
        f.columnconfigure(0, weight=1)
        f.columnconfigure(1, weight=1)
        f.rowconfigure(1, weight=1)

        tk.Label(f, text="Gestione tag e Gruppi Tag",
                 font=("TkFixedFont", 11, "bold"),
                 bg=BG_COLOR, fg=HUD_CYAN).grid(
                     row=0, column=0, columnspan=2, sticky="w", padx=20, pady=(16, 8))

        # --- Colonna sinistra: Tag ---
        left = tk.Frame(f, bg=BG_COLOR)
        left.grid(row=1, column=0, sticky="nsew", padx=(20, 10), pady=(0, 4))
        left.rowconfigure(1, weight=1)
        left.columnconfigure(0, weight=1)
        tk.Label(left, text="Tag", font=("TkFixedFont", 9, "bold"),
                 bg=BG_COLOR, fg=TEXT_COLOR).grid(row=0, column=0, sticky="w")

        tag_lf = tk.Frame(left, bg=ACCENT_COLOR)
        tag_lf.grid(row=1, column=0, sticky="nsew", pady=(2, 4))
        tag_lf.rowconfigure(0, weight=1)
        tag_lf.columnconfigure(0, weight=1)
        tag_sb = tk.Scrollbar(tag_lf, orient="vertical", bg=ACCENT_COLOR, troughcolor=BG_COLOR)
        tag_sb.grid(row=0, column=1, sticky="ns")
        self.tag_listbox = tk.Listbox(tag_lf, font=("TkFixedFont", 10),
                                      bg=PANEL_COLOR, fg=TEXT_COLOR,
                                      selectbackground=HIGHLIGHT, selectforeground="white",
                                      activestyle="none", relief="flat", bd=0,
                                      height=10, exportselection=False,
                                      yscrollcommand=tag_sb.set)
        self.tag_listbox.grid(row=0, column=0, sticky="nsew")
        tag_sb.config(command=self.tag_listbox.yview)
        self.tag_listbox.bind("<Button-4>", lambda e: self.tag_listbox.yview_scroll(-1, "units"))
        self.tag_listbox.bind("<Button-5>", lambda e: self.tag_listbox.yview_scroll(1, "units"))

        tag_new_row = tk.Frame(left, bg=BG_COLOR)
        tag_new_row.grid(row=2, column=0, sticky="ew", pady=(0, 4))
        tag_new_row.columnconfigure(0, weight=1)
        self._tag_new_var = tk.StringVar(value="")
        tag_new_entry = tk.Entry(tag_new_row, textvariable=self._tag_new_var,
                                 font=("TkFixedFont", 9), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                                 insertbackground=TEXT_COLOR, relief="flat", bd=3)
        tag_new_entry.grid(row=0, column=0, sticky="ew", ipady=3)
        tag_new_entry.bind("<Return>", lambda e: (self._tags_new_tag(), "break")[1])
        tk.Button(tag_new_row, text="+ Nuovo", font=("TkFixedFont", 8),
                  bg=SUCCESS, fg="white", relief="flat", padx=6,
                  command=self._tags_new_tag).grid(row=0, column=1, padx=(4, 0))

        tag_btn_row = tk.Frame(left, bg=BG_COLOR)
        tag_btn_row.grid(row=3, column=0, sticky="ew")
        tk.Button(tag_btn_row, text="Rinomina", font=("TkFixedFont", 8),
                  bg=WARNING, fg="white", relief="flat", padx=6,
                  command=self._tags_rename_tag).pack(side="left", fill="x", expand=True, padx=(0, 3))
        tk.Button(tag_btn_row, text="Elimina", font=("TkFixedFont", 8),
                  bg="#c0392b", fg="white", relief="flat", padx=6,
                  command=self._tags_delete_tag).pack(side="left", fill="x", expand=True)

        # --- Colonna destra: Gruppi Tag ---
        right = tk.Frame(f, bg=BG_COLOR)
        right.grid(row=1, column=1, sticky="nsew", padx=(10, 20), pady=(0, 4))
        right.rowconfigure(1, weight=1)
        right.columnconfigure(0, weight=1)
        tk.Label(right, text="Gruppi Tag", font=("TkFixedFont", 9, "bold"),
                 bg=BG_COLOR, fg=TEXT_COLOR).grid(row=0, column=0, sticky="w")

        grp_lf = tk.Frame(right, bg=ACCENT_COLOR)
        grp_lf.grid(row=1, column=0, sticky="nsew", pady=(2, 4))
        grp_lf.rowconfigure(0, weight=1)
        grp_lf.columnconfigure(0, weight=1)
        grp_sb = tk.Scrollbar(grp_lf, orient="vertical", bg=ACCENT_COLOR, troughcolor=BG_COLOR)
        grp_sb.grid(row=0, column=1, sticky="ns")
        self.group_listbox = tk.Listbox(grp_lf, font=("TkFixedFont", 10),
                                        bg=PANEL_COLOR, fg=TEXT_COLOR,
                                        selectbackground=HIGHLIGHT, selectforeground="white",
                                        activestyle="none", relief="flat", bd=0,
                                        height=10, exportselection=False,
                                        yscrollcommand=grp_sb.set)
        self.group_listbox.grid(row=0, column=0, sticky="nsew")
        grp_sb.config(command=self.group_listbox.yview)
        self.group_listbox.bind("<Button-4>", lambda e: self.group_listbox.yview_scroll(-1, "units"))
        self.group_listbox.bind("<Button-5>", lambda e: self.group_listbox.yview_scroll(1, "units"))
        self.group_listbox.bind("<<ListboxSelect>>", lambda e: self._tags_rebuild_membership_cloud())

        grp_new_row = tk.Frame(right, bg=BG_COLOR)
        grp_new_row.grid(row=2, column=0, sticky="ew", pady=(0, 4))
        grp_new_row.columnconfigure(0, weight=1)
        self._group_new_var = tk.StringVar(value="")
        grp_new_entry = tk.Entry(grp_new_row, textvariable=self._group_new_var,
                                 font=("TkFixedFont", 9), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                                 insertbackground=TEXT_COLOR, relief="flat", bd=3)
        grp_new_entry.grid(row=0, column=0, sticky="ew", ipady=3)
        grp_new_entry.bind("<Return>", lambda e: (self._tags_new_group(), "break")[1])
        tk.Button(grp_new_row, text="+ Nuovo", font=("TkFixedFont", 8),
                  bg=SUCCESS, fg="white", relief="flat", padx=6,
                  command=self._tags_new_group).grid(row=0, column=1, padx=(4, 0))

        grp_btn_row = tk.Frame(right, bg=BG_COLOR)
        grp_btn_row.grid(row=3, column=0, sticky="ew")
        tk.Button(grp_btn_row, text="Rinomina", font=("TkFixedFont", 8),
                  bg=WARNING, fg="white", relief="flat", padx=6,
                  command=self._tags_rename_group).pack(side="left", fill="x", expand=True, padx=(0, 3))
        tk.Button(grp_btn_row, text="Elimina", font=("TkFixedFont", 8),
                  bg="#c0392b", fg="white", relief="flat", padx=6,
                  command=self._tags_delete_group).pack(side="left", fill="x", expand=True)

        # --- Appartenenza al gruppo selezionato ---
        tk.Frame(f, bg=ACCENT_COLOR, height=1).grid(
            row=2, column=0, columnspan=2, sticky="ew", padx=20, pady=(8, 4))
        self._group_membership_title = tk.Label(
            f, text="Tag nel gruppo selezionato:", font=("TkFixedFont", 8),
            bg=BG_COLOR, fg=MUTED_COLOR)
        self._group_membership_title.grid(row=3, column=0, columnspan=2, sticky="w", padx=24)

        cloud_outer = tk.Frame(f, bg=BG_COLOR)
        cloud_outer.grid(row=4, column=0, columnspan=2, sticky="ew", padx=20, pady=(2, 4))
        CLOUD_W, CLOUD_H = 620, 110
        self._group_cloud_canvas = tk.Canvas(cloud_outer, bg=BG_COLOR, width=CLOUD_W,
                                             height=CLOUD_H, highlightthickness=0)
        cloud_vsb = tk.Scrollbar(cloud_outer, orient="vertical",
                                 command=self._group_cloud_canvas.yview)
        self._group_cloud_canvas.configure(yscrollcommand=cloud_vsb.set)
        self._group_cloud_canvas.pack(side="left", fill="both", expand=True)
        cloud_vsb.pack(side="left", fill="y")
        self._group_cloud_inner = tk.Frame(self._group_cloud_canvas, bg=BG_COLOR)
        self._group_cloud_canvas.create_window(0, 0, window=self._group_cloud_inner, anchor="nw")

        def _on_cloud_configure(e=None):
            self._group_cloud_canvas.configure(scrollregion=self._group_cloud_canvas.bbox("all"))
        self._group_cloud_inner.bind("<Configure>", _on_cloud_configure)

        def _on_mousewheel(e):
            self._group_cloud_canvas.yview_scroll(-1 if e.delta > 0 else 1, "units")
        self._group_cloud_canvas.bind(
            "<Enter>", lambda e: self._group_cloud_canvas.bind_all("<MouseWheel>", _on_mousewheel))
        self._group_cloud_canvas.bind(
            "<Leave>", lambda e: self._group_cloud_canvas.unbind_all("<MouseWheel>"))

        # Ordine dei tag nella nuvola (finestra Tag Ctrl+T, riga Tag di
        # Naviga/Timeline, e qui sopra) — spostato dal tab Visualizza:
        # e' una preferenza sui TAG, ha piu' senso qui ora che esiste
        # questa scheda dedicata.
        tk.Frame(f, bg=ACCENT_COLOR, height=1).grid(
            row=5, column=0, columnspan=2, sticky="ew", padx=20, pady=(4, 8))
        tk.Label(f, text="Ordine dei tag nella nuvola (Ctrl+T, Naviga, Timeline):",
                 font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(
                     row=6, column=0, columnspan=2, sticky="w", padx=24)

        sort_frame = tk.Frame(f, bg=BG_COLOR)
        sort_frame.grid(row=7, column=0, columnspan=2, sticky="w", padx=20, pady=(4, 12))

        cfg = self.config
        sort_var = tk.StringVar(value=cfg.get("tag_sort_mode", "alpha"))
        sort_btns = {}

        def _refresh_sort_btns():
            for m, b in sort_btns.items():
                active = (sort_var.get() == m)
                b.config(bg=HUD_CYAN if active else ACCENT_COLOR,
                        fg="#0a1a2e" if active else TEXT_COLOR,
                        font=("TkFixedFont", 9, "bold" if active else "normal"))

        def _set_sort_mode(mode):
            sort_var.set(mode)
            cfg["tag_sort_mode"] = mode
            save_config(cfg)
            _refresh_sort_btns()

        for _mode, _label in (("alpha", "Alfabetico"),
                              ("recent", "Uso recente"),
                              ("freq", "Frequenza")):
            _b = tk.Button(sort_frame, text=_label, font=("TkFixedFont", 9),
                          relief="flat", padx=10, pady=4,
                          activebackground=HIGHLIGHT, activeforeground="white",
                          command=lambda m=_mode: _set_sort_mode(m))
            _b.pack(side="left", padx=(0, 6))
            sort_btns[_mode] = _b
        _refresh_sort_btns()

        self._tags_refresh_tag_list()
        self._tags_refresh_group_list()
        self._tags_rebuild_membership_cloud()

    def _tags_selected_tag(self):
        sel = self.tag_listbox.curselection()
        if not sel:
            return None
        tags = metadata_store.get_all_tags()
        return tags[sel[0]] if sel[0] < len(tags) else None

    def _tags_refresh_tag_list(self, select=None):
        self.tag_listbox.delete(0, tk.END)
        tags = metadata_store.get_all_tags()
        counts = metadata_store.get_tag_counts()
        for t in tags:
            n = counts.get(t, 0)
            suffix = f"  ({n})" if n else "  (0)"
            self.tag_listbox.insert(tk.END, f"  {t}{suffix}")
        if select in tags:
            idx = tags.index(select)
            self.tag_listbox.selection_set(idx)
            self.tag_listbox.see(idx)

    def _tags_new_tag(self):
        name = self._tag_new_var.get().strip()
        if not name:
            return
        canonical = metadata_store.create_tag(name)
        self._tag_new_var.set("")
        self._tags_refresh_tag_list(select=canonical)
        self._tags_rebuild_membership_cloud()

    def _tags_rename_tag(self):
        old = self._tags_selected_tag()
        if not old:
            return
        new = self.sorter._hud_prompt(
            "Rinomina tag", f"Nuovo nome per '{old}':",
            initial=old, ok_label="Rinomina", parent=self.win)
        if not new or new.strip() == old:
            return
        metadata_store.rename_tag(old, new.strip())
        self._tags_refresh_tag_list(select=new.strip())
        self._tags_rebuild_membership_cloud()

    def _tags_delete_tag(self):
        tag = self._tags_selected_tag()
        if not tag:
            return
        n = metadata_store.get_tag_counts().get(tag, 0)
        msg = (f"Eliminare il tag '{tag}'?\n\n"
               f"Verra' tolto da {n} file e da tutti i gruppi che lo contengono."
               if n else f"Eliminare il tag '{tag}'?")
        if not self._hud_yesno("Elimina tag", msg,
                              yes_label="Elimina", no_label="Annulla", parent=self.win):
            return
        metadata_store.delete_tag(tag)
        self._tags_refresh_tag_list()
        self._tags_refresh_group_list(select=self._tags_selected_group_name())
        self._tags_rebuild_membership_cloud()

    def _tags_selected_group_name(self):
        sel = self.group_listbox.curselection()
        if not sel:
            return None
        groups = list(metadata_store.get_tag_groups().keys())
        return groups[sel[0]] if sel[0] < len(groups) else None

    def _tags_refresh_group_list(self, select=None):
        self.group_listbox.delete(0, tk.END)
        groups = metadata_store.get_tag_groups()
        names = list(groups.keys())
        for g in names:
            self.group_listbox.insert(tk.END, f"  {g}  ({len(groups[g])})")
        if select in names:
            idx = names.index(select)
            self.group_listbox.selection_set(idx)
            self.group_listbox.see(idx)

    def _tags_new_group(self):
        name = self._group_new_var.get().strip()
        if not name:
            return
        canonical = metadata_store.create_tag_group(name)
        self._group_new_var.set("")
        self._tags_refresh_group_list(select=canonical)
        self._tags_rebuild_membership_cloud()

    def _tags_rename_group(self):
        old = self._tags_selected_group_name()
        if not old:
            return
        new = self.sorter._hud_prompt(
            "Rinomina gruppo", f"Nuovo nome per '{old}':",
            initial=old, ok_label="Rinomina", parent=self.win)
        if not new or new.strip() == old:
            return
        metadata_store.rename_tag_group(old, new.strip())
        self._tags_refresh_group_list(select=new.strip())
        self._tags_rebuild_membership_cloud()

    def _tags_delete_group(self):
        name = self._tags_selected_group_name()
        if not name:
            return
        if not self._hud_yesno(
                "Elimina gruppo",
                f"Eliminare il gruppo '{name}'?\n\n"
                "I tag che contiene NON vengono eliminati dalla libreria.",
                yes_label="Elimina", no_label="Annulla", parent=self.win):
            return
        metadata_store.delete_tag_group(name)
        self._tags_refresh_group_list()
        self._tags_rebuild_membership_cloud()

    def _tags_rebuild_membership_cloud(self):
        """Nuvola di bottoni on/off per i tag del gruppo selezionato —
        stesso schema della nuvola in _open_tag_window."""
        for w in self._group_cloud_inner.winfo_children():
            w.destroy()
        group = self._tags_selected_group_name()
        if not group:
            self._group_membership_title.config(text="Tag nel gruppo selezionato:")
            tk.Label(self._group_cloud_inner, text="(seleziona un gruppo per gestirne i tag)",
                     font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR
                     ).pack(anchor="w", padx=2, pady=6)
            return
        self._group_membership_title.config(text=f"Tag nel gruppo '{group}':")
        all_tags = metadata_store.get_all_tags()
        member_tags = set(metadata_store.get_tag_groups().get(group, []))
        if not all_tags:
            tk.Label(self._group_cloud_inner, text="(nessun tag ancora nella libreria)",
                     font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR
                     ).pack(anchor="w", padx=2, pady=6)
            return
        CLOUD_W = 610
        row = tk.Frame(self._group_cloud_inner, bg=BG_COLOR)
        row.pack(fill="x", anchor="w")
        used_w = 0
        _measure_font = tkfont.Font(family="TkFixedFont", size=8, weight="bold")
        for t in all_tags:
            is_on = t in member_tags
            est_w = _measure_font.measure(t) + 20
            if used_w + est_w > CLOUD_W and used_w > 0:
                row = tk.Frame(self._group_cloud_inner, bg=BG_COLOR)
                row.pack(fill="x", anchor="w")
                used_w = 0
            btn = tk.Button(
                row, text=t, font=("TkFixedFont", 8, "bold" if is_on else "normal"),
                bg=(HUD_CYAN if is_on else ACCENT_COLOR),
                fg=("#0a1a2e" if is_on else TEXT_COLOR),
                activebackground=HIGHLIGHT, activeforeground="white",
                relief="flat", padx=8, pady=3,
                command=lambda tg=t, g=group: self._tags_toggle_membership(g, tg))
            btn.pack(side="left", padx=2, pady=2)
            used_w += est_w

    def _tags_toggle_membership(self, group, tag):
        metadata_store.toggle_tag_in_group(group, tag)
        self._tags_refresh_group_list(select=group)
        self._tags_rebuild_membership_cloud()

    def _build_deck_tab(self):
        """Tab impostazioni Stream Deck: modello, luminosità, pagine idle."""
        f = self._content
        f.columnconfigure(0, weight=1)
        f.rowconfigure(1, weight=1)

        sdk = getattr(self.sorter, '_stream_deck', None)
        connected = sdk and sdk.is_active()
        n_keys = sdk._deck_info.get("key_count", 15) if connected else 15
        cols   = sdk._deck_info.get("cols", 5)        if connected else 5

        # ── Barra superiore: stato + luminosità ──────────────────────────────
        top = tk.Frame(f, bg=PANEL_COLOR)
        top.grid(row=0, column=0, sticky="ew")
        top.columnconfigure(2, weight=1)

        status_text = (f"Connesso: {sdk._deck_info.get('type','?')}  "
                       f"({n_keys} tasti)"
                       if connected else "Stream Deck non connesso")
        tk.Label(top, text=status_text,
                 font=("TkFixedFont", 9, "bold"),
                 bg=PANEL_COLOR,
                 fg=SUCCESS if connected else MUTED_COLOR
                 ).grid(row=0, column=0, padx=12, pady=8, sticky="w")

        tk.Label(top, text="Luminosità:",
                 font=("TkFixedFont", 8), bg=PANEL_COLOR,
                 fg=MUTED_COLOR).grid(row=0, column=1, padx=(16,4))
        bright_var = tk.IntVar(value=self.config.get("deck_brightness", 70))
        tk.Scale(top, from_=10, to=100, orient="horizontal",
                 variable=bright_var, length=120, width=7,
                 bg=PANEL_COLOR, fg=HUD_CYAN, troughcolor=ACCENT_COLOR,
                 highlightthickness=0, bd=0, showvalue=False,
                 command=lambda v: self._apply_deck_brightness(int(float(v)))
                 ).grid(row=0, column=2, padx=4, sticky="w")
        top.columnconfigure(3, weight=1)

        f.rowconfigure(0, weight=0)
        f.rowconfigure(1, weight=1)
        # ── Area principale: griglia + editor ────────────────────────────────
        main = tk.Frame(f, bg=BG_COLOR)
        main.grid(row=1, column=0, sticky="nsew", padx=0, pady=0)
        main.columnconfigure(0, weight=1)
        main.rowconfigure(0, weight=0)   # tab pagine
        main.rowconfigure(1, weight=0)   # griglia tasti
        main.rowconfigure(2, weight=1)   # editor

        # ── Tab pagine ────────────────────────────────────────────────────────
        pages = self.config.setdefault("deck_idle_pages", [])
        while len(pages) < 1:
            pages.append([None] * n_keys)

        page_tab_fr = tk.Frame(main, bg=PANEL_COLOR)
        page_tab_fr.grid(row=0, column=0, columnspan=2, sticky="ew")
        self._deck_page_idx  = 0
        self._deck_page_btns = []
        self._deck_sel_key   = [None]   # [page_idx, key_idx] selezionato
        self._deck_key_cells = {}       # {key_idx: widget} — per l'anteprima live dell'icona

        def _page_empty(pi):
            return 0 <= pi < len(pages) and all(s is None for s in pages[pi])

        def _prune_empty_page(pi):
            """Toglie la pagina pi se e' vuota, a meno che sia l'unica
            rimasta. Ritorna True se l'ha tolta.

            Serve al bottone "+ Pag.": premuto per errore, o svuotato con
            "Svuota" fino a restare senza nessun tasto, prima restava li'
            per sempre - non c'era modo di rimuoverlo dall'interfaccia.
            """
            if len(pages) <= 1 or not _page_empty(pi):
                return False
            del pages[pi]
            # Un'azione "Cambia pagina" puo' puntare a un numero assoluto
            # (1-based): quelle che puntavano a una pagina dopo quella
            # tolta vanno scalate di uno, o finirebbero sulla pagina
            # sbagliata adesso che gli indici sono cambiati.
            for pg in pages:
                for slot in pg:
                    if slot and slot.get("action") == "page":
                        try:
                            n = int(slot.get("param", ""))
                            if n - 1 > pi:
                                slot["param"] = str(n - 1)
                        except ValueError:
                            pass
            save_config(self.config)
            if connected:
                sdk.refresh_all()
            return True

        def _switch_page(pi, rebuild=True):
            vecchia = self._deck_page_idx
            # Si lascia una pagina: se restava vuota (creata per errore, o
            # svuotata con "Svuota" senza rimettere nulla), sparisce da
            # sola invece di restare li' a occupare una scheda.
            if vecchia != pi and _prune_empty_page(vecchia):
                _rebuild_tabs()
                if pi > vecchia:
                    pi -= 1   # gli indici dopo quella tolta sono scalati
            self._deck_page_idx = pi
            self._deck_sel_key[0] = None
            for i, b in enumerate(self._deck_page_btns):
                b.config(bg=BG_COLOR if i == pi else PANEL_COLOR,
                         fg=HUD_CYAN if i == pi else MUTED_COLOR,
                         font=("TkFixedFont", 9, "bold") if i == pi
                              else ("TkFixedFont", 9))
            if rebuild:
                _rebuild_grid(pi)
                _clear_editor()

        def _add_page():
            pages.append([None] * n_keys)
            _rebuild_tabs()
            _switch_page(len(pages) - 1)

        def _rebuild_tabs():
            for w in page_tab_fr.winfo_children():
                w.destroy()
            self._deck_page_btns.clear()
            for pi in range(len(pages)):
                b = tk.Button(page_tab_fr, text=f"  Pag.{pi+1}  ",
                              font=("TkFixedFont", 9), relief="flat", bd=0,
                              padx=4, pady=6,
                              command=lambda p=pi: _switch_page(p))
                b.pack(side="left")
                self._deck_page_btns.append(b)
            tk.Button(page_tab_fr, text="+ Pag.",
                      font=("TkFixedFont", 8), bg=PANEL_COLOR, fg=MUTED_COLOR,
                      relief="flat", padx=6,
                      command=_add_page).pack(side="left", padx=6)
            # Indicatore del tasto selezionato: prima era un titolo dentro
            # l'editor del tasto (riga 0), qui accanto alla modalita' fa
            # risparmiare quella riga nella zona dei campi, dove lo spazio
            # verticale e' piu' prezioso. page_tab_fr viene ricreato ad
            # ogni aggiunta/rimozione di pagina, quindi anche questa
            # etichetta va ricreata qui; _show_editor()/_clear_editor()
            # la aggiornano in seguito senza pacchettarla di nuovo.
            self._deck_selkey_lbl = tk.Label(page_tab_fr, text="",
                                             font=("TkFixedFont", 8, "bold"),
                                             bg=PANEL_COLOR, fg=HUD_CYAN)
            self._deck_selkey_lbl.pack(side="left", padx=(10, 0))
            mode_txt = "preset" if (connected and sdk._mode == "preset") else "idle"
            mode_col = SUCCESS if mode_txt == "preset" else HUD_CYAN
            # pack(side="right") mette il primo impacchettato piu' a
            # destra: per leggere "Modalita' attuale: IDLE" da sinistra a
            # destra, il VALORE va impacchettato per primo (finisce
            # all'estrema destra) e la SCRITTA subito dopo (si mette alla
            # sua sinistra). L'ordine inverso dava "IDLE  Modalita'
            # attuale:", che si legge al contrario.
            self._deck_mode_lbl = tk.Label(page_tab_fr, text=mode_txt.upper(),
                     font=("TkFixedFont", 8, "bold"), bg=PANEL_COLOR,
                     fg=mode_col)
            self._deck_mode_lbl.pack(side="right", padx=(0,8))
            tk.Label(page_tab_fr, text="Modalità attuale:",
                     font=("TkFixedFont", 7), bg=PANEL_COLOR,
                     fg=MUTED_COLOR).pack(side="right", padx=4)

        # ── Griglia tasti ─────────────────────────────────────────────────────
        grid_outer = tk.Frame(main, bg=BG_COLOR)
        grid_outer.grid(row=1, column=0, sticky="ew", padx=4, pady=4)
        grid_outer.columnconfigure(0, weight=1)
        grid_outer.rowconfigure(0, weight=1)
        grid_fr = tk.Frame(grid_outer, bg=BG_COLOR)
        grid_fr.grid(row=0, column=0, sticky="nw")

        def _build_key_cell(pi, ki, slot):
            """Costruisce la cella-anteprima di un tasto e la piazza nella
            griglia. Isolata da _rebuild_grid perche' serve anche a
            _refresh_key_preview() per ridisegnare una sola cella con i
            valori non ancora salvati del form (l'icona appena scelta,
            prima che il campo venga completato e si salvi da solo),
            senza rifare tutta la griglia.
            """
            r, c = divmod(ki, cols)
            is_nav = False   # tutti i tasti sono liberamente configurabili
            label  = slot.get("label", "")
            color  = tuple(slot.get("color", [15,20,40]))
            bg_hex = "#{:02x}{:02x}{:02x}".format(*[
                max(0,min(255,int(x))) for x in color])
            sel = (self._deck_sel_key[0] == ki)
            border_col = HUD_CYAN if sel else (PANEL_COLOR if label else ACCENT_COLOR)

            cell = tk.Frame(grid_fr, bg=border_col,
                            width=76, height=70)
            cell.grid(row=r, column=c, padx=2, pady=2)
            cell.grid_propagate(False)

            inner = tk.Frame(cell, bg=bg_hex)
            inner.place(x=2, y=2, width=72, height=66)

            # Immagine miniatura
            img_path = slot.get("image")
            if img_path and os.path.isfile(img_path) and not is_nav:
                try:
                    thumb = load_thumbnail(img_path, 46)
                    if thumb:
                        photo = ImageTk.PhotoImage(thumb)
                        self._deck_idle_imgs = getattr(
                            self, "_deck_idle_imgs", [])
                        self._deck_idle_imgs.append(photo)
                        tk.Label(inner, image=photo,
                                 bg=bg_hex).pack(pady=(4,0))
                except Exception:
                    tk.Frame(inner, bg=bg_hex, height=32).pack(fill="x")
            else:
                # Icona azione
                if is_nav:
                    nav_txt = ("< Pag" if ki == n_keys-2
                               else f"> {pi+1}/{len(pages)}")
                    tk.Label(inner, text=nav_txt,
                             font=("TkFixedFont", 7), bg=bg_hex,
                             fg=MUTED_COLOR).pack(expand=True)
                else:
                    # Prova icona da file, fallback etichetta testo
                    _act = slot.get("action","")
                    if _act == "command":
                        icon_img = get_command_icon(slot.get("param",""), size=36)
                    else:
                        icon_img = get_deck_icon(_act, size=36)
                    if icon_img and not img_path:
                        try:
                            icon_photo = ImageTk.PhotoImage(icon_img)
                            self._deck_idle_imgs = getattr(
                                self,"_deck_idle_imgs",[])
                            self._deck_idle_imgs.append(icon_photo)
                            tk.Label(inner, image=icon_photo,
                                     bg=bg_hex).pack(pady=(4,0))
                        except Exception:
                            pass

            lbl_txt = (label[:9]+"...") if len(label)>9 else (label or "-")
            lbl_col = TEXT_COLOR if label else MUTED_COLOR
            tk.Label(inner, text=lbl_txt,
                     font=("TkFixedFont", 7, "bold" if label else ""),
                     bg=bg_hex, fg=lbl_col).pack()

            if not is_nav:
                for w in [cell, inner] + inner.winfo_children():
                    w.bind("<Button-1>",
                           lambda e, p=pi, k=ki: _select_key(p, k))
            return cell

        def _refresh_key_preview(pi, ki, preview_slot):
            """Ridisegna la sola cella ki con valori non ancora salvati.

            Usata quando si sceglie un'icona nell'editor: prima compariva
            solo dopo un salvataggio esplicito, perche' la griglia legge
            sempre da page[ki] (lo stato salvato) e non dal form. Qui si
            disegna la cella da un dizionario "di prova" costruito al
            volo, SENZA scrivere in page[ki]: quel campo si salvera' da
            solo quando verra' completato — se prima l'utente preme
            "Annulla", il file scelto non deve restare agganciato al
            tasto.
            """
            if pi != self._deck_page_idx:
                return   # pagina cambiata nel frattempo: anteprima non piu' valida
            vecchia = self._deck_key_cells.get(ki)
            if vecchia is not None:
                try:
                    vecchia.destroy()
                except Exception:
                    pass
            self._deck_key_cells[ki] = _build_key_cell(pi, ki, preview_slot)

        def _rebuild_grid(pi):
            for w in grid_fr.winfo_children():
                w.destroy()
            self._deck_key_cells = {}
            page = pages[pi]
            while len(page) < n_keys:
                page.append(None)
            # Altezza righe uniforme
            rows_count = (n_keys + cols - 1) // cols
            for ri in range(rows_count):
                grid_fr.rowconfigure(ri, weight=1, uniform="deck_row", minsize=74)
            for ci in range(cols):
                grid_fr.columnconfigure(ci, weight=1, uniform="deck_col", minsize=80)
            for ki in range(n_keys):
                slot = page[ki] or {}
                self._deck_key_cells[ki] = _build_key_cell(pi, ki, slot)

        def _select_key(pi, ki):
            self._deck_sel_key[0] = ki
            _rebuild_grid(pi)
            _show_editor(pi, ki)

        # ── Editor inline ─────────────────────────────────────────────────────
        editor_fr = tk.Frame(main, bg=BG_COLOR)
        editor_fr.grid(row=2, column=0, sticky="nsew", padx=8, pady=4)
        editor_fr.columnconfigure(1, weight=1)

        def _clear_editor():
            for w in editor_fr.winfo_children():
                w.destroy()
            tk.Label(editor_fr,
                     text="Clicca un tasto qui sopra per configurarlo",
                     font=("TkFixedFont", 9), bg=BG_COLOR,
                     fg=MUTED_COLOR).pack(pady=20)
            if hasattr(self, "_deck_selkey_lbl"):
                try:
                    self._deck_selkey_lbl.config(text="")
                except Exception:
                    pass
            # Rimuovi bottoni deck dalla barra globale
            if hasattr(self, '_bot_left'):
                for w in self._bot_left.winfo_children():
                    w.destroy()

        # Descrizioni chiare per ogni azione

        def _show_editor(pi, ki):
            for w in editor_fr.winfo_children():
                w.destroy()
            page = pages[pi]
            while len(page) <= ki:
                page.append(None)
            slot = page[ki] or {}
            # Scatto della situazione di partenza: "Annulla" torna qui,
            # non semplicemente chiude senza fare nulla — ora che ogni
            # campo si salva da solo, "chiudere senza fare nulla" non
            # significherebbe piu' niente, perche' qualcosa potrebbe
            # gia' essere stato scritto.
            _slot_originale    = page[ki]
            _snapshot_iniziale = dict(_slot_originale) if _slot_originale else None

            # Il titolo "Tasto N. - Pagina N." vive ora sulla riga dei tab
            # (self._deck_selkey_lbl), non piu' qui: libera una riga
            # nella zona campi, che e' quella con meno spazio.
            if hasattr(self, "_deck_selkey_lbl"):
                try:
                    self._deck_selkey_lbl.config(
                        text=f"Tasto {ki+1}  -  Pagina {pi+1}")
                except Exception:
                    pass

            vars_ = {}
            editor_fr.columnconfigure(1, weight=1)

            def _field_row(r, label, widget_fn):
                tk.Label(editor_fr, text=label,
                         font=("TkFixedFont", 8), bg=BG_COLOR,
                         fg=MUTED_COLOR, anchor="w", width=12
                         ).grid(row=r, column=0, sticky="w", pady=2, padx=(0,4))
                w = widget_fn(r)
                return w

            # ── Label (con posizione, sulla stessa riga) ─────────────────────
            label_var = tk.StringVar(value=slot.get("label", ""))
            vars_["label"] = label_var
            labelpos_val = slot.get("label_pos", "middle")
            labelpos_var = tk.StringVar(value=labelpos_val)
            vars_["label_pos"] = labelpos_var
            def _mk_label(r):
                fr = tk.Frame(editor_fr, bg=BG_COLOR)
                fr.grid(row=r, column=1, columnspan=2, sticky="ew")
                # Solo l'entry si allarga: i tre radio hanno larghezza
                # fissa, o si allargherebbero anche loro lasciando un
                # vuoto brutto fra il testo e il pallino.
                fr.columnconfigure(0, weight=1)
                e = tk.Entry(fr, textvariable=label_var,
                             font=("TkFixedFont", 9),
                             bg=ACCENT_COLOR, fg=TEXT_COLOR,
                             insertbackground=TEXT_COLOR,
                             relief="flat", bd=3)
                e.grid(row=0, column=0, sticky="ew", ipady=3, padx=(0,6))
                e.bind("<FocusOut>", lambda ev: _save_key())
                e.bind("<Return>",   lambda ev: _save_key())
                for ci, (val, txt) in enumerate(
                        [("top","Alto"), ("middle","In mezzo"), ("bottom","Basso")]):
                    tk.Radiobutton(fr, text=txt,
                                   variable=labelpos_var, value=val,
                                   font=("TkFixedFont", 8),
                                   bg=BG_COLOR, fg=TEXT_COLOR,
                                   selectcolor=BG_COLOR,
                                   activebackground=BG_COLOR,
                                   activeforeground=HUD_CYAN,
                                   command=lambda: (_live_preview(), _save_key())
                                   ).grid(row=0, column=ci+1, sticky="w",
                                          padx=(0,2))
                return fr
            _field_row(0, "Label:", _mk_label)

            # ── Image ────────────────────────────────────────────────────────
            img_var = tk.StringVar(value=slot.get("image", "") or "")
            vars_["image"] = img_var

            def _live_preview():
                """Ricostruisce uno slot "di prova" dai valori CORRENTI
                del form (non ancora salvati) e ridisegna solo quella
                cella. Non scrive in page[ki]: se poi si preme "Annulla"
                niente resta agganciato al tasto — la cella torna allo
                stato salvato al prossimo _rebuild_grid().

                Usata sia quando si sceglie un file immagine, sia quando
                si cambia azione o si sceglie un comando dal menu a
                tendina: senza, l'icona automatica di un comando si
                vedeva solo a campo completato, non appena scelto.
                action_var e param_var sono definiti piu' sotto in questa
                stessa funzione, ma essendo una chiusura li legge al
                momento in cui viene chiamata, non a quando e' stata
                definita — e viene chiamata solo dopo che tutto il form
                e' gia' costruito.
                """
                preview = dict(slot)
                preview["action"] = action_var.get()
                preview["param"]  = param_var.get().strip()
                preview["image"]  = img_var.get().strip() or None
                _refresh_key_preview(pi, ki, preview)
            img_var.trace_add("write", lambda *_a: _live_preview())

            def _mk_image(r):
                fr = tk.Frame(editor_fr, bg=BG_COLOR)
                fr.grid(row=r, column=1, columnspan=2, sticky="ew")
                fr.columnconfigure(0, weight=1)
                img_entry = tk.Entry(fr, textvariable=img_var,
                         font=("TkFixedFont", 8),
                         bg=ACCENT_COLOR, fg=TEXT_COLOR,
                         insertbackground=TEXT_COLOR,
                         relief="flat", bd=3)
                img_entry.grid(row=0, column=0, sticky="ew", ipady=2)
                img_entry.bind("<FocusOut>", lambda ev: _save_key())
                img_entry.bind("<Return>",   lambda ev: _save_key())
                tk.Button(fr, text="...",
                          font=("TkFixedFont", 8), bg=PANEL_COLOR, fg=TEXT_COLOR,
                          relief="flat", padx=6,
                          command=lambda: (img_var.set(
                              browse_icon_hud(self.win,
                                  title="Scegli immagine tasto",
                                  initial_dir=(os.path.dirname(img_var.get())
                                               if img_var.get()
                                               else _deck_icons_dir()))
                              or img_var.get()), _save_key())
                          ).grid(row=0, column=1, padx=(4,0), ipady=2)
                tk.Button(fr, text="x",
                          font=("TkFixedFont", 8), bg=PANEL_COLOR, fg=MUTED_COLOR,
                          relief="flat",
                          command=lambda: (img_var.set(""), _save_key())
                          ).grid(row=0, column=2, padx=(2,0), ipady=2)
                return fr
            _field_row(1, "Image:", _mk_image)

            # ── Colore ───────────────────────────────────────────────────────
            color_val = slot.get("color", [15, 20, 40])
            color_var = tk.StringVar(value=",".join(str(x) for x in color_val))
            vars_["color"] = color_var
            def _mk_color(r):
                fr = tk.Frame(editor_fr, bg=BG_COLOR)
                fr.grid(row=r, column=1, columnspan=2, sticky="ew")
                color_entry = tk.Entry(fr, textvariable=color_var,
                         font=("TkFixedFont", 9), width=12,
                         bg=ACCENT_COLOR, fg=TEXT_COLOR,
                         insertbackground=TEXT_COLOR,
                         relief="flat", bd=3)
                color_entry.pack(side="left", ipady=3)
                color_entry.bind("<FocusOut>", lambda ev: _save_key())
                color_entry.bind("<Return>",   lambda ev: _save_key())
                tk.Label(fr, text="  (0-255 per R,G,B)",
                         font=("TkFixedFont", 7), bg=BG_COLOR,
                         fg=MUTED_COLOR).pack(side="left")
                return fr
            _field_row(2, "Colore R,G,B:", _mk_color)

            # Separatore
            tk.Frame(editor_fr, bg=ACCENT_COLOR, height=1
                     ).grid(row=3, column=0, columnspan=3, sticky="ew", pady=4)

            # ── Azione ───────────────────────────────────────────────────────
            tk.Label(editor_fr, text="Azione:",
                     font=("TkFixedFont", 8), bg=BG_COLOR,
                     fg=MUTED_COLOR, anchor="w", width=12
                     ).grid(row=4, column=0, sticky="w", pady=2, padx=(0,4))

            ACTION_ROWS = [
                # (action_key, label_display, param_label, param_hint, param_type)
                ("folder",  "Apri cartella",           "Percorso:", "/home/user/Documenti", "folder"),
                ("app",     "Apri applicazione",       "Comando:",  "gimp  /  firefox",     "entry"),
                ("hotkey",  "Scorciatoia tastiera",    "Tasto:",    "ctrl+c  ctrl+alt+t",   "hotkey_capture"),
                ("url",     "Apri URL",                "URL:",      "https://www.esempio.it","entry"),
                ("mute",    "Muto/smuto audio",        "",          "",                      "none"),
                ("sorter",  "Image Sorter su cartella","Cartella:", "/home/user/Foto",       "folder"),
                ("page",    "Cambia pagina",           "N. pagina:","1  (numero pagina)",    "entry"),
                ("text",    "Scrivi testo",            "Testo:",    "testo da digitare",     "text_area"),
                ("command", "Comando Image Sorter",    "Comando:",  "",                      "command_menu"),
                ("rating",      "Valutazione (stella)", "Stelle:",  "",                      "rating_menu"),
                ("color_label", "Colore etichetta",     "Colore:",  "",                      "color_menu"),
            ]
            action_map   = {a[0]: a for a in ACTION_ROWS}

            cur_action = slot.get("action", "folder")
            action_var = tk.StringVar(value=cur_action)

            # Radio buttons per azione
            radio_fr = tk.Frame(editor_fr, bg=BG_COLOR)
            def _on_action_change():
                """Cambiare azione non salva subito da solo — se il
                parametro vecchio (un percorso, una scorciatoia...) resta
                ancora nella casella mentre il campo si ricostruisce per
                il nuovo tipo, salvarlo comunque scriverebbe una
                combinazione senza senso (es. un percorso di cartella
                salvato come scorciatoia da tastiera). Si salva solo se
                la nuova azione non ha affatto bisogno di un parametro
                (es. "Muto/smuto"): li' non c'e' nulla da aspettare.
                Per tutte le altre, il salvataggio arriva quando il
                nuovo campo parametro viene davvero completato.
                """
                _update_param_row()
                _live_preview()
                _riga = action_map.get(action_var.get())
                if _riga and _riga[4] == "none":
                    _save_key()

            radio_fr.grid(row=4, column=1, columnspan=2, sticky="ew")
            for ai, (akey, alabel, *_) in enumerate(ACTION_ROWS):
                rb = tk.Radiobutton(radio_fr, text=alabel,
                                    variable=action_var, value=akey,
                                    font=("TkFixedFont", 8),
                                    bg=BG_COLOR, fg=TEXT_COLOR,
                                    selectcolor=BG_COLOR,
                                    activebackground=BG_COLOR,
                                    activeforeground=HUD_CYAN,
                                    command=_on_action_change)
                rb.grid(row=ai//3, column=ai%3, sticky="w", padx=4, pady=1)

            # ── Parametro dinamico ───────────────────────────────────────────
            param_var  = tk.StringVar(value=slot.get("param", ""))
            param_fr   = tk.Frame(editor_fr, bg=BG_COLOR)
            param_fr.grid(row=5, column=0, columnspan=3, sticky="ew", pady=(4,0))
            param_fr.columnconfigure(1, weight=1)
            vars_["param"] = param_var
            _param_widgets = [None]  # riferimento al widget corrente

            def _update_param_row():
                for w in param_fr.winfo_children():
                    w.destroy()
                akey = action_var.get()
                if akey not in action_map:
                    return
                _, _, plabel, phint, ptype = action_map[akey]
                if ptype == "none":
                    tk.Label(param_fr, text="(nessun parametro richiesto)",
                             font=("TkFixedFont", 7), bg=BG_COLOR,
                             fg=MUTED_COLOR).grid(row=0, column=0,
                                                  columnspan=3, sticky="w")
                    return
                tk.Label(param_fr, text=plabel,
                         font=("TkFixedFont", 8), bg=BG_COLOR,
                         fg=MUTED_COLOR, anchor="w", width=12
                         ).grid(row=0, column=0, sticky="w", padx=(0,4))
                if ptype == "text_area":
                    txt = tk.Text(param_fr, font=("TkFixedFont", 9),
                                  bg=ACCENT_COLOR, fg=TEXT_COLOR,
                                  insertbackground=TEXT_COLOR,
                                  relief="flat", bd=3, height=4, width=28)
                    txt.grid(row=0, column=1, columnspan=2, sticky="ew")
                    txt.insert("1.0", param_var.get())
                    txt.bind("<Button-4>", lambda e: txt.yview_scroll(-1, "units"))
                    txt.bind("<Button-5>", lambda e: txt.yview_scroll(1, "units"))
                    # Aggiorna param_var in tempo reale (per l'anteprima),
                    # ma salva solo quando si esce dal campo — non ad ogni
                    # lettera, altrimenti scriverebbe su disco e spingerebbe
                    # l'immagine al tasto fisico ad ogni battuta.
                    txt.bind("<KeyRelease>",
                             lambda e: param_var.set(txt.get("1.0", "end-1c")))
                    txt.bind("<FocusOut>", lambda e: _save_key())
                    _param_widgets[0] = txt
                elif ptype == "command_menu":
                    # param_var conserva l'id del comando (es. "rotate_cw"),
                    # non l'etichetta italiana: e' quello che _deck_execute_
                    # action() cerca in DECK_COMMAND_FUNCS. Il menu mostra
                    # le etichette e traduce dall'una all'altra.
                    id_per_etichetta = {lbl: cid for cid, lbl in
                                        DECK_COMMAND_LABELS.items()}
                    etichette = list(DECK_COMMAND_LABELS.values())
                    cmd_var = tk.StringVar(
                        value=DECK_COMMAND_LABELS.get(param_var.get(), ""))
                    cb = ttk.Combobox(param_fr, textvariable=cmd_var,
                                      values=etichette, state="readonly",
                                      font=("TkFixedFont", 9), width=30)
                    cb.grid(row=0, column=1, columnspan=2, sticky="ew")
                    cb.bind("<<ComboboxSelected>>",
                            lambda e: (param_var.set(
                                id_per_etichetta.get(cmd_var.get(), "")),
                                       _live_preview(), _save_key()))
                    _param_widgets[0] = cb
                elif ptype == "rating_menu":
                    # param_var conserva il numero come stringa ("1".."5"),
                    # letto da _render_rating_color_key/_deck_execute_action.
                    etichette_r = [f"{n} stell{'a' if n==1 else 'e'}" for n in range(1,6)]
                    id_per_etichetta_r = {et: str(n) for et, n in zip(etichette_r, range(1,6))}
                    cur_lbl_r = next((et for et, n in zip(etichette_r, range(1,6))
                                     if str(n) == param_var.get()), etichette_r[0])
                    rate_var = tk.StringVar(value=cur_lbl_r)
                    cb = ttk.Combobox(param_fr, textvariable=rate_var,
                                      values=etichette_r, state="readonly",
                                      font=("TkFixedFont", 9), width=30)
                    cb.grid(row=0, column=1, columnspan=2, sticky="ew")
                    cb.bind("<<ComboboxSelected>>",
                            lambda e: (param_var.set(
                                id_per_etichetta_r.get(rate_var.get(), "1")),
                                       _live_preview(), _save_key()))
                    if not param_var.get():
                        param_var.set("1")
                    _param_widgets[0] = cb
                elif ptype == "color_menu":
                    # param_var conserva l'id colore (es. "red"), lo stesso
                    # usato da metadata_store — il menu mostra il nome
                    # italiano e traduce dall'uno all'altro.
                    _labels_src = (metadata_store.COLOR_LABELS
                                  if _METADATA_STORE_AVAILABLE else [])
                    id_per_etichetta_c = {name: cid for cid, name, _hex in _labels_src}
                    etichette_c = [name for _cid, name, _hex in _labels_src]
                    nome_per_id = {cid: name for cid, name, _hex in _labels_src}
                    color_var = tk.StringVar(
                        value=nome_per_id.get(param_var.get(),
                                              etichette_c[0] if etichette_c else ""))
                    cb = ttk.Combobox(param_fr, textvariable=color_var,
                                      values=etichette_c, state="readonly",
                                      font=("TkFixedFont", 9), width=30)
                    cb.grid(row=0, column=1, columnspan=2, sticky="ew")
                    cb.bind("<<ComboboxSelected>>",
                            lambda e: (param_var.set(
                                id_per_etichetta_c.get(color_var.get(), "")),
                                       _live_preview(), _save_key()))
                    if not param_var.get() and etichette_c:
                        param_var.set(id_per_etichetta_c[etichette_c[0]])
                    _param_widgets[0] = cb
                elif ptype == "hotkey_capture":
                    pf = tk.Frame(param_fr, bg=BG_COLOR)
                    pf.grid(row=0, column=1, columnspan=2, sticky="ew")
                    pf.columnconfigure(0, weight=1)
                    e = tk.Entry(pf, textvariable=param_var,
                                 font=("TkFixedFont", 9),
                                 bg=ACCENT_COLOR, fg=TEXT_COLOR,
                                 insertbackground=TEXT_COLOR,
                                 relief="flat", bd=3)
                    e.grid(row=0, column=0, sticky="ew", ipady=3)
                    e.bind("<Return>",   lambda ev: _save_key())
                    e.bind("<FocusOut>", lambda ev: _save_key())

                    # Resta modificabile a mano come prima — il bottone
                    # "Registra" e' solo un modo IN PIU' di riempirlo,
                    # non sostituisce la scrittura diretta.
                    _cattura = {"attiva": False}
                    _MODIFICATORI_SOLI = {
                        "Control_L", "Control_R", "Shift_L", "Shift_R",
                        "Alt_L", "Alt_R", "Meta_L", "Meta_R",
                        "Super_L", "Super_R", "ISO_Level3_Shift",
                        "Caps_Lock",
                    }

                    def _stringa_da_evento(ev):
                        """Costruisce la combinazione (es. "ctrl+c") dal
                        vero tasto premuto, leggendo i modificatori
                        davvero attivi in quel momento — mai scritta a
                        mano, quindi mai ambigua fra "C maiuscola" e
                        "Ctrl+C": xdotool distingue le due cose, chi
                        scrive a mano puo' sbagliarsi, la cattura no,
                        perche' rispecchia esattamente cio' che e' stato
                        premuto fisicamente.
                        """
                        if ev.keysym in _MODIFICATORI_SOLI:
                            return None   # solo un modificatore: resta in ascolto
                        if ev.keysym == "Escape":
                            return ""     # convenzione: Escape annulla
                        parti = []
                        # Bit dei modificatori nello stato dell'evento:
                        # valori standard X11 (Shift=0x1, Control=0x4,
                        # Mod1/Alt=0x8, Mod4/Super=0x40).
                        if ev.state & 0x0004: parti.append("ctrl")
                        if ev.state & 0x0008: parti.append("alt")
                        if ev.state & 0x0001: parti.append("shift")
                        if ev.state & 0x0040: parti.append("super")
                        parti.append(ev.keysym)
                        return "+".join(parti)

                    def _termina_cattura(nuovo=None):
                        _cattura["attiva"] = False
                        e.config(bg=ACCENT_COLOR)
                        btn_cattura.config(text="Registra", bg=PANEL_COLOR)
                        try:
                            e.unbind("<KeyPress>")
                        except Exception:
                            pass
                        if nuovo:
                            param_var.set(nuovo)
                            _live_preview()
                            _save_key()

                    def _on_key_capture(ev):
                        risultato = _stringa_da_evento(ev)
                        if risultato is None:
                            return "break"   # solo un modificatore: resta in ascolto
                        _termina_cattura(risultato)
                        return "break"   # impedisce al tasto di finire
                                         # scritto anche come testo normale

                    def _avvia_cattura():
                        if _cattura["attiva"]:
                            _termina_cattura()   # un secondo click annulla
                            return
                        _cattura["attiva"] = True
                        e.config(bg=HIGHLIGHT)
                        btn_cattura.config(text="Premi un tasto...", bg=HIGHLIGHT)
                        e.focus_set()
                        e.bind("<KeyPress>", _on_key_capture)

                    btn_cattura = tk.Button(pf, text="Registra",
                                            font=("TkFixedFont", 8),
                                            bg=PANEL_COLOR, fg=TEXT_COLOR,
                                            relief="flat", padx=6,
                                            command=_avvia_cattura)
                    btn_cattura.grid(row=0, column=1, padx=(4,0), ipady=3)

                    if phint:
                        tk.Label(param_fr, text="Es: " + phint,
                                 font=("TkFixedFont", 7), bg=BG_COLOR,
                                 fg=MUTED_COLOR
                                 ).grid(row=1, column=1, columnspan=2,
                                        sticky="w", pady=(1,0))
                    _param_widgets[0] = e
                else:
                    pf = tk.Frame(param_fr, bg=BG_COLOR)
                    pf.grid(row=0, column=1, columnspan=2, sticky="ew")
                    pf.columnconfigure(0, weight=1)
                    e = tk.Entry(pf, textvariable=param_var,
                                 font=("TkFixedFont", 9),
                                 bg=ACCENT_COLOR, fg=TEXT_COLOR,
                                 insertbackground=TEXT_COLOR,
                                 relief="flat", bd=3)
                    e.grid(row=0, column=0, sticky="ew", ipady=3)
                    e.bind("<Return>",   lambda ev: _save_key())
                    e.bind("<FocusOut>", lambda ev: _save_key())
                    if ptype in ("folder",):
                        def _br():
                            d = browse_folder_hud(self.win,
                                title="Scegli cartella",
                                initial_dir=param_var.get() or os.path.expanduser("~"),
                                config=self.config)
                            if d:
                                param_var.set(d)
                                _save_key()
                        tk.Button(pf, text="...",
                                  font=("TkFixedFont", 8), bg=PANEL_COLOR,
                                  fg=TEXT_COLOR, relief="flat", padx=6,
                                  command=_br
                                  ).grid(row=0, column=1, padx=(4,0), ipady=3)
                    if phint:
                        tk.Label(param_fr, text="Es: " + phint,
                                 font=("TkFixedFont", 7), bg=BG_COLOR,
                                 fg=MUTED_COLOR
                                 ).grid(row=1, column=1, columnspan=2,
                                        sticky="w", pady=(1,0))
                    _param_widgets[0] = e

            _update_param_row()

            # Separatore
            tk.Frame(editor_fr, bg=ACCENT_COLOR, height=1
                     ).grid(row=6, column=0, columnspan=3, sticky="ew", pady=6)

            # ── Bottoni nella barra globale in basso ─────────────────────
            def _save_key():
                try:
                    raw = [max(0, min(255, int(x.strip())))
                           for x in color_var.get().split(",")]
                    if len(raw) != 3:
                        raise ValueError
                except ValueError:
                    raw = [15, 20, 40]
                # Il parametro va "ripulito" dagli spazi ai margini per la
                # maggior parte delle azioni (un percorso o una
                # scorciatoia con uno spazio in piu' per errore e' quasi
                # sempre un refuso) — ma per "Scrivi testo" NO: uno spazio
                # iniziale o finale puo' essere voluto (per far seguire il
                # testo a quello gia' scritto, per esempio), e togliendolo
                # sempre un testo che finiva o iniziava solo con spazi
                # poteva ridursi a niente.
                _param_raw = param_var.get()
                page[ki] = {
                    "label":     label_var.get().strip(),
                    "action":    action_var.get(),
                    "param":     _param_raw if action_var.get() == "text"
                                else _param_raw.strip(),
                    "color":     raw,
                    "image":     img_var.get().strip() or None,
                    "label_pos": labelpos_var.get(),
                }
                save_config(self.config)
                if connected:
                    sdk.refresh_all()
                _rebuild_grid(pi)

            def _clear_key():
                page[ki] = None
                save_config(self.config)
                if connected:
                    sdk.refresh_all()
                # Se questo era l'ultimo tasto della pagina, la pagina
                # sparisce da sola: e' il caso piu' diretto in cui capita,
                # non solo lasciandola vuota e cambiando scheda.
                if _prune_empty_page(pi):
                    _rebuild_tabs()
                    nuovo = min(pi, len(pages) - 1)
                    # Aggiornato PRIMA di chiamare _switch_page: altrimenti
                    # quella funzione vedrebbe ancora l'indice appena tolto
                    # come "pagina da lasciare" e proverebbe a svuotare
                    # anche quella che vi e' scivolata sopra.
                    self._deck_page_idx = nuovo
                    _switch_page(nuovo)
                else:
                    _clear_editor()
                    _rebuild_grid(pi)

            def _annulla_modifiche():
                """Torna esattamente a com'era il tasto quando questo
                editor si e' aperto — non piu' "chiudi senza aver fatto
                nulla" (con il salvataggio automatico, qualcosa potrebbe
                gia' essere stato scritto), ma un vero ripristino allo
                scatto preso in _show_editor().
                """
                page[ki] = dict(_snapshot_iniziale) if _snapshot_iniziale else None
                save_config(self.config)
                if connected:
                    sdk.refresh_all()
                _rebuild_grid(pi)
                _clear_editor()

            # Aggiorna _bot_left con i bottoni contestuali
            for w in self._bot_left.winfo_children():
                w.destroy()
            tk.Button(self._bot_left, text="Svuota",
                      font=("TkFixedFont", 9),
                      bg=WARNING, fg="white", relief="flat", padx=8,
                      command=_clear_key).pack(side="left", padx=(10,4),
                                               pady=6, ipady=3)
            tk.Button(self._bot_left, text="Annulla",
                      font=("TkFixedFont", 9),
                      bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=8,
                      command=_annulla_modifiche).pack(side="left", pady=6, ipady=3)
            tk.Label(self._bot_left, text="  (ogni campo si salva da solo)",
                     font=("TkFixedFont", 7), bg=PANEL_COLOR, fg=MUTED_COLOR
                     ).pack(side="left", padx=(6,0))

        _rebuild_tabs()
        _switch_page(0)
        _clear_editor()

    def _apply_deck_brightness(self, val):
        self.config["deck_brightness"] = val
        save_config(self.config)
        sdk = getattr(self.sorter, '_stream_deck', None)
        if sdk and sdk.is_active():
            try: sdk.deck.set_brightness(val)
            except Exception: pass

    def _edit_idle_key(self, page_idx, key_idx):
        """Apre il popup di configurazione per un tasto idle."""
        pages  = self.config.setdefault("deck_idle_pages", [])
        while len(pages) <= page_idx:
            pages.append([])
        page = pages[page_idx]
        while len(page) <= key_idx:
            page.append(None)

        slot = page[key_idx] or {}

        win = tk.Toplevel(self.win)
        win.withdraw()
        win.title(f"Tasto {key_idx+1} — Pagina {page_idx+1}")
        win.configure(bg=BG_COLOR)
        win.resizable(False, False)
        win.transient(self.win)
        hud_apply(win)

        frm = tk.Frame(win, bg=BG_COLOR)
        frm.pack(padx=16, pady=12, fill="x")
        frm.columnconfigure(1, weight=1)

        # Etichetta
        tk.Label(frm, text="Etichetta:", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(row=0, column=0, sticky="w", pady=4)
        label_var = tk.StringVar(value=slot.get("label", ""))
        tk.Entry(frm, textvariable=label_var, font=("TkFixedFont", 9),
                 bg=ACCENT_COLOR, fg=TEXT_COLOR, insertbackground=TEXT_COLOR,
                 relief="flat", bd=3).grid(row=0, column=1, sticky="ew", ipady=3)

        # Azione
        tk.Label(frm, text="Azione:", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(row=1, column=0, sticky="w", pady=4)
        action_var = tk.StringVar(value=slot.get("action", "folder"))
        action_frame = tk.Frame(frm, bg=BG_COLOR)
        action_frame.grid(row=1, column=1, sticky="ew")
        action_menu = ttk.Combobox(action_frame, textvariable=action_var,
                                   values=[k for k,v in IDLE_ACTION_TYPES],
                                   state="readonly", width=16)
        action_menu.pack(side="left")
        # Mostra nome descrittivo
        desc_lbl = tk.Label(action_frame, text="",
                            font=("TkFixedFont", 7), bg=BG_COLOR, fg=MUTED_COLOR)
        desc_lbl.pack(side="left", padx=6)
        def _upd_desc(*_):
            desc_lbl.config(text=IDLE_ACTION_LABELS.get(action_var.get(), ""))
        action_var.trace_add("write", _upd_desc)
        _upd_desc()

        # Parametro
        tk.Label(frm, text="Parametro:", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(row=2, column=0, sticky="w", pady=4)
        param_var = tk.StringVar(value=slot.get("param", ""))
        param_fr = tk.Frame(frm, bg=BG_COLOR)
        param_fr.grid(row=2, column=1, sticky="ew")
        param_fr.columnconfigure(0, weight=1)
        tk.Entry(param_fr, textvariable=param_var, font=("TkFixedFont", 9),
                 bg=ACCENT_COLOR, fg=TEXT_COLOR, insertbackground=TEXT_COLOR,
                 relief="flat", bd=3).grid(row=0, column=0, sticky="ew", ipady=3)
        def _browse_param():
            a = action_var.get()
            if a in ("folder", "sorter"):
                d = browse_folder_hud(win, title="Scegli cartella",
                    initial_dir=param_var.get() or os.path.expanduser("~"),
                    config=self.config)
                if d: param_var.set(d)
            elif a in ("app",):
                f = browse_file_hud(win, title="Scegli programma",
                    filetypes=[("Eseguibili","*"), ("Tutti i file","*")])
                if f: param_var.set(f)
        tk.Button(param_fr, text="...",
                  font=("TkFixedFont", 8), bg=PANEL_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=6,
                  command=_browse_param).grid(row=0, column=1, padx=(4,0), ipady=3)

        # Immagine sfondo tasto
        tk.Label(frm, text="Immagine tasto:", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(row=3, column=0, sticky="w", pady=4)
        img_var = tk.StringVar(value=slot.get("image", "") or "")
        img_fr = tk.Frame(frm, bg=BG_COLOR)
        img_fr.grid(row=3, column=1, sticky="ew")
        img_fr.columnconfigure(0, weight=1)
        tk.Entry(img_fr, textvariable=img_var, font=("TkFixedFont", 8),
                 bg=ACCENT_COLOR, fg=TEXT_COLOR, insertbackground=TEXT_COLOR,
                 relief="flat", bd=3).grid(row=0, column=0, sticky="ew", ipady=2)
        def _browse_img():
            f = browse_icon_hud(win, title="Scegli immagine tasto",
                               initial_dir=(os.path.dirname(img_var.get())
                                            if img_var.get()
                                            else _deck_icons_dir()))
            if f: img_var.set(f)
        tk.Button(img_fr, text="...", font=("TkFixedFont", 8),
                  bg=PANEL_COLOR, fg=TEXT_COLOR, relief="flat", padx=6,
                  command=_browse_img).grid(row=0, column=1, padx=(4,0), ipady=2)
        tk.Button(img_fr, text="x", font=("TkFixedFont", 8),
                  bg=PANEL_COLOR, fg=MUTED_COLOR, relief="flat",
                  command=lambda: img_var.set("")
                  ).grid(row=0, column=2, padx=(2,0), ipady=2)

        # Colore sfondo
        tk.Label(frm, text="Colore (R,G,B):", font=("TkFixedFont", 8),
                 bg=BG_COLOR, fg=MUTED_COLOR).grid(row=4, column=0, sticky="w", pady=4)
        color_val = slot.get("color", [15,20,40])
        color_var = tk.StringVar(value=",".join(str(x) for x in color_val))
        tk.Entry(frm, textvariable=color_var, font=("TkFixedFont", 9),
                 bg=ACCENT_COLOR, fg=TEXT_COLOR, insertbackground=TEXT_COLOR,
                 relief="flat", bd=3, width=14).grid(row=4, column=1, sticky="w", ipady=3)

        msg = tk.Label(win, text="", font=("TkFixedFont", 8), bg=BG_COLOR, fg=HIGHLIGHT)
        msg.pack(padx=16)

        def _save():
            try:
                raw_color = [max(0,min(255,int(x.strip())))
                             for x in color_var.get().split(",")]
                if len(raw_color) != 3:
                    raise ValueError
            except ValueError:
                raw_color = [15,20,40]
            page[key_idx] = {
                "label":  label_var.get().strip(),
                "action": action_var.get(),
                "param":  param_var.get().strip(),
                "color":  raw_color,
                "image":  img_var.get().strip() or None,
            }
            save_config(self.config)
            win.destroy()
            self._build_deck_tab()   # aggiorna la griglia

        def _clear():
            page[key_idx] = None
            save_config(self.config)
            win.destroy()
            self._build_deck_tab()

        bf = tk.Frame(win, bg=BG_COLOR)
        bf.pack(padx=16, pady=(4,14))
        tk.Button(bf, text="Salva", font=("TkFixedFont", 9, "bold"),
                  bg=SUCCESS, fg="white", relief="flat", padx=12,
                  command=_save).pack(side="left", padx=(0,8), ipady=4)
        tk.Button(bf, text="Svuota tasto", font=("TkFixedFont", 9),
                  bg=WARNING, fg="white", relief="flat", padx=8,
                  command=_clear).pack(side="left", padx=(0,8), ipady=4)
        tk.Button(bf, text="Annulla", font=("TkFixedFont", 9),
                  bg=ACCENT_COLOR, fg=TEXT_COLOR, relief="flat", padx=8,
                  command=win.destroy).pack(side="left", ipady=4)
        win.bind("<Return>", lambda e: _save())
        win.bind("<Escape>", lambda e: win.destroy())

        win.update_idletasks()
        pw, ph = win.winfo_reqwidth(), win.winfo_reqheight()
        px = self.win.winfo_rootx() + (self.win.winfo_width()  - pw) // 2
        py = self.win.winfo_rooty() + (self.win.winfo_height() - ph) // 2
        win.geometry(f"+{max(0,px)}+{max(0,py)}")
        win.deiconify()
        win.grab_set()

    def _build_keys_tab(self):
        """Tab scorciatoie da tastiera."""
        lang = self.config.get("language", "it")
        f = self._content
        f.columnconfigure(0, weight=1)
        f.rowconfigure(0, weight=1)

        outer = tk.Frame(f, bg=BG_COLOR)
        outer.grid(row=0, column=0, sticky="nsew")
        outer.columnconfigure(0, weight=1)
        outer.rowconfigure(0, weight=1)

        canvas = tk.Canvas(outer, bg=BG_COLOR, highlightthickness=0)
        vsb = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")

        inner = tk.Frame(canvas, bg=BG_COLOR)
        iid = canvas.create_window((0,0), window=inner, anchor="nw")
        canvas.bind("<Configure>",
                    lambda e: canvas.itemconfig(iid, width=e.width))
        inner.bind("<Configure>",
                   lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        def _scroll_up(e): canvas.yview_scroll(-1, "units")
        def _scroll_dn(e): canvas.yview_scroll( 1, "units")
        # Bind su canvas E su inner (e tutti i figli tramite bind_all temporaneo)
        canvas.bind("<Button-4>", _scroll_up)
        canvas.bind("<Button-5>", _scroll_dn)
        canvas.bind("<MouseWheel>",
                    lambda e: canvas.yview_scroll(-1 if e.delta > 0 else 1, "units"))
        inner.bind("<Button-4>", _scroll_up)
        inner.bind("<Button-5>", _scroll_dn)
        # Propaga scroll dai widget figli che verranno creati
        def _bind_scroll_to_children(widget):
            widget.bind("<Button-4>", _scroll_up)
            widget.bind("<Button-5>", _scroll_dn)
        # Chiama dopo che i widget sono stati creati
        inner.bind("<Configure>",
                   lambda e: [_bind_scroll_to_children(w)
                               for w in inner.winfo_children()
                               for w in [w] + list(w.winfo_children())],
                   add=True)

        shortcuts = (_SHORTCUTS_DATA or {}).get(lang,
                     (_SHORTCUTS_DATA or {}).get("it", []))

        for section, pairs in shortcuts:
            tk.Label(inner, text=section,
                     font=("TkFixedFont", 10, "bold"),
                     bg=BG_COLOR, fg=HUD_CYAN,
                     anchor="w").pack(fill="x", padx=20, pady=(14,2))
            tk.Frame(inner, bg=ACCENT_COLOR, height=1).pack(fill="x", padx=20)
            for key, desc in pairs:
                row = tk.Frame(inner, bg=BG_COLOR)
                row.pack(fill="x", padx=20, pady=1)
                tk.Label(row, text=key,
                         font=("TkFixedFont", 9, "bold"),
                         bg=BG_COLOR, fg=TEXT_COLOR,
                         width=22, anchor="w").pack(side="left")
                tk.Label(row, text=desc,
                         font=("TkFixedFont", 9),
                         bg=BG_COLOR, fg=MUTED_COLOR,
                         anchor="w").pack(side="left")

    def _apply_lang(self):
        """Salva la lingua e riapre la finestra impostazioni tradotta."""
        lang = self._lang_var.get()
        self.config["language"] = lang
        save_config(self.config)
        # Riapri le impostazioni con la nuova lingua
        self.sorter._settings_dialog = None
        self.win.destroy()
        # Ricostruisci la toolbar principale (hardcoded IT)
        try:
            self.sorter._build_toolbar()
        except Exception:
            pass
        # Riapri impostazioni con la nuova lingua
        self.sorter.root.after(50, lambda:
            self.sorter._open_settings(tab="info"))

    def _build_private_tab(self):
        """Tab Privato: gestione cartelle private."""
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)

        tk.Label(f, text="Cartelle private",
                 font=("TkFixedFont", 11, "bold"),
                 bg=BG_COLOR, fg=HUD_CYAN
                 ).pack(padx=24, pady=(20,2), anchor="w")
        tk.Label(f,
                 text="Le cartelle qui elencate richiedono conferma prima di essere"
                      " visualizzate.\n"
                      "L'elenco si conserva tra le sessioni; lo sblocco no.",
                 font=("TkFixedFont", 8), bg=BG_COLOR, fg=MUTED_COLOR,
                 justify="left"
                 ).pack(padx=24, pady=(0,12), anchor="w")

        # Lista cartelle
        list_fr = tk.Frame(f, bg=PANEL_COLOR)
        list_fr.pack(fill="both", expand=True, padx=20, pady=(0,8))
        list_fr.columnconfigure(0, weight=1)
        list_fr.rowconfigure(0, weight=1)
        lb = tk.Listbox(list_fr, bg=PANEL_COLOR, fg=TEXT_COLOR,
                        selectbackground=HIGHLIGHT, selectforeground="white",
                        font=("TkFixedFont", 9), relief="flat",
                        activestyle="none", borderwidth=0)
        sb = ttk.Scrollbar(list_fr, command=lb.yview)
        lb.config(yscrollcommand=sb.set)
        sb.grid(row=0, column=1, sticky="ns")
        lb.grid(row=0, column=0, sticky="nsew")

        def _refresh_list():
            lb.delete(0, tk.END)
            for pf in self.sorter._private_folders:
                unlkd = pf in self.sorter._unlocked_private
                tag = " [sbloccata]" if unlkd else ""
                lb.insert(tk.END, pf + tag)
                lb.itemconfig(tk.END,
                    fg=SUCCESS if unlkd else PRIVACY_RED)
        _refresh_list()

        # DnD: trascina cartella sulla lista
        if _TKDND_OK:
            _dnd_register(lb,
                lambda dropped: _add_private(
                    dropped[0] if isinstance(dropped, list) else dropped))

        def _add_private(path):
            if os.path.isfile(path): path = os.path.dirname(path)
            if not os.path.isdir(path): return
            path = os.path.abspath(path)
            if path not in self.sorter._private_folders:
                self.sorter._private_folders.append(path)
                _save_private_folders(self.sorter._private_folders)
                _refresh_list()

        def _remove_sel():
            sel = lb.curselection()
            if not sel: return
            item = lb.get(sel[0]).replace(" [sbloccata]","")
            if item in self.sorter._private_folders:
                self.sorter._private_folders.remove(item)
                _save_private_folders(self.sorter._private_folders)
            if item in self.sorter._unlocked_private:
                self.sorter._unlocked_private.discard(item)
            _refresh_list()

        def _reset_all():
            self.sorter._private_folders.clear()
            self.sorter._unlocked_private.clear()
            _save_private_folders([])
            _refresh_list()

        # Bottoni
        btn_fr = tk.Frame(f, bg=BG_COLOR)
        btn_fr.pack(fill="x", padx=20, pady=(0,16))

        tk.Button(btn_fr, text="+ Aggiungi cartella",
                  font=("TkFixedFont", 8), bg=ACCENT_COLOR, fg=TEXT_COLOR,
                  relief="flat", padx=10,
                  command=lambda: _add_private(
                      browse_folder_hud(self.win,
                          title="Scegli cartella privata") or "")
                  ).pack(side="left", padx=(0,6), ipady=3)

        tk.Button(btn_fr, text="Rimuovi selezionata",
                  font=("TkFixedFont", 8), bg=WARNING, fg="white",
                  relief="flat", padx=10,
                  command=_remove_sel
                  ).pack(side="left", padx=(0,6), ipady=3)

        tk.Button(btn_fr, text="Svuota lista",
                  font=("TkFixedFont", 8), bg="#c0392b", fg="white",
                  relief="flat", padx=10,
                  command=_reset_all
                  ).pack(side="left", ipady=3)

        # Seconda riga bottoni
        btn_fr2 = tk.Frame(f, bg=BG_COLOR)
        btn_fr2.pack(fill="x", padx=20, pady=(0,8))

        def _unlock_session():
            """Sblocca tutte le cartelle private per la sessione corrente."""
            for pf in self.sorter._private_folders:
                self.sorter._unlocked_private.add(pf)
            _refresh_list()
            status_lbl.config(
                text="Tutte le cartelle sbloccate per questa sessione.")

        tk.Button(btn_fr2, text="Sblocca tutto per questa sessione",
                  font=("TkFixedFont", 8), bg=SUCCESS, fg="white",
                  relief="flat", padx=10,
                  command=_unlock_session
                  ).pack(side="left", ipady=3)

        # Stato sessione
        n_tot  = len(self.sorter._private_folders)
        n_unlk = len(self.sorter._unlocked_private)
        status_lbl = tk.Label(f,
                 text=f"{n_tot} cartelle private  |  "
                      f"{n_unlk} sbloccate questa sessione",
                 font=("TkFixedFont", 7), bg=BG_COLOR, fg=MUTED_COLOR)
        status_lbl.pack(padx=24, pady=(0,8), anchor="w")

        # Hint DnD
        if _TKDND_OK:
            tk.Label(f,
                     text="Trascina una cartella sulla lista per aggiungerla.",
                     font=("TkFixedFont", 7), bg=BG_COLOR, fg=MUTED_COLOR
                     ).pack(padx=24, pady=(0,12), anchor="w")

    def _build_history_tab(self):
        """Tab Storico: lista operazioni persistente con undo selettivo."""
        f = self._content
        f.rowconfigure(1, weight=1)
        f.columnconfigure(0, weight=1)
        _lang = self.config.get("language", "it")

        # Intestazione
        hdr = tk.Frame(f, bg=BG_COLOR)
        hdr.grid(row=0, column=0, sticky="ew", padx=12, pady=(10,4))
        tk.Label(hdr, text=T("tab_history", _lang).strip(),
                 font=("TkFixedFont", 10, "bold"),
                 bg=BG_COLOR, fg=HUD_CYAN).pack(side="left")
        # Area scrollabile
        outer = tk.Frame(f, bg=BG_COLOR)
        outer.grid(row=1, column=0, sticky="nsew", padx=12, pady=(0,8))
        outer.rowconfigure(0, weight=1)
        outer.columnconfigure(0, weight=1)
        canvas = tk.Canvas(outer, bg=BG_COLOR, highlightthickness=0)
        vsb    = tk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        def _scroll(e):
            canvas.yview_scroll(-1 if e.num == 4 else 1, "units")
        canvas.bind("<Button-4>", _scroll)
        canvas.bind("<Button-5>", _scroll)
        rows_frame = tk.Frame(canvas, bg=BG_COLOR)
        canvas_win = canvas.create_window((0,0), window=rows_frame, anchor="nw")
        _populated = [False]

        def _update_scrollregion(e=None):
            # Aggiorna scrollregion solo dopo il primo populate
            if not _populated[0]:
                return
            canvas.update_idletasks()
            h = rows_frame.winfo_reqheight()
            w = canvas.winfo_width() or rows_frame.winfo_reqwidth()
            if h > 0:
                canvas.configure(scrollregion=(0, 0, w, h))

        def _on_canvas_configure(e):
            canvas.itemconfig(canvas_win, width=e.width)
            _update_scrollregion()

        rows_frame.bind("<Configure>", _update_scrollregion)
        canvas.bind("<Configure>", _on_canvas_configure)

        def _bind_scroll(widget):
            """Propaga scroll wheel dal widget al canvas."""
            widget.bind("<Button-4>", _scroll, add=True)
            widget.bind("<Button-5>", _scroll, add=True)
            for child in widget.winfo_children():
                _bind_scroll(child)

        def _populate_after():
            self._history_populate(rows_frame, _lang)
            canvas.update_idletasks()
            _populated[0] = True
            h = rows_frame.winfo_reqheight()
            w = canvas.winfo_width() or rows_frame.winfo_reqwidth()
            canvas.configure(scrollregion=(0, 0, w, max(h, 1)))
            canvas.yview_moveto(0)
            # Propaga scroll a tutti i widget figli
            _bind_scroll(rows_frame)

        # Popola subito: _switch_tab tiene nascosta l'intera area contenuto
        # (grid_remove) finché il tab non è completamente pronto, quindi
        # non serve più rimandare il popolamento per evitare un "vuoto poi
        # pieno" visibile — update_idletasks() dentro _populate_after
        # garantisce comunque che la geometria del canvas sia corretta.
        _populate_after()

        # Sezione backup crop
        f.rowconfigure(2, weight=0)
        bak_frame = tk.Frame(f, bg=PANEL_COLOR)
        bak_frame.grid(row=2, column=0, sticky="ew", padx=12, pady=(0,8))
        bak_frame.columnconfigure(1, weight=1)

        # Riga 0: etichetta + dimensione + limite + bottoni azione
